def _write_crash_log(exc_type, exc_value, exc_tb):
    try:
        _crash_path = os.path.join(_log_output_dir(), "crash_log.txt")
        import traceback as _tb
        with open(_crash_path, "a", encoding="utf-8") as _f:
            _f.write(f"\n=== CRASH {datetime.datetime.now().isoformat()} ===\n")
            _tb.print_exception(exc_type, exc_value, exc_tb, file=_f)
    except Exception:
        pass
    try:
        import traceback as _tb
        _formatted = "".join(_tb.format_exception(exc_type, exc_value, exc_tb))
        log.critical("=== CRASH ===\n%s", _formatted)
    except Exception:
        pass
    sys.__excepthook__(exc_type, exc_value, exc_tb)

def _thread_crash_hook(args):
    _write_crash_log(args.exc_type, args.exc_value, args.exc_traceback)

def _write_crash_log_main_thread(exc_type, exc_value, exc_tb):
    _write_crash_log(exc_type, exc_value, exc_tb)
    try:
        _attempt_self_relaunch()
    except NameError:
        pass
    except Exception as _relaunch_err:
        try:
            log.warning("_write_crash_log_main_thread: relaunch attempt failed: %s", _relaunch_err)
        except Exception:
            pass

sys.excepthook = _write_crash_log_main_thread
threading.excepthook = _thread_crash_hook

def _app_log_namer(default_name):
    directory = os.path.dirname(default_name)
    fname = os.path.basename(default_name)
    root, num = os.path.splitext(fname)
    if num[1:].isdigit():
        stem, txt_ext = os.path.splitext(root)
        return os.path.join(directory, f"{stem}{num[1:]}{txt_ext}")
    return default_name

try:
    _app_log_dir = _log_output_dir()
    _app_log_path = os.path.join(_app_log_dir, "app_log.txt")
    _app_log_handler = logging.handlers.RotatingFileHandler(
        _app_log_path, maxBytes=2 * 1024 * 1024, backupCount=3, encoding="utf-8")
    _app_log_handler.namer = _app_log_namer
    _app_log_handler.setFormatter(logging.Formatter(
        "%(asctime)s [%(levelname)s] %(name)s: %(message)s"))

    _log_queue = queue.Queue(maxsize=10000)
    _queue_handler = logging.handlers.QueueHandler(_log_queue)

    _root_logger = logging.getLogger()
    _root_logger.setLevel(logging.INFO)
    _root_logger.addHandler(_queue_handler)

    _log_listener = logging.handlers.QueueListener(
        _log_queue, _app_log_handler, respect_handler_level=False)
    _log_listener.start()
except Exception:
    pass

