def _log_boot_environment_fingerprint():
    """One-time log of the machine's OS/CPU/RAM/process bit-width at boot,
    so a community tester's crash/hang/stutter report can be diagnosed
    without asking them to describe their PC by hand. Best-effort: any
    piece that fails to read is logged as "unknown" rather than blocking
    startup."""
    import platform as _platform
    _os_str = "unknown"
    try:
        _os_str = _platform.platform()
    except Exception:
        pass
    _cpu_count = os.cpu_count() or "unknown"
    _bit_width = ctypes.sizeof(ctypes.c_void_p) * 8
    _ram_str = "unknown"
    if os.name == "nt":
        try:
            class _MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("sullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]
            _mem = _MEMORYSTATUSEX()
            _mem.dwLength = ctypes.sizeof(_MEMORYSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(_mem)):
                _ram_str = (f"{_mem.ullTotalPhys / (1024 ** 3):.1f}GB total, "
                            f"{_mem.ullAvailPhys / (1024 ** 3):.1f}GB available")
        except Exception:
            pass
    log.info("[BOOT ENV] OS=%s | CPU cores=%s | RAM=%s | Process=%s-bit",
              _os_str, _cpu_count, _ram_str, _bit_width)


_log_boot_environment_fingerprint()

_SINGLE_INSTANCE_HANDLE = None  # kept alive for the whole process lifetime

def _acquire_single_instance():
    global _SINGLE_INSTANCE_HANDLE
    if os.name != "nt":
        return True
    try:
        import ctypes
        from ctypes import wintypes
        ERROR_ALREADY_EXISTS = 183
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        # Set restype so the 64-bit HANDLE isn't truncated to a 32-bit int.
        kernel32.CreateMutexW.restype = wintypes.HANDLE
        kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        mutex_name = "RetroTVEmulator_SingleInstance_Mutex"
        # Allow a previous instance to finish shutting down before retrying.
        import time as _time
        _deadline = _time.time() + 3.0
        while True:
            handle = kernel32.CreateMutexW(None, True, mutex_name)
            last_err = ctypes.get_last_error()
            if not handle:
                # Couldn't create the mutex at all -> don't block startup.
                return True
            if last_err != ERROR_ALREADY_EXISTS:
                _SINGLE_INSTANCE_HANDLE = handle  # hold the handle so the lock persists
                return True
            kernel32.CloseHandle(handle)
            if _time.time() >= _deadline:
                return False
            _time.sleep(0.2)
    except Exception as _e:
        log.warning("[SINGLE INSTANCE] guard failed (%s) -- launching anyway", _e)
        return True

if __name__ == "__main__":
    if not _acquire_single_instance():
        log.info("[SINGLE INSTANCE] Another instance is already running -- exiting this duplicate launch.")
        sys.exit(0)

_CHILD_PROCESS_JOB_HANDLE = None  # kept alive for the whole process lifetime

def _setup_child_process_job_object():
    """Ties every child process this app ever spawns (ffmpeg/ffprobe probes
    running in background threads, the game-deck emulator, etc.) to this
    process's lifetime via a Windows Job Object with
    JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE.

    Without this, a background probe's ffmpeg.exe (or an emulator launched
    through game_deck) can still be running the instant this process exits --
    whether that's a normal shutdown, a crash, or the heartbeat watchdog's
    os._exit(1) force-relaunch -- and Windows does NOT automatically kill
    orphaned child processes. An orphan like that can sit holding a file
    handle open inside the media library, which blocks renaming/deleting/
    overwriting that folder until the orphan finishes or is killed by hand.

    With the job object in place, the moment this process ends for ANY
    reason, Windows itself force-kills every child still running -- no
    per-subprocess-call bookkeeping needed, and it still works even on a
    hard os._exit() that skips all normal Python cleanup.
    """
    global _CHILD_PROCESS_JOB_HANDLE
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes

        JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x2000
        # Allow a child to explicitly opt out of this job (via
        # CREATE_BREAKAWAY_FROM_JOB at spawn time) instead of silently
        # inheriting membership in it. Needed so _attempt_self_relaunch()'s
        # replacement process isn't itself killed the instant this process's
        # job handle closes on exit/crash -- without this flag, Windows adds
        # every child (including the intentional relaunch) to this same job
        # by default, and JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE then kills it
        # along with everything else the moment we exit.
        JOB_OBJECT_LIMIT_BREAKAWAY_OK = 0x0800
        JobObjectExtendedLimitInformation = 9

        class _IO_COUNTERS(ctypes.Structure):
            _fields_ = [
                ("ReadOperationCount", ctypes.c_uint64),
                ("WriteOperationCount", ctypes.c_uint64),
                ("OtherOperationCount", ctypes.c_uint64),
                ("ReadTransferCount", ctypes.c_uint64),
                ("WriteTransferCount", ctypes.c_uint64),
                ("OtherTransferCount", ctypes.c_uint64),
            ]

        class _JOBOBJECT_BASIC_LIMIT_INFORMATION(ctypes.Structure):
            _fields_ = [
                ("PerProcessUserTimeLimit", ctypes.c_int64),
                ("PerJobUserTimeLimit", ctypes.c_int64),
                ("LimitFlags", wintypes.DWORD),
                ("MinimumWorkingSetSize", ctypes.c_size_t),
                ("MaximumWorkingSetSize", ctypes.c_size_t),
                ("ActiveProcessLimit", wintypes.DWORD),
                ("Affinity", ctypes.c_size_t),
                ("PriorityClass", wintypes.DWORD),
                ("SchedulingClass", wintypes.DWORD),
            ]

        class _JOBOBJECT_EXTENDED_LIMIT_INFORMATION(ctypes.Structure):
            _fields_ = [
                ("BasicLimitInformation", _JOBOBJECT_BASIC_LIMIT_INFORMATION),
                ("IoInfo", _IO_COUNTERS),
                ("ProcessMemoryLimit", ctypes.c_size_t),
                ("JobMemoryLimit", ctypes.c_size_t),
                ("PeakProcessMemoryUsed", ctypes.c_size_t),
                ("PeakJobMemoryUsed", ctypes.c_size_t),
            ]

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateJobObjectW.restype = wintypes.HANDLE
        kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        kernel32.SetInformationJobObject.argtypes = [
            wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
        kernel32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE

        job = kernel32.CreateJobObjectW(None, None)
        if not job:
            log.warning("[SHUTDOWN GUARD] CreateJobObjectW failed (err=%s) -- "
                        "orphaned ffmpeg/emulator processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            return

        info = _JOBOBJECT_EXTENDED_LIMIT_INFORMATION()
        info.BasicLimitInformation.LimitFlags = (
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE | JOB_OBJECT_LIMIT_BREAKAWAY_OK
        )
        if not kernel32.SetInformationJobObject(
                job, JobObjectExtendedLimitInformation,
                ctypes.byref(info), ctypes.sizeof(info)):
            log.warning("[SHUTDOWN GUARD] SetInformationJobObject failed (err=%s) -- "
                        "orphaned ffmpeg/emulator processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            kernel32.CloseHandle(job)
            return

        if not kernel32.AssignProcessToJobObject(job, kernel32.GetCurrentProcess()):
            log.warning("[SHUTDOWN GUARD] AssignProcessToJobObject failed (err=%s) -- "
                        "orphaned ffmpeg/emulator processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            kernel32.CloseHandle(job)
            return

        _CHILD_PROCESS_JOB_HANDLE = job  # keep the handle alive for the process lifetime
        log.info("[SHUTDOWN GUARD] Child-process job object active -- ffmpeg/ffprobe "
                  "and emulator child processes will be force-killed if this app "
                  "exits for any reason.")
    except Exception as e:
        log.warning("[SHUTDOWN GUARD] Failed to set up child-process job object: %s -- "
                    "orphaned ffmpeg/emulator processes will NOT be cleaned up "
                    "automatically on exit.", e)

def _hard_exit_process(code):
    """Terminate this process immediately, bypassing Windows' normal DLL
    unload sequence -- unlike os._exit()/sys.exit().

    os._exit() ultimately reaches the OS's own ExitProcess(), and
    ExitProcess() runs every loaded DLL's DLL_PROCESS_DETACH cleanup on
    the exiting thread *before* the process actually dies. If libvlc.dll
    (or one of its access-plugin DLLs) is mid-teardown of a decode/demux
    thread that's itself stuck in a blocking file read against an
    unresponsive/disconnected drive, that DLL_PROCESS_DETACH wait has no
    timeout of its own -- ExitProcess() simply never returns, and the
    process sits there forever even though os._exit() was already called.
    This is exactly what happened when a network/USB drive went
    unresponsive mid-playback: the WEDGED-TEARDOWN watchdogs correctly
    caught and logged the stuck player.stop()/release() within 5s each,
    but the subsequent os._exit(0) still hung indefinitely inside
    ExitProcess() itself, leaving the process alive (and its log file
    locked) even after the window/console was closed by hand.

    TerminateProcess(), called directly via ctypes, is a different OS
    primitive: per Windows' own documentation it does NOT invoke
    DLL_PROCESS_DETACH for any attached DLL, so a DLL stuck waiting on a
    dead drive can't block it. Falls back to os._exit() on any failure
    (including non-Windows platforms, where this whole class of hang
    doesn't apply)."""
    try:
        if os.name == "nt":
            _k32 = ctypes.windll.kernel32
            _k32.TerminateProcess(_k32.GetCurrentProcess(), code)
    except Exception:
        pass
    # Only reached if TerminateProcess itself failed to fire (or we're not
    # on Windows) -- fall back to the previous behavior rather than never
    # exiting at all.
    os._exit(code)


if __name__ == "__main__":
    _setup_child_process_job_object()

import builtins as _builtins
_original_print = _builtins.print

def _logged_print(*args, **kwargs):
    try:
        _original_print(*args, **kwargs)
    except Exception:
        pass  # no console to write to (or a closed one) -- fine, log below still captures it
    try:
        _msg = " ".join(str(a) for a in args)
        log.info(_msg)
    except Exception:
        pass

_builtins.print = _logged_print

_throttled_log_last_ts = {}
_THROTTLED_LOG_INTERVAL_S = 30.0

def _log_warn_throttled(_key, msg, *args, **_kwargs):
    _now = time.monotonic()
    if _now - _throttled_log_last_ts.get(_key, -1e9) >= _THROTTLED_LOG_INTERVAL_S:
        _throttled_log_last_ts[_key] = _now
        log.warning(msg, *args)


def _log_info_throttled(_key, msg, *args, **_kwargs):
    _now = time.monotonic()
    if _now - _throttled_log_last_ts.get(_key, -1e9) >= _THROTTLED_LOG_INTERVAL_S:
        _throttled_log_last_ts[_key] = _now
        log.info(msg, *args)


if sys.platform == "win32":
    try:
        ctypes.windll.shcore.SetProcessDpiAwareness(2)
    except Exception:
        try:
            ctypes.windll.user32.SetProcessDPIAware()
        except Exception as _dpi_err:
            log.warning(f"Could not set DPI awareness: {_dpi_err}")

    # Stop Windows from popping its own blocking "Bad Image" / "This app can't
    # run" system dialogs whenever a native DLL fails to load (bad core file,
    # wrong architecture, missing dependency, etc). Those dialogs are modal
    # and freeze our whole message loop -- LoadLibrary failures should just
    # raise back into our own Python try/except (see libretro_core.load_dll)
    # so we can log it and fall back gracefully instead of hanging the app.
    try:
        SEM_FAILCRITICALERRORS = 0x0001
        SEM_NOGPFAULTERRORBOX  = 0x0002
        SEM_NOOPENFILEERRORBOX = 0x8000
        ctypes.windll.kernel32.SetErrorMode(
            SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX | SEM_NOOPENFILEERRORBOX
        )
    except Exception as _errmode_err:
        log.warning(f"Could not set SetErrorMode: {_errmode_err}")

