_BEZEL_CHANNEL_LED_TILT_DEG = {
    "bezel":  -2.0,
    "bezel1": -2.0,
}
_BEZEL_CHANNEL_LED_TILT_DEG_DEFAULT = 0.0

# Extra width added to the black hide-patch on its right edge only, as a
# fraction of the fitted font height (_fit_h) so it scales with the
# readout instead of staying a fixed pixel count -- a fixed-pixel extend
# is barely noticeable at full screen but reads as oversized once the
# window (and therefore the readout/font) shrinks on a smaller/minimized
# window. Per-style hand-tuning for when the patch still clips the live
# text's own right edge or leaves a sliver of the art's baked-in readout
# showing on that side.
_BEZEL_CHANNEL_LED_HIDE_RIGHT_EXTEND_FRAC = {
    "bezel":  0.65,
    "bezel1": 0.0,
}
_BEZEL_CHANNEL_LED_HIDE_RIGHT_EXTEND_FRAC_DEFAULT = 0.0

# Extra width added to the black hide-patch on its left edge only (right
# edge stays put), same fit_h-relative scaling as the right-extend above.
_BEZEL_CHANNEL_LED_HIDE_LEFT_EXTEND_FRAC = {
    "bezel":  0.22,
    "bezel1": 0.0,
}
_BEZEL_CHANNEL_LED_HIDE_LEFT_EXTEND_FRAC_DEFAULT = 0.0

# Extra height added to the black hide-patch on its bottom edge only, same
# fit_h-relative scaling as the right/left-extends above (top edge stays
# put).
_BEZEL_CHANNEL_LED_HIDE_DOWN_EXTEND_FRAC = {
    "bezel":  0.65,
    "bezel1": 0.0,
}
_BEZEL_CHANNEL_LED_HIDE_DOWN_EXTEND_FRAC_DEFAULT = 0.0

# Fine trim pulling the black hide-patch's bottom edge upward, as a
# fraction of the fitted font height (_fit_h) -- top edge stays put --
# so it scales down with the readout at smaller/minimized window sizes
# instead of staying a fixed pixel count (which drifted the patch off
# position once the window was no longer full screen). Applied after
# the down-extend above, so this is a final, style-specific nudge on
# top of it. Per-style hand-tuning against each bezel's actual readout
# window, at full screen.
_BEZEL_CHANNEL_LED_HIDE_BOTTOM_TRIM_FRAC = {
    "bezel":  0.061,   # sunlit-room CRT photo (Bezel Option 1 / "bezel.png")
}
_BEZEL_CHANNEL_LED_HIDE_BOTTOM_TRIM_FRAC_DEFAULT = 0.0

# Fine trim pulling the black hide-patch's right edge leftward, same
# fit_h-relative scaling as the bottom-trim above -- left edge stays put.
_BEZEL_CHANNEL_LED_HIDE_RIGHT_TRIM_FRAC = {
    "bezel":  0.061,   # sunlit-room CRT photo (Bezel Option 1 / "bezel.png")
}
_BEZEL_CHANNEL_LED_HIDE_RIGHT_TRIM_FRAC_DEFAULT = 0.0

# Fine push of the black hide-patch's left edge further leftward, same
# fit_h-relative scaling as the trims above -- right edge stays put.
_BEZEL_CHANNEL_LED_HIDE_LEFT_EXTRA_FRAC = {
    "bezel":  0.061,   # sunlit-room CRT photo (Bezel Option 1 / "bezel.png")
    "bezel1": 0.241,   # plain grey/black frame (Bezel Option 2 / "bezel1.png")
}
_BEZEL_CHANNEL_LED_HIDE_LEFT_EXTRA_FRAC_DEFAULT = 0.0

# Whole-patch nudge (moves the black hide-patch as a rigid unit, size
# unchanged) in real (non-supersampled) pixels. Positive x = right,
# positive y = down. Does NOT touch the live "CH NN" text position (see
# _BEZEL_CHANNEL_LED_TEXT_X_NUDGE_PX / _TEXT_Y_NUDGE_PX for that).
# bezel1: the CH/number gap-frac and num-scale change (see
# _BEZEL_CHANNEL_LED_GAP_FRAC / _NUM_SCALE_FRAC) shifted where the patch
# landed relative to the number; this pushes it back (right 1, down 1)
