clock = pygame.time.Clock()

# Named default fallbacks for the pacing rules in _resolve_main_loop_tick_fps
# below -- kept as constants (not magic numbers inline) so the *intent*
# behind each number is visible at a glance and grep-able if a future
# change needs to touch pacing again.
_GAME_CORE_FPS_FALLBACK = 60.0     # used only if a libretro core reports
                                    # something outside the sane guard band
_GAME_CORE_FPS_GUARD = (40.0, 120.0)
_UI_COMPOSITOR_FPS = 60.0          # TV / DVD / Media / menus: paces input
                                    # polling, OSD/caption/overlay redraw,
                                    # and pygame.display.flip() -- NOT the
                                    # video content itself (see note below)


def _resolve_main_loop_tick_fps(game_deck_ref):
    """Single source of truth for how fast clock.tick() paces the main
    loop, made explicit per-mode instead of leaving the reasoning
    scattered inline. There are exactly two regimes, and they are NOT
    interchangeable:

    1. GAME mode with a live libretro core: tick pacing IS the emulation
       clock. It must match the core's real reported native rate
       (e.g. ~59.73Hz for GB/GBC/GBA, ~60.0988Hz for NES/SNES/N64), not a
       flat 60.0 -- real hardware rates are fractional, and pacing a core
       at a slightly-wrong flat 60 causes slow audio/video drift over a
       play session (small at first, audible after 10-20+ minutes). Only
       fall back to _GAME_CORE_FPS_FALLBACK if the core's reported fps is
       missing or clearly bogus (outside _GAME_CORE_FPS_GUARD).

    2. Everything else -- TV stations, DVD player, Media player, menus:
       tick pacing here only controls how often THIS loop polls input,
       redraws OSD/captions/watermark/static-noise/reception-lines, and
       flips the display. It does NOT control the video content's frame
       rate. VLC decodes and delivers frames on its own thread via
       video_set_callbacks, and RetroDatabase/VLCEngine.get_display_frame()
       already gates the expensive buffer-copy-under-lock on VLC's own
       self._frame_ready flag -- so a genuinely new video frame is only
       pulled off the wire at VLC's real native decode cadence
       (23.976/25/29.97/etc, whatever the source file is), no matter how
       fast this loop spins. Lowering _UI_COMPOSITOR_FPS to "match" the
       video would not smooth video playback (it was never coupled to
       this tick rate) -- it would only make input response and
       OSD/overlay redraws choppier. Keep this at a flat UI-responsive
       rate for every non-GAME mode; do not tie it to source video fps.
    """
    if (game_deck_ref is not None
            and getattr(game_deck_ref, "mode", None) == "GAME"
            and getattr(game_deck_ref, "_libretro_core", None) is not None
            and not getattr(game_deck_ref, "emulator_loading", False)):
        try:
            core_fps = float(game_deck_ref._libretro_core.fps)
            lo, hi = _GAME_CORE_FPS_GUARD
            if lo <= core_fps <= hi:
                return core_fps
        except Exception as e:
            _log_warn_throttled(
                "core_fps_tick_pacing",
                "Per-frame core.fps lookup for tick pacing failed, using %.1f: %s",
                _GAME_CORE_FPS_FALLBACK, e)
        return _GAME_CORE_FPS_FALLBACK
    return _UI_COMPOSITOR_FPS

_rt_font_cache = {}
def _cached_sys_font(name, size, bold=False):
    k = (name, size, bold)
    if k not in _rt_font_cache:
        _rt_font_cache[k] = pygame.font.SysFont(name, size, bold=bold)
    return _rt_font_cache[k]


STATUS_BANNER_DURATION_MS = 30000  # each active status banner below gets

_drive_streak_signature = None
_drive_streak_consumed  = False  # True once THIS streak has already had
                                  # its one full turn in the slot
_drive_streak_consumed_at = None # ticks when the current streak was consumed

# Re-arm the drive banner after a quiet interval.
_DRIVE_BANNER_REARM_MS = 5 * 60 * 1000  # 5 minutes

_gamepad_streak_signature = None
_gamepad_streak_consumed  = False

# Same re-arm cadence as the drive banner (see _DRIVE_BANNER_REARM_MS) --
# an unresolved missing-media condition is the same kind of "ongoing
# problem" as an unresponsive drive, not a one-off blip, so it deserves
# the same periodic reminder instead of showing once per session and
# then going permanently silent.
_MISSING_MEDIA_BANNER_REARM_MS = 5 * 60 * 1000  # 5 minutes

_missing_media_streak_signature = None  # (channel, reason, reason_detail) or None -- despite
                                         # the "missing_media" name this now covers every
                                         # non-silent Static fallback reason (see
                                         # STATIC_FALLBACK_BANNER_PREFIX / SILENT_STATIC_REASONS)
_missing_media_streak_consumed  = False
_missing_media_streak_consumed_at = None
_missing_media_streak_label = None

# Set once per frame by the Static/missing_media render branch via
# _report_missing_media() -- (signature, label) tuple, or None once
# resolved/not currently on screen. _advance_status_banner_streaks() reads
# this each frame to decide whether the condition is new, ongoing, or
# cleared, the same way it polls _unresponsive_drive_roots() for the
# drive banner.
_missing_media_live_report = None

# A connected User gets the same shared banner treatment as drive/media
# failures.  The transport reports "offline" after its bounded socket read
# timeout, and a locked-channel playback failure is treated as a second
# server-health signal even if the control connection has not failed yet.
_SERVER_BANNER_REARM_MS = 5 * 60 * 1000
_server_streak_signature = None
_server_streak_consumed = False
_server_streak_consumed_at = None


def _report_missing_media(signature, label):
    """Called once per frame from the main render loop (see content_rect
    setup above and the Static/missing_media branch) to hand the current
    missing-media condition -- or None, once resolved/not on screen -- to
    the shared status-banner system, instead of drawing a banner directly
    on the spot. Routing it through here is what lets it share
    _draw_status_banner_bar's exact position and Bezel-composite handling
    with the drive/gamepad banners, and get its own real 30s
    STATUS_BANNER_DURATION_MS turn (see _advance_status_banner_streaks)."""
    global _missing_media_live_report
    _missing_media_live_report = (signature, label) if signature is not None else None


_status_banner_current    = None   # "drive" | "gamepad" | "missing_media" | None
                                    # -- whichever one currently owns the
                                    # shared slot
_status_banner_started_at = None   # ticks when it started owning it


def _active_playback_drive_roots():
    """Drive roots actually backing whatever's on screen right now (the
    main engine's, DVD engine's, and active game engine's current file), so the drive
    banner can be scoped to the channel that's really reading from the
    dead/unresponsive drive instead of lighting up on every channel the
    instant ANY drive anywhere on the system goes unresponsive. A channel
    with nothing currently open on any engine (game/visualizer
    channels, or a video channel that hasn't started playback yet)
    contributes no roots here, so it never trips the banner on its own.

    The Guide (channel 04) is a special case even though it DOES touch
    vlc_engine: its live preview thumbnail loads whichever channel is
    currently highlighted into the same shared vlc_engine purely to render
    a thumbnail (see _start_guide_preview_load's docstring -- "Guide
    previews share the single live vlc_engine with full-screen playback").
    That's just browsing, not the player committing to watch that channel,
    so without this exclusion, arrowing past a channel backed by a dead
    drive would light up CHECK YOUR DRIVE over the grid itself. The guide
    already has its own per-row way of surfacing a dead channel
    (_register_channel_playback_failure / _station_confirmed_dead_drive),
    so the shared banner is suppressed entirely while on the guide.
    """
    if str(globals().get("app_state", {}).get("current_channel", "")) == "04":
        return set()

    roots = set()

    # current_filepath is set once, the moment a file is opened, and is
    # NEVER cleared back to None/"" anywhere -- not on stop(), not on
    # leaving the channel, not on release(). So on its own it's sticky:
    # once you've ever watched anything from a drive, it keeps pointing
    # at that same last file indefinitely, and a dead-drive root would
    # keep tripping this banner on every other channel (games, audio-only,
    # anything) forever, long after that file stopped being relevant.
    # Gate each engine on its own separate "is this genuinely live right
    # now" flag instead of trusting current_filepath by itself:
    #  - vlc_engine: app_state["_live_playback_channel"] is the one place
    #    that's deliberately kept in sync with "is real scheduled content
    #    actually loaded in vlc_engine right now" -- change_channel()
    #    clears it to "" the instant it leaves a channel that had real
    #    content going (see its own comment at the assignment site), so an
    #    empty value here reliably means vlc_engine's current_filepath is
    #    stale leftover from whatever was last watched, not something
    #    actually on screen (e.g. sitting on the Games channel).
    #  - dvd_engine: game_deck.dvd_playback_active is the equivalent
    #    signal for a genuinely still-open DVD session; it's set True only
    #    while a disc is actually playing (including backgrounded/muted
    #    on channel leave) and flips back to False once that session has
    #    really ended, unlike current_filepath which would otherwise keep
    #    pointing at whatever disc played last, forever.
    if vlc_engine is not None and globals().get("app_state", {}).get("_live_playback_channel"):
        _fp = getattr(vlc_engine, "current_filepath", None)
        if _fp:
            _root = media._drive_root_of(_fp)
            if _root:
                roots.add(_root)
    _game_deck = globals().get("game_deck")
    if dvd_engine is not None and getattr(_game_deck, "dvd_playback_active", False):
        _fp = getattr(dvd_engine, "current_filepath", None)
        if _fp:
            _root = media._drive_root_of(_fp)
            if _root:
                roots.add(_root)

    # Channel 03 is also the libretro game surface.  Do not use
    # active_console or mode alone here: channel 03 opens on the console
    # picker/ROM list, and a dead drive containing merely-listed ROMs must
    # not light the shared banner.  _libretro_rom_path is written only after
    # a ROM has actually been accepted by the core, so it is the precise
    # "a game is currently loaded from this path" signal.
    if (_game_deck is not None
            and getattr(_game_deck, "mode", "") == "GAME"
            and getattr(_game_deck, "_libretro_core", None) is not None):
        _fp = getattr(_game_deck, "_libretro_rom_path", None)
        if _fp:
            _root = media._drive_root_of(_fp)
            if _root:
                roots.add(_root)

    # A TV/Visualizer tune-in can fail fast before the OS health monitor has
    # had a chance to mark the root unresponsive.  The channel-specific
    # confirmed-dead maps are still authoritative for the channel currently
    # on screen, but must not leak onto unrelated channels (or the normal
    # Channel 03 picker).
    _cur_ch = str(globals().get("app_state", {}).get("current_channel", "")).zfill(2)
    if _cur_ch not in ("03", "04"):
        for _dead_map in (
                globals().get("_station_confirmed_dead_drive", {}),
                globals().get("_visualizer_confirmed_dead_drive", {})):
            _root = _dead_map.get(_cur_ch)
            if _root:
                roots.add(_root)

    # A live Visualizer channel never touches vlc_engine/dvd_engine at all --
    # it plays through pygame.mixer.music -- so without this it contributed
    # no roots here whatsoever, and a Visualizer channel stuck on a dead
    # drive could never trip the "CHECK YOUR DRIVE" banner no matter how
    # long it stayed on that channel. The render loop refreshes
    # _vis_target_filepath every frame it's actually showing a Visualizer
    # channel (see the "Visualizer" branch below) to whatever file that
    # channel's schedule says should be playing right now, independent of
    # whether the load attempt for it actually succeeded, so this stays
    # accurate through both "briefly flashed, now static" and "already
    # known dead, straight to static" visits alike.
    _vis_fp = globals().get("app_state", {}).get("_vis_target_filepath", "")
    if _vis_fp:
        _root = media._drive_root_of(_vis_fp)
        if _root:
            roots.add(_root)
    return roots


def _return_active_game_to_romlist_if_drive_failed():
    """Bail out of a loaded Channel-03 ROM when its source drive is dead.

    Merely opening Channel 03 is not enough to trigger this: the game deck
    must be in GAME mode with a core-loaded ROM path.  That distinction keeps
    the console picker/ROM list usable when it contains entries from a drive
    that is currently unplugged.
    """
    _game_deck = globals().get("game_deck")
    if (_game_deck is None
            or str(globals().get("app_state", {}).get("current_channel", "")).zfill(2) != "03"
            or getattr(_game_deck, "mode", "") != "GAME"
            or getattr(_game_deck, "emulator_loading", False)):
        return False
    _fp = getattr(_game_deck, "_libretro_rom_path", None)
    if not _fp:
        return False
    try:
        _root = media._drive_root_of(_fp)
        if not _root or _root not in _unresponsive_drive_roots():
            return False
    except Exception as _e:
        log.warning("Active game drive-health fallback check failed: %s", _e)
        return False
    try:
        _handled = _game_deck.return_active_rom_to_list_for_drive_failure()
        if _handled:
            log.warning(
                "[LIBRETRO] Active ROM source drive %s failed; returned to ROM list: %s",
                _root, _fp,
            )
        return bool(_handled)
    except Exception as _e:
        log.warning("Active game drive-health fallback failed: %s", _e)
        return False


def _channel_failure_is_drive_wide(ch_key, entry):
    """Return whether a failure entry belongs to a confirmed-dead drive."""
    if not entry:
        return False
    if str(entry.get("reason", "")).strip().lower() == "drive not responding":
        return True
    _file_path = entry.get("file_path")
    if not _file_path:
        return False
    try:
        _root = media._drive_root_of(_file_path)
        if not _root:
            return False
        return (
            globals().get("_station_confirmed_dead_drive", {}).get(ch_key) == _root
            or globals().get("_visualizer_confirmed_dead_drive", {}).get(ch_key) == _root
        )
    except Exception:
        return False


def _advance_status_banner_streaks():
    global _drive_streak_signature, _drive_streak_consumed, _drive_streak_consumed_at
    global _gamepad_streak_signature, _gamepad_streak_consumed
    global _missing_media_streak_signature, _missing_media_streak_consumed
    global _missing_media_streak_consumed_at, _missing_media_streak_label
    global _server_streak_signature, _server_streak_consumed
    global _server_streak_consumed_at

    _mm = _missing_media_live_report
    if _mm is None:
        _missing_media_streak_signature = None
        _missing_media_streak_consumed = False
        _missing_media_streak_consumed_at = None
        _missing_media_streak_label = None
    else:
        _mm_sig, _mm_label = _mm
        if _mm_sig != _missing_media_streak_signature:
            _missing_media_streak_signature = _mm_sig
            _missing_media_streak_consumed = False
            _missing_media_streak_consumed_at = None
        elif (_missing_media_streak_consumed and _missing_media_streak_consumed_at is not None
                and pygame.time.get_ticks() - _missing_media_streak_consumed_at >= _MISSING_MEDIA_BANNER_REARM_MS):
            _missing_media_streak_consumed = False
            _missing_media_streak_consumed_at = None
        _missing_media_streak_label = _mm_label

    # The schedule client deliberately uses finite connect/read timeouts.  A
    # locked channel can also expose a server-side media reachability failure
    # before the control socket itself notices the outage, so include those
    # channel failures in the same health signal.
    _app = globals().get("app_state", {})
    _remote = _app.get("active_remote_server")
    _remote_status = _app.get("remote_server_status")
    _locked_failures = ()
    try:
        if db is not None:
            _locked_failures = tuple(sorted(
                ch_key for ch_key in _channel_playback_failures
                if db.channels_db.get(ch_key, {}).get("server_locked", False)
            ))
    except Exception:
        _locked_failures = ()
    if _remote is not None and (_remote_status == "offline" or _locked_failures):
        _server_sig = (
            str(_remote.get("name", _remote.get("host", "server"))),
            _remote_status if _remote_status == "offline" else "media",
            _locked_failures,
        )
        if _server_sig != _server_streak_signature:
            _server_streak_signature = _server_sig
            _server_streak_consumed = False
            _server_streak_consumed_at = None
        elif (_server_streak_consumed
              and _server_streak_consumed_at is not None
              and pygame.time.get_ticks() - _server_streak_consumed_at >= _SERVER_BANNER_REARM_MS):
            _server_streak_consumed = False
            _server_streak_consumed_at = None
    else:
        _server_streak_signature = None
        _server_streak_consumed = False
        _server_streak_consumed_at = None

    # Only count a failed drive toward the banner if it's actually one of
    # the drives backing what's currently playing (or the current channel
    # has already confirmed that root dead). Otherwise a dead D:\ would
    # light up the banner on a channel that's reading entirely from C:\.
    _bad_drive_roots = set(_unresponsive_drive_roots())
    _cur_ch = str(_app.get("current_channel", "")).zfill(2)
    if _cur_ch not in ("03", "04"):
        for _dead_map in (
                globals().get("_station_confirmed_dead_drive", {}),
                globals().get("_visualizer_confirmed_dead_drive", {})):
            _root = _dead_map.get(_cur_ch)
            if _root:
                _bad_drive_roots.add(_root)
    roots = frozenset(_bad_drive_roots) & _active_playback_drive_roots()
    # File-specific failures own the per-channel PLAYBACK FAILED banner.
    # Drive-wide failures own CHECK YOUR DRIVE.  A drive failure can still
    # have a registry entry because the channel needs to fall back to real
    # static, so only suppress the shared banner for a genuinely
    # file-specific entry.
    if roots:
        _cur_ch = str(_app.get("current_channel", "")).zfill(2)
        _cur_failure = _channel_playback_failures.get(_cur_ch)
        if (_cur_failure is not None
                and not _channel_failure_is_drive_wide(_cur_ch, _cur_failure)
                and pygame.time.get_ticks() - _cur_failure.get("shown_at", 0) < CHANNEL_FAILURE_MESSAGE_MS):
            roots = frozenset()
    if not roots:
        _drive_streak_signature = None
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None
    elif roots != _drive_streak_signature:
        _drive_streak_signature = roots
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None
    elif (_drive_streak_consumed and _drive_streak_consumed_at is not None
            and pygame.time.get_ticks() - _drive_streak_consumed_at >= _DRIVE_BANNER_REARM_MS):
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None

    try:
        import game_deck
        path = game_deck.gamepad_permission_denied_path()
    except Exception:
        path = None
    if not path:
        _gamepad_streak_signature = None
        _gamepad_streak_consumed = False
    elif path != _gamepad_streak_signature:
        _gamepad_streak_signature = path
        _gamepad_streak_consumed = False


def _status_banner_is_active(name):
    if name == "server":
        return _server_streak_signature is not None
    if name == "drive":
        return _drive_streak_signature is not None
    if name == "gamepad":
        return _gamepad_streak_signature is not None
    if name == "missing_media":
        return _missing_media_streak_signature is not None
    return False


def _status_banner_is_consumed(name):
    if name == "server":
        return _server_streak_consumed
    if name == "drive":
        return _drive_streak_consumed
    if name == "gamepad":
        return _gamepad_streak_consumed
    if name == "missing_media":
        return _missing_media_streak_consumed
    return True


def _mark_status_banner_consumed(name):
    global _drive_streak_consumed, _drive_streak_consumed_at, _gamepad_streak_consumed
    global _missing_media_streak_consumed, _missing_media_streak_consumed_at
    global _server_streak_consumed, _server_streak_consumed_at
    if name == "server":
        _server_streak_consumed = True
        _server_streak_consumed_at = pygame.time.get_ticks()
    elif name == "drive":
        _drive_streak_consumed = True
        _drive_streak_consumed_at = pygame.time.get_ticks()
    elif name == "gamepad":
        _gamepad_streak_consumed = True
    elif name == "missing_media":
        _missing_media_streak_consumed = True
        _missing_media_streak_consumed_at = pygame.time.get_ticks()


def _status_banner_label(name):
    if name == "server" and _server_streak_signature is not None:
        server_name = _server_streak_signature[0]
        return f"SERVER OFFLINE — {server_name}"
    if name == "drive" and _drive_streak_signature is not None:
        roots = _drive_streak_signature
        return "CHECK YOUR DRIVE — " + ", ".join(r.rstrip("\\") for r in roots) + " isn't responding"
    if name == "gamepad" and _gamepad_streak_signature is not None:
        return "CONTROLLER NOT READABLE — add your user to the 'input' group and restart"
    if name == "missing_media" and _missing_media_streak_signature is not None:
        return _missing_media_streak_label
    return None


def _draw_status_banner_bar(screen, label):
    """Draw a shared status banner onto the virtual frame.

    This is intentionally called before CRT/Bezel compositing. The old
    post-composite placement made CHECK YOUR DRIVE (and the other shared
    banners) stay flat while the per-channel failure banner warped with the
    picture. Drawing at virtual-frame size means the normal CRT/Bezel path
    scales and warps the banner together with everything else.
    """
    sw, sh = screen.get_size()
    picture_rect = pygame.Rect(0, 0, sw, sh)
    font_size = 18
    pad_x = 14
    pad_y = 8
    margin = 12
    border_w = 2

    font = _cached_sys_font("Arial", font_size, bold=True)
    text_surf = font.render(label, True, (255, 255, 255))
    bar_w = text_surf.get_width() + pad_x * 2
    bar_h = text_surf.get_height() + pad_y * 2
    bar_w = min(bar_w, picture_rect.width)
    # Box + text composed onto one surface first (rather than blit
    # separately to `screen`) so the Option-3-only correction just below
    # can correct the whole banner -- background box and text together --
    # as a single unit, instead of the box and the text each landing at
    # very slightly different corrected widths.
    bar_surf = pygame.Surface((bar_w, bar_h), pygame.SRCALPHA)
    bar_surf.fill((120, 20, 20, 210))
    pygame.draw.rect(bar_surf, (255, 90, 90, 255), bar_surf.get_rect(), width=border_w)
    bar_surf.blit(text_surf, (pad_x, pad_y))
    # Bezel Option 3 only ("bezel2"): correct for this frame's possible
    # non-uniform scale_x/scale_y -- see _osd_anisotropic_correct's
    # docstring. This is the same "shrinks on some channels, not others"
    # bug as the channel number, just with zero prior compensation on the
    # banner (it was a flat, uncorrected 18px font). Applies uniformly to
    # every channel 03-44 since it's keyed off this frame's geometry, not
    # a per-channel table. No-op for Options 1/2/off.
    if _active_bezel_stem() == "bezel2":
        bar_surf = _osd_anisotropic_correct(
            bar_surf, sw, sh,
            ignore_package_aspect=_content_ignores_package_aspect(sw, sh))
        bar_w = bar_surf.get_width()
    bar_x = picture_rect.x + (picture_rect.width - bar_w) // 2
    bar_y = picture_rect.bottom - bar_h - margin
    screen.blit(bar_surf, (bar_x, bar_y))



def _draw_status_banners(screen):
    global _status_banner_current, _status_banner_started_at
    try:
        _advance_status_banner_streaks()
        now = pygame.time.get_ticks()
        order = ("server", "drive", "gamepad", "missing_media")

        if _status_banner_current is not None:
            if not _status_banner_is_active(_status_banner_current):
                _status_banner_current = None
                _status_banner_started_at = None
            elif now - _status_banner_started_at >= STATUS_BANNER_DURATION_MS:
                _mark_status_banner_consumed(_status_banner_current)
                _status_banner_current = None
                _status_banner_started_at = None

        if _status_banner_current is None:
            for name in order:
                if _status_banner_is_active(name) and not _status_banner_is_consumed(name):
                    _status_banner_current = name
                    _status_banner_started_at = now
                    break

        if _status_banner_current is None:
            return
        _draw_status_banner_bar(screen, _status_banner_label(_status_banner_current))
    except Exception as e:
        log.warning("_draw_status_banners: draw failed: %s", e)


# ---------------------------------------------------------------------------
# TV-station / visualizer captions overlay
#
# Separate from the DVD player's captions entirely (see game_deck.py's
# _apply_dvd_captions_state) -- that one hands a subtitle track straight to
# VLC's own SPU renderer, which is composited into the decoded video frame
# itself and therefore already scales/crops/repositions for free as part of
# the picture. Visualizer channels never display a decoded VLC frame at all
# (visualizer_deck.render_active_engine only reads audio amplitude and draws
# its own generated graphic -- see the original captions-study notes), so a
# VLC-burned subtitle there would be composited onto a frame nobody ever
# blits to screen. Regular TV-station channels do show a real VLC frame, but
# for a single consistent "plain white text you control" look across both
# channel types (per the user's ask), both go through this one pygame text
# overlay instead of two different rendering mechanisms.
#
# Cue *sourcing* reuses the same embedded -> sidecar waterfall as the DVD
# player (media.resolve_caption_source), just consumed differently: this
# overlay needs actual parsed (start_ms, end_ms, text) cue data to look up
# and draw every frame, not a file handed to VLC's add_slave.
# ---------------------------------------------------------------------------

# In-memory cue cache for whatever's currently playing on vlc_engine (TV
# station / visualizer channels only -- the DVD engine's captions never
# touch this). Re-resolved only when the playing path actually changes, so
# this costs nothing on the other ~59 frames/sec between path changes.
# "pending_path" tracks a path whose resolution is currently running on a
# background thread (see _caption_cues_for) -- kept separate from "path"/
# "cues" so the render thread can tell "still resolving, show nothing yet"
# apart from "resolved, and it turned out to have no captions" without a
# third cues-list sentinel value. "live_session" holds the LiveCaptionSession
# doing a live, in-memory-only ASR pass when nothing embedded/sidecar was
# found for this path -- see _caption_cues_for. "channel" is the channel
# this cache was built for -- how _caption_cues_for tells a same-channel
# internal advance (show -> next show/commercial) apart from a real channel
# change, which is what decides whether a prefetched next-file session (see
# _tv_caption_prefetch below) gets promoted instead of starting cold.
_tv_caption_cache = {"path": None, "cues": [], "pending_path": None, "resolved_at": 0.0,
                     "live_session": None, "channel": None}

# A LiveCaptionSession started ahead of time for the NEXT file scheduled on
# the same channel, kicked off once the CURRENT file's session has already
# built its lead (see _maybe_start_tv_caption_prefetch). The point: without
# this, every internal advance to a new file -- not just a real channel
# change -- stopped whatever session was running and started the next one
# from a cold 0s lead, so a live-captioned show that had been caught up for
# its whole runtime still went caption-less for LIVE_CAPTION_LEAD_SEC again
# at every single commercial break and every episode boundary. Prefetching
# means that by the time the next file actually goes live, its session
# already has a head start (or is already ready) -- see _caption_cues_for's
# "same channel, prefetch matches" branch for where this gets promoted.
# Only ever holds one lookahead session at a time -- one file ahead is
# enough to close the commercial-break gap without keeping N sessions (and
# N whisper workloads) alive for content that's still several files out.
_tv_caption_prefetch = {"path": None, "session": None, "channel": None}

# How often to re-attempt resolution for a file that came back with no
# embedded/sidecar captions at all (no live ASR session even started --
# see the mtime check in _resolve_job). A genuine ASR fallback instead
# gets its own live session immediately and is polled every frame via
# live_session.ready/.snapshot(), not through this retry.
_TV_CAPTION_RETRY_SECONDS = 8.0

_TV_CAPTION_COLOR_NAMES = {
    "white":  (255, 255, 255),
    "yellow": (255, 220, 60),
    "green":  (90, 230, 110),
}

# Longest a single cue may stay on screen, independent of its own end_ms --
# see the BUG FIX note in _draw_caption_overlay for why end_ms alone isn't
# trustworthy (VAD can merge a long silent/musical gap into the segment
# right before it). 7s matches common broadcast/streaming subtitle style
# guides for a single cue's max hold.
_CAPTION_MAX_HOLD_MS = 7000


def _tv_caption_color_rgb():
    """Resolve the persisted tv_captions_color config value to an RGB
    triple. Uses the exact same LIST_TEXT_COLOR_RGB palette as the game
    console "TEXT COLOR" setting (see game_deck.py) -- matched intentionally
    since it's the app's one other existing text-color picker, and the UI
    cycles through the identical LIST_TEXT_COLOR_NAMES list."""
    from game_deck import LIST_TEXT_COLOR_RGB
    name = db.config.get("tv_captions_color", "white") if db is not None else "white"
    return LIST_TEXT_COLOR_RGB.get(name, (255, 255, 255))


def _stop_tv_live_caption_session():
    """Stop whatever LiveCaptionSession is running for the currently
    cached path, if any -- content nobody's watching anymore doesn't need
    to keep transcribing. Safe to call any time; a no-op if there is no
    live session."""
    live = _tv_caption_cache.get("live_session") if isinstance(_tv_caption_cache, dict) else None
    if live is not None:
        try:
            live.stop()
        except Exception:
            pass


def _stop_tv_caption_prefetch():
    """Stop and clear whatever lookahead session _maybe_start_tv_caption_
    prefetch has running (or already landed) for the next file on this
    channel, if any -- called whenever that prefetch no longer applies:
    a real channel change, or the file that actually went live next
    turned out not to be the one predicted. Safe to call any time; a
    no-op if there is no prefetch in flight."""
    global _tv_caption_prefetch
    session = _tv_caption_prefetch.get("session") if isinstance(_tv_caption_prefetch, dict) else None
    if session is not None:
        try:
            session.stop()
        except Exception:
            pass
    _tv_caption_prefetch = {"path": None, "session": None, "channel": None}


def _maybe_start_tv_caption_prefetch(ch, current_path):
    """Once the current file's live caption session has caught up (see the
    call sites in _caption_cues_for), start transcribing the NEXT file
    scheduled on this same channel ahead of time, so a same-channel
    advance -- a commercial break, the next episode -- can promote an
    already-running (or already-ready) session instead of starting a
    fresh one from a cold 0s lead. See _tv_caption_prefetch's module-level
    comment for why only one file is ever prefetched ahead.

    No-op if a prefetch is already in flight or already landed (one at a
    time -- see _tv_caption_prefetch), if the next file can't be
    determined, or if it's the same file already playing (a 1-item
    rotation has nothing to prefetch ahead of itself). Cheap to call
    every frame once the current session is ready -- these guards make
    every call after the first a plain dict-get no-op.
    """
    global _tv_caption_prefetch
    if _tv_caption_prefetch.get("session") is not None or _tv_caption_prefetch.get("path"):
        return
    if db is None or not ch or not current_path:
        return
    try:
        ch_info = db.channels_db.get(ch, {})
        if not ch_info or not ch_info.get("active", True):
            return
        next_path = None
        tl_upcoming = None
        if ch_info.get("commercials_enabled", False):
            tl_upcoming = _next_n_from_block_timeline(ch, current_path, n=2)
        if tl_upcoming and len(tl_upcoming) > 1:
            next_path = tl_upcoming[1].get("path")
        else:
            ordered, block_key = _get_channel_ordered_content(ch, ch_info)
            if ordered and block_key:
                upcoming = _next_n_from_ordered(ordered, current_path, n=2)
                if len(upcoming) > 1:
                    for p in _paths_from_entry(upcoming[1]):
                        next_path = p
                        break
        if not next_path or not os.path.exists(next_path):
            return
        next_path = os.path.normpath(next_path)
        if next_path.lower() == os.path.normpath(current_path).lower():
            return  # rotation of one -- nothing to prefetch ahead of itself
    except Exception:
        return

    _tv_caption_prefetch["path"] = next_path
    _tv_caption_prefetch["channel"] = ch
    _tv_caption_prefetch["session"] = None  # landed by the thread below once resolved

    def _prefetch_job():
        session = None
        try:
            cache_entry = None
            if db is not None:
                cache_entry = db.config.get("caption_cache", {}).get(next_path.lower())
            info = resolve_caption_source(next_path, cache_entry=cache_entry)
            # Embedded/sidecar needs no lookahead -- resolving it fresh at
            # advance time is already instant, nothing to build lead for.
            if info.get("kind") is None and info.get("mtime") is not None and not asr_known_unavailable():
                session = LiveCaptionSession(next_path, start_sec=0.0).start()
        except Exception as e:
            log.warning("[TV CAPTIONS] prefetch resolve failed for %s: %s", next_path, e)
        global _tv_caption_prefetch
        if _tv_caption_prefetch.get("path") == next_path:
            _tv_caption_prefetch["session"] = session
        elif session is not None:
            session.stop()  # superseded (channel changed) before this landed

    threading.Thread(target=_prefetch_job, daemon=True, name="TVCaptionPrefetch").start()


def _caption_cues_for(path):
    """Return the current cue list for `path` (the file currently loaded on
    vlc_engine) if already resolved; otherwise kick off resolution on a
    background thread and return [] for now. `path` may be None (nothing
    loaded / not a plain file) -- always returns a list, never raises, and
    never blocks the caller.

    Resolution is intentionally NOT done inline on the caller's thread:
    this is called from the render loop every frame, and while most hits
    are instant (an embedded/sidecar cache hit), a cold path -- captions
    just toggled on mid-playback, or a title with neither -- can still need
    a real ffmpeg subprocess call (embedded-track extraction) or a live ASR
    session to start. Running that synchronously here would stall the
    render thread and show up as a visible frame hitch right at the moment
    captions are turned on; backgrounding it means that frame (and the few
    after it, until the thread finishes) simply show no caption yet,
    exactly like the DVD player's own few-second retry window at title
    start, rather than freezing the picture.

    Follows the exact same embedded -> sidecar priority order the DVD
    player's own captions use (see resolve_caption_source's docstring); if
    neither is found, falls back to a live, in-memory-only ASR pass (see
    media.LiveCaptionSession) instead of the old disk-cached ASR path.
    """
    global _tv_caption_cache, _tv_caption_prefetch
    if not path:
        _stop_tv_live_caption_session()
        _stop_tv_caption_prefetch()
        _tv_caption_cache = {"path": None, "cues": [], "pending_path": None,
                              "resolved_at": 0.0, "live_session": None, "channel": None}
        return []
    ch = str(app_state.get("current_channel", "")).zfill(2)
    if _tv_caption_cache.get("path") == path:
        live = _tv_caption_cache.get("live_session")
        if live is not None:
            # A live ASR session is running (or finished) for this exact
            # title. Nothing is shown until it's built its lead buffer --
            # same "give it a moment" behavior the old disk-cached path
            # had while a background job was still working -- after that
            # its cue list is read fresh every frame, live. Once caught
            # up, also make sure the NEXT file on this channel is already
            # being transcribed ahead of time (see
            # _maybe_start_tv_caption_prefetch) so a commercial break or
            # episode boundary doesn't go dark again while a fresh
            # session builds lead from scratch.
            if live.ready:
                _maybe_start_tv_caption_prefetch(ch, path)
                return live.snapshot()
            return []
        cues = _tv_caption_cache.get("cues") or []
        if cues:
            _maybe_start_tv_caption_prefetch(ch, path)
            return cues  # a static embedded/sidecar file -- it doesn't grow, nothing to re-poll
        # Came back empty last time (no embedded/sidecar track at all, or
        # the resolve itself failed) -- don't treat that as final. Re-poll
        # at _TV_CAPTION_RETRY_SECONDS pace (not every frame, since a miss
        # still costs a resolve_caption_source() call -- an ffprobe/stat
        # round trip) in case captions get added to the file later.
        if time.monotonic() - _tv_caption_cache.get("resolved_at", 0.0) < _TV_CAPTION_RETRY_SECONDS:
            return []
        if _tv_caption_cache.get("pending_path") == path:
            return []  # a retry is already resolving this exact path
    elif _tv_caption_cache.get("pending_path") == path:
        return []  # already resolving this exact path in the background
    else:
        # Genuinely a new path. If this is a same-channel advance (a
        # commercial break, the next episode -- NOT a real channel
        # change) landing on exactly the file _maybe_start_tv_caption_
        # prefetch already started transcribing ahead of time, promote
        # that session instead of throwing away its head start and
        # starting over at a cold 0s lead -- see _tv_caption_prefetch's
        # module-level comment for why this is the whole point of
        # prefetching. Anything else still running for the old path (the
        # old file's own session, or a stale/non-matching prefetch) is
        # for content nobody's watching anymore and gets cleared either
        # way -- this is also the "clear the cache when the show ends or
        # the channel changes" behavior: old cues never survive a path
        # change, promoted or not.
        prefetch = _tv_caption_prefetch
        if (_tv_caption_cache.get("channel") == ch and prefetch.get("channel") == ch
                and prefetch.get("path") == path and prefetch.get("session") is not None):
            _stop_tv_live_caption_session()  # the OLD file's session -- done with it
            promoted = prefetch["session"]
            promoted.attach_playback(_tv_playback_seconds, _tv_playback_seconds() or 0.0)
            _tv_caption_prefetch = {"path": None, "session": None, "channel": None}
            _tv_caption_cache = {"path": path, "cues": [], "pending_path": None,
                                  "resolved_at": time.monotonic(),
                                  "live_session": promoted, "channel": ch}
            return promoted.snapshot() if promoted.ready else []
        _stop_tv_live_caption_session()
        _stop_tv_caption_prefetch()

    _tv_caption_cache["pending_path"] = path

    def _resolve_job():
        cues = []
        live_session = None
        try:
            cache_entry = None
            if db is not None:
                cache_entry = db.config.get("caption_cache", {}).get(os.path.normpath(path).lower())
            info = resolve_caption_source(path, cache_entry=cache_entry)
            srt_path = info.get("srt_path")
            if info.get("kind") == "embedded" and not srt_path:
                out_path = os.path.join(
                    resolve_captions_dir(),
                    f"tv_{abs(hash(os.path.normpath(path).lower()))}.srt",
                )
                if _extract_embedded_subtitle_to_file(path, info["stream_index"], out_path):
                    srt_path = out_path
            if srt_path:
                cues = parse_caption_cues(srt_path)
            elif info.get("kind") is None and info.get("mtime") is not None and not asr_known_unavailable():
                # Nothing embedded/sidecar, and the file is real (mtime set
                # means resolve_caption_source actually stat()'d it) --
                # fall back to a live, in-memory-only ASR pass instead of
                # the old disk-cached one. Seed it from the exact playback
                # position at tune-in so it starts building lead from
                # where the viewer actually is, not from 0:00.
                #
                # BUG FIX (captions never appearing to show up): this used
                # to seed only from vlc.player.get_time(). On a boot or
                # scheduled tune-in the file is opened already mid-way
                # through (seek_offset can be minutes in -- see
                # change_channel/_seek_when_ready), but VLC's own
                # get_time() keeps reporting ~0 until that seek actually
                # lands, which _seek_when_ready's own [SEEK VERIFY]
                # logging shows can take over a second -- and captions
                # start resolving as soon as _had_first_frame_this_tune
                # flips, which isn't guaranteed to be after that. Seeded
                # from ~0 instead of the real position, the session spent
                # its transcription budget building lead for content
                # nobody was watching yet, and had to fully catch up to
                # the real position (potentially minutes of audio) before
                # any cue's timestamp ever matched live playback -- which
                # just looked like "no captions ever showed up" for
                # however long that catch-up took.
                # calculate_slotted_playback_state's own schedule math
                # (via _get_probe_now_state) knows the correct seek
                # position immediately, independent of whether VLC's own
                # seek has landed yet, so it's tried first and confirmed
                # against `path` before being trusted. get_time() is kept
                # as a fallback for anything not driven by that schedule.
                start_sec = 0.0
                try:
                    now_state = _get_probe_now_state(ch) if ch else {}
                    sched_file = now_state.get("file", "")
                    sched_seek = now_state.get("seek", 0) or 0
                    if (sched_file and sched_seek > 0
                            and os.path.normpath(sched_file).lower() == os.path.normpath(path).lower()):
                        start_sec = float(sched_seek)
                except Exception:
                    pass
                if start_sec <= 0.0:
                    try:
                        vlc = globals().get("vlc_engine")
                        if vlc is not None and vlc.player is not None:
                            pos_ms = vlc.player.get_time()
                            if pos_ms and pos_ms > 0:
                                start_sec = pos_ms / 1000.0
                    except Exception:
                        pass
                live_session = LiveCaptionSession(
                    path, start_sec=start_sec, position_fn=_tv_playback_seconds).start()
        except Exception as e:
            log.warning("[TV CAPTIONS] cue resolve failed for %s: %s", path, e)
            cues = []
        global _tv_caption_cache
        # Only land the result if this is still the path actually playing
        # -- the user may have changed channels again before a slow
        # resolve (extraction, or spinning up a live ASR session) finished.
        if _tv_caption_cache.get("pending_path") == path:
            _tv_caption_cache = {"path": path, "cues": cues, "pending_path": None,
                                  "resolved_at": time.monotonic(),
                                  "live_session": live_session, "channel": ch}
        elif live_session is not None:
            live_session.stop()  # channel changed again before this landed

    threading.Thread(target=_resolve_job, daemon=True, name="TVCaptionResolve").start()
    return []


def _tv_playback_seconds():
    """Current playback position of the TV player in FILE seconds, or None if
    it can't be read. This is the same clock _draw_caption_overlay compares cue
    times against, so live captions are paced against exactly what the viewer
    sees (see media.LiveCaptionSession)."""
    try:
        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return None
        ms = vlc.player.get_time()
        if ms is None or ms < 0:
            return None
        return ms / 1000.0
    except Exception:
        return None


def _current_tv_caption_path():
    """The plain-file path currently loaded on vlc_engine, or None. Same
    get_media()/get_mrl() pattern already used elsewhere in this file (see
    e.g. the "now playing" checks around change_channel) -- returns None for
    anything that isn't a resolvable local file path (nothing loaded, a
    stream URL, etc.), which _caption_cues_for treats as "no cues"."""
    try:
        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return None
        media = vlc.player.get_media()
        if media is None:
            return None
        mrl = media.get_mrl()
        if not mrl or not mrl.startswith("file:///"):
            return None
        from urllib.parse import unquote
        return os.path.normpath(unquote(mrl.replace("file:///", "")))
    except Exception:
        return None


def _vis_card_font_that_fits(strs, base_size, max_w, min_size=8):
    """Largest Courier New bold size <= base_size where every string in
    `strs` fits within max_w real pixels, down to min_size. Used so a
    long song title can never run past the edge of the picture -- the
    prior fixed 17px (just scaled by the Bezel shrink factor) had no
    upper bound tied to the actual available width, so it only avoided
    overflow by coincidence for shorter titles."""
    size = max(min_size, base_size)
    while size > min_size:
        f = _cached_sys_font("Courier New", size, bold=True)
        if all(f.size(s)[0] <= max_w for s in strs):
            return f, size
        size -= 1
    return _cached_sys_font("Courier New", min_size, bold=True), min_size


def _vis_card_truncate_to_width(font, s, max_w):
    """Last-resort truncation with a trailing ellipsis for a title so
    long even the font floor from _vis_card_font_that_fits can't make it
    fit."""
    if font.size(s)[0] <= max_w:
        return s
    t = s
    while t and font.size(t + "...")[0] > max_w:
        t = t[:-1]
    return (t + "...") if t else s[:1]


def _clean_song_display_title(raw_title):
    """Thin wrapper -- the actual 'hide extra text' logic lives in
    media.clean_music_display_title() now, shared with every other screen
    that shows a music track's display name (file explorer's audio rows),
    so the visualizer's now-playing card and those screens can never drift
    out of sync."""
    return media.clean_music_display_title(raw_title)


def _draw_visualizer_song_card(screen):
    """Draws the visualizer channel's song-name/style card.

    Simple, flat rule, no exceptions: the card's top-left corner sits
    (as close as an integer-pixel round-trip allows) 16px down and 16px
    right of the real, on-screen picture's own top-left corner -- always,
    regardless of Bezel style (off, Option 1, 2, or 3), window Aspect
    Ratio (4:3/16:9), or window size.

    This draws PRE-Bezel-composite, onto the virtual `screen` -- the
    single call site is right after media.CRT_WARP_ACTIVE is set, before
    the Settings menu/dialog overlay is painted on top of that same
    canvas (see the call site comment). That ordering is what makes the
    card warp/curve along with the picture through the CRT shader, the
    same way the menu and the generic channel-number OSD already do, and
    what makes it sit naturally BEHIND the menu when one is open: the
    menu's own draw call simply paints over the card's corner afterward,
    on the same canvas, rather than this function needing to hide itself.
    The card keeps rendering (and its own burn-in timeout keeps counting
    down) exactly as if nothing were covering it -- it's only ever
    visually occluded, never actually skipped, while the menu is up.

    Gets a flat, style-independent 16 real screen pixel margin by
    pre-shrinking the margin (and only the margin -- font size/line gap
    are already a fraction of the picture and so scale correctly on
    their own) by the inverse of whatever _composite_bezel_frame is
    about to shrink this canvas by for the active style, the exact same
    trick _draw_channel_volume_osd's "picture" phase already uses for
    the channel-number OSD. See _bezel_composite_geometry's own
    docstring for the scale math. This is necessary because each
    photographed Bezel style shrinks the picture by a different amount,
    so a flat pixel margin drawn pre-shrink would otherwise land at a
    different real on-screen distance per style.

    The card's position is fully decoupled from the channel number's own
    anchor (app_state["_ch_num_generic_osd_y"], written by
    _draw_channel_volume_osd) -- the ONLY OSD that gets its own
    special-cased location is the physical LED "CH NN" readout baked
    into bezel1/bezel2's casing itself (that's real, fixed hardware art,
    not something this text should try to match). The song card does
    not read that value at all.

    The Visualizer channel ignores Aspect Ratio/Screen Mode boxing only
    while Bezel is off -- its picture fills the full real window rect
    then (see "_vis_fixed_rect" at its render call), independent of
    whatever 4:3/16:9 "package" the Aspect Ratio setting is currently set
    to (that setting only affects TV-station video content, never the
    program window itself). While Bezel is on, the Visualizer is boxed
    into the same rect every other channel type is, so this card and the
    channel-number OSD shrink/position in step with it exactly like they
    do for Video/Guide/Game -- see _vis_ignores_package_aspect, the one
    shared function that decides this for every consumer (the
    Visualizer's own picture render included), so none of them can ever
    disagree about which case is active."""
    text = app_state.get("_vis_card_text")
    if not text:
        return

    # Full replacement screens still hide the card outright -- there's
    # nothing sensible to show it "behind" for these (splash, the quit/
    # restart confirmation dialogs, the file explorer). The Settings
    # menu is deliberately NOT in this list any more: see the docstring
    # above for why drawing pre-composite, before the menu is painted,
    # already puts the card behind it for free without this function
    # needing to know the menu is open at all.
    if (app_state.get("show_splash", False)
            or app_state.get("show_quit_confirm", False)
            or app_state.get("show_restart_confirm", False)
            or app_state.get("file_explorer_active", False)):
        return

    line1, line2 = text

    sw, sh = screen.get_size()
    geom = _bezel_composite_geometry(sw, sh, ignore_package_aspect=_vis_ignores_package_aspect(sw, sh))
    if geom is not None:
        src_rect, scale_x, scale_y, _dest_x, _dest_y, _draw_w, _draw_h = geom
        # Pre-composite/pre-warp virtual-canvas rect -- what
        # _composite_bezel_frame is about to shrink by (scale_x, scale_y)
        # into the real, on-screen picture rect. Drawing directly against
        # THIS rect (instead of the post-shrink real one) is what lets
        # the card ride along with the CRT warp/Bezel shrink like every
        # other pre-composite layer. See docstring.
        picture_rect = src_rect
        _inv_scale_x = 1.0 / scale_x if scale_x > 0 else 1.0
        _inv_scale_y = 1.0 / scale_y if scale_y > 0 else 1.0
    else:
        picture_rect = pygame.Rect(0, 0, sw, sh)
        _inv_scale_x = 1.0
        _inv_scale_y = 1.0

    ref = max(1, picture_rect.height)
    line_gap = max(2, round(ref * 0.045))
    base_font_size = max(8, round(ref * 0.026))

    # Flat 48/64 real screen pixel margin, pre-scaled by the inverse of
    # this style's own composite shrink so that, after
    # _composite_bezel_frame shrinks this whole canvas back down by
    # (scale_x, scale_y), the margin lands at that same flat 48/64 real
    # screen pixels for every style -- see docstring. font size/line_gap
    # above don't need this correction: they're already a fraction of
    # picture_rect's own height, so the same shrink that corrects the
    # margin leaves their real on-screen size unchanged relative to the
    # picture.
    _MARGIN_X_PX = max(1, round(48 * _inv_scale_x))
    _MARGIN_Y_PX = max(1, round(64 * _inv_scale_y))

    import colorsys as _card_colorsys
    _hue = (db.config.get("theme_ui_hue", 140) / 360.0) if db is not None else (140 / 360.0)
    _hr, _hg, _hb = _card_colorsys.hsv_to_rgb(_hue, 0.9, 1.0)
    theme_green_color = (int(_hr * 255), int(_hg * 255), int(_hb * 255))

    # Never let the card run past the right edge of the actual picture,
    # regardless of how long the song title is: shrink the font to fit
    # both lines first, and truncate with an ellipsis as a last resort if
    # even the font floor is still too wide.
    max_text_width = max(10, picture_rect.width - _MARGIN_X_PX * 2)
    font, _fitted_size = _vis_card_font_that_fits((line1, line2), base_font_size, max_text_width)
    line1 = _vis_card_truncate_to_width(font, line1, max_text_width)
    line2 = _vis_card_truncate_to_width(font, line2, max_text_width)

    # Top-left corner: flat pixels down/right of the picture's own real
    # top-left corner. Same rule for every style/aspect -- see docstring.
    line1_y = picture_rect.y + _MARGIN_Y_PX
    line1_x = picture_rect.x + _MARGIN_X_PX

    # Hard backstop regardless of the width-budget fit above: never let
    # either line's rendered surface actually cross the picture's right
    # edge, the same clamp the channel-number OSD already applies to
    # itself for the identical reason.
    _picture_right = picture_rect.x + picture_rect.width
    line2_y = line1_y + line_gap
    _surf1 = font.render(line1, True, theme_green_color)
    _surf2 = font.render(line2, True, theme_green_color)
    _line1_x = min(line1_x, _picture_right - _surf1.get_width())
    _line2_x = min(line1_x, _picture_right - _surf2.get_width())
    screen.blit(_surf1, (_line1_x, line1_y))
    screen.blit(_surf2, (_line2_x, line2_y))


def _wrap_caption_to_two_lines(font, text, max_w):
    """Greedily word-wrap `text` into at most two lines that each fit
    max_w real pixels at `font`'s size. Returns (line1, line2) -- line2 is
    "" when the whole thing already fits on one line. Words are never
    split mid-word; if even two lines can't hold everything, the leftover
    is truncated onto line2 with a trailing ellipsis via
    _vis_card_truncate_to_width (same last-resort behavior the song card
    already uses), rather than silently dropping words with no indication."""
    words = text.split()
    if not words:
        return "", ""
    if font.size(text)[0] <= max_w:
        return text, ""
    line1_words = []
    i = 0
    while i < len(words):
        candidate = " ".join(line1_words + [words[i]])
        # `not line1_words` lets a single word wider than max_w on its own
        # still go on line1 rather than looping forever with nothing ever
        # fitting -- _vis_card_truncate_to_width further down handles that
        # rare case for line2 the same way.
        if not line1_words or font.size(candidate)[0] <= max_w:
            line1_words.append(words[i])
            i += 1
        else:
            break
    line1 = " ".join(line1_words)
    remaining = " ".join(words[i:])
    if not remaining:
        return line1, ""
    return line1, _vis_card_truncate_to_width(font, remaining, max_w)


def _draw_caption_overlay(screen):
    """Draw the current caption cue (if any) for TV-station / visualizer
    channels. It is gated on the persisted tv_captions_enabled toggle, on the
    current channel not being the game channel ("03", whose background music
    has no dialogue to caption) or the guide ("04", where captions were never
    wanted per the original ask), and on the new channel having displayed its
    first frame. The latter prevents old cues from being painted over the
    static/black channel-switch transition or while the new media is still
    loading.

    Draw order / z-order: this now draws onto the virtual `screen` BEFORE
    _composite_bezel_frame shrinks it into the Bezel cutout -- the same
    pre-composite canvas the Settings menu, splash/quit/restart dialogs, and
    the on-picture channel/volume OSD ("picture" phase) already draw onto.
    Call this EARLY in that pre-composite stack (right after the Visualizer
    song card, before the menu/dialog block and before
    _draw_channel_volume_osd("picture")) so anything drawn later in the same
    stack simply paints over the caption where they overlap -- captions stay
    confined to the TV picture and sit underneath the menu, dialogs, and the
    volume bar/channel OSD, without this function needing to know any of
    those are open. Because it now shares the virtual canvas with the
    picture, it also warps/shrinks right along with it under every screen
    mode automatically through the Bezel-composite/CRT-warp step -- but that
    step only accounts for Bezel style and warp, NOT the real window simply
    being resized/minimized smaller. The virtual canvas IS the current
    window (see caption_rect below, sized off screen.get_size() every
    frame), so font_size/pad_x/pad_y are deliberately expressed as a
    fraction of caption_rect's own height (see `ref` below), the same
    pattern _draw_visualizer_song_card's font/line_gap already use, rather
    than flat pixel constants -- a flat 38px stayed 38 *real* window pixels
    at any window size, so shrinking the actual OS window (not just picking
    a smaller Bezel/aspect option) made the text an ever-larger fraction of
    the available width instead of shrinking with everything else, forcing
    more of every cue to get ellipsis-truncated the smaller the window got.

    Anchor rule: the caption line sits at a stable bottom-of-screen
    position. It does not follow the source picture when an aspect ratio
    adds or removes black bars.

    Vertical position: halfway between the bottom of the Water Mark badge
    and the true bottom of the screen -- computed the same way regardless
    of whether Water Mark is actually turned on, using the same margin
    formula _draw_watermark applies to its own bottom-right corner
    (_WATERMARK_MARGIN_FRAC of the content rect's height, plus that Bezel
    style's _WATERMARK_BEZEL_EXTRA_OFFSET), so the two stay in step with
    each other without this function needing the watermark to be visible.

    Up to two lines, capped at 80% of caption_rect's own width (see
    _wrap_caption_to_two_lines): line 1 sits at a fixed spot by default,
    and a cue that needs a second line grows the box DOWNWARD by adding
    line 2 below it. Line 2 is hard-clamped so it can never grow low
    enough to paint over the Water Mark badge (see "line2_bottom_limit"
    below). If line 1's normal spot doesn't leave enough room for line 2
    to fit above that limit, line 1 shifts UP just enough to make room --
    the only thing that ever moves line 1 -- so a real two-line cue keeps
    both lines instead of getting silently truncated to one. Only on an
    extremely short window, where even two lines shifted all the way to
    the top of caption_rect still wouldn't fit, does line 2 fall back to
    being dropped (with line 1 rendered plain, no ellipsis needed since
    line 1 alone was never length-limited to begin with).
    """
    try:
        if db is None or not db.config.get("tv_captions_enabled", False):
            return
        ch = str(app_state.get("current_channel", "")).zfill(2)
        if ch in ("03", "04"):
            return

        # A channel switch clears the prior tune's first-frame marker. Keep
        # captions hidden through the static/black transition, while an
        # activation is still queued, and until the replacement media has
        # actually supplied a frame. Without all three guards, a cue from the
        # outgoing file can briefly appear over the transition or over the
        # new channel's loading fill.
        now_ticks = pygame.time.get_ticks()
        if (now_ticks < app_state.get("channel_switch_black_until", 0)
                or app_state.get("_pending_channel_activation") is not None
                or not app_state.get("_had_first_frame_this_tune", False)):
            return

        path = _current_tv_caption_path()
        cues = _caption_cues_for(path)
        if not cues:
            return

        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return
        now_ms = vlc.player.get_time()
        if now_ms is None or now_ms < 0:
            return

        # BUG FIX (caption lingering through a real silent stretch): a cue's
        # own end_ms isn't always trustworthy as "when to stop showing this
        # text" -- faster-whisper's VAD can merge a stretch of near-silence
        # into the same segment as the speech right before/after it (a long
        # musical interlude between two lines, e.g.), which hands that
        # segment an end_ms far later than when anyone actually finished
        # talking. Capping how long any single cue may stay on screen,
        # independent of its own end_ms, means a cue like that clears after
        # a normal reading hold instead of sitting there for the whole gap.
        # 7s is comfortably longer than any one- or two-line cue here takes
        # to read, and is in the same range most broadcast/streaming
        # subtitle style guides (Netflix's timed-text guidance, etc.) use
        # as a single cue's max on-screen hold.
        active_text = None
        for start_ms, end_ms, text in cues:
            shown_until_ms = min(end_ms, start_ms + _CAPTION_MAX_HOLD_MS)
            if start_ms <= now_ms <= shown_until_ms:
                active_text = text
                break
            if start_ms > now_ms:
                break  # cues are time-sorted; nothing later can match either
        if not active_text:
            return

        # Do not use the decoded picture's aspect-fit rectangle here. That
        # rectangle moves when a video/settings aspect ratio changes, which
        # is precisely the behavior captions must not inherit. The stable
        # screen boundary intentionally allows captions to remain in the
        # lower black bar when the picture becomes narrower or shorter.
        #
        # BUG FIX (captions bleeding into the letterbox/pillarbox bars):
        # this used to go through _bezel_composite_geometry's own src_rect
        # (_cap_geom[0]) instead of calling _compute_content_rect directly.
        # That geometry function's src_rect only actually equals the
        # 4:3-package content box in SOME configurations -- it depends on
        # _content_ignores_package_aspect, on whether Bezel is on, and on
        # a couple of Bezel-only expansion/widen steps applied further
        # downstream -- so it could drift from the true package-boxed area
        # the actual picture renders into. _compute_content_rect is the
        # single rect video/guide/game content is ALWAYS boxed into
        # regardless of Bezel (see its own docstring: "Bezel never shrinks
        # the content rect... applied once, downstream" -- Bezel is purely
        # a later compositing step over the finished frame, so this rect
        # is identical whether Bezel is on or off). Calling it directly
        # here, the same way it's called for the actual picture, is what
        # guarantees captions can never end up sized/positioned off of a
        # DIFFERENT rect than the one the picture itself is confined to.
        sw, sh = screen.get_size()
        caption_rect = _compute_content_rect(sw, sh)
        # Explicit side gap so a caption box can never sit flush against
        # the true left/right edge of the 4:3 picture -- always a visible
        # margin of real picture between the caption and wherever the
        # pillarbox bar (or, in a 4:3 window, the real window edge)
        # begins, on both sides, at any window shape.
        _cap_side_gap = max(2, round(caption_rect.width * 0.02))
        if caption_rect.width > _cap_side_gap * 2:
            caption_rect = caption_rect.inflate(-_cap_side_gap * 2, 0)

        # font_size/pad_x/pad_y scale with caption_rect's own height instead
        # of being flat pixel counts -- see docstring's "Draw order" section
        # for why a flat value doesn't track an actual window resize. 720px
        # is the reference height the original flat values (38/14/6) were
        # tuned at, so these fractions reproduce that exact look at 720p and
        # scale proportionally above/below it.
        ref = max(1, caption_rect.height)
        font_size = max(10, round(ref * (38.0 / 720.0)))
        pad_x = max(2, round(ref * (14.0 / 720.0)))
        pad_y = max(1, round(ref * (6.0 / 720.0)))

        # Margin: halfway between the Water Mark's own bottom edge and the
        # true bottom of the screen. Reuses _draw_watermark's own margin
        # formula (fraction of height + this Bezel style's extra offset)
        # against this same caption_rect -- NOT the watermark's live
        # bounds_rect, which tracks the actual decoded picture and can
        # differ from caption_rect the same way the picture's own aspect-fit
        # rect can (see "Anchor rule" above) -- so this stays independent of
        # whether Water Mark is even turned on right now.
        _wm_margin_y = max(6, round(ref * _WATERMARK_MARGIN_FRAC))
        _wm_extra_y = 0.0
        _wm_stem = _active_bezel_stem()
        if _wm_stem is not None:
            _wm_extra_y = _WATERMARK_BEZEL_EXTRA_OFFSET.get(_wm_stem, (0, 0))[1]
        margin = max(2, round((_wm_margin_y + _wm_extra_y) / 2.0))

        font = _cached_sys_font("Arial", font_size, bold=True)
        # Capped at 80% of caption_rect's own width -- the true
        # package-boxed content area (see caption_rect above), not the
        # raw screen -- so a long cue can't run past the actual picture's
        # edge into the letterbox bars on a window whose real shape
        # doesn't match the selected package aspect.
        max_text_width = max(10, round(caption_rect.width * 0.8) - pad_x * 2)
        one_line = " ".join(active_text.split())
        line1_text, line2_text = _wrap_caption_to_two_lines(font, one_line, max_text_width)
        if not line1_text:
            return

        color = _tv_caption_color_rgb()
        surf1 = font.render(line1_text, True, color)
        surf2 = font.render(line2_text, True, color) if line2_text else None

        # Line 1's default position -- the same fixed anchor a single-line
        # cue always used (stable screen anchor; see the caption_rect note
        # above for why it doesn't follow the source picture's own rect).
        # A second line, when needed, is added BELOW this spot, growing
        # the box downward. line1_y only ever moves off this default in
        # one case -- see the "shift line 1 up" block below -- and even
        # then only by the minimum needed to fit line 2 above
        # line2_bottom_limit.
        line1_y = caption_rect.bottom - surf1.get_height() - pad_y - margin
        line_gap = max(1, round(pad_y / 2))

        # How far line 2 may grow downward before it would start painting
        # over the Water Mark badge. This is deliberately NOT the "margin"
        # used for line 1 above -- that's only half the badge's own bottom
        # margin, picked purely to sit a single line partway between the
        # badge and the screen edge, and leaves nowhere near enough room to
        # ever fit a real second line under it (that gap used to be the
        # bug: line 2 got dropped almost every time). Instead, when the
        # badge is actually going to be drawn this frame, this works out
        # its real top edge the same way _draw_watermark positions it, and
        # lets line 2 use every pixel down to just above that. When the
        # badge isn't currently on screen (Water Mark off, wrong
        # channel/mode, splash up, etc.) there's nothing to protect against,
        # so line 2 is free to use nearly all the rest of caption_rect.
        _wm_enabled = db is not None and db.config.get("watermark_enabled", False)
        _wm_raw = _watermark_cache.get("raw")
        if _wm_enabled and _wm_raw not in (None, False):
            _wm_target_w = max(24, round(caption_rect.width * _WATERMARK_WIDTH_FRAC))
            _wm_raw_w, _wm_raw_h = _wm_raw.get_size()
            _wm_target_h = (max(1, round(_wm_raw_h * (_wm_target_w / _wm_raw_w)))
                             if _wm_raw_w > 0 else 0)
            line2_bottom_limit = (caption_rect.bottom - (_wm_margin_y + _wm_extra_y)
                                   - _wm_target_h - pad_y)
        else:
            line2_bottom_limit = caption_rect.bottom - pad_y
        # Never let badge-avoidance push the limit above line 1's own box --
        # line 1 always draws no matter what.
        line2_bottom_limit = max(line2_bottom_limit, line1_y + surf1.get_height() + pad_y)

        # Line 1 NEVER moves. A second row is simply added directly below it;
        # it is not shifted, clamped against the Water Mark, or dropped. (The
        # old shift-up block treated the badge's top edge as line 2's floor,
        # which line 1 always sits below, so it always pushed line 1 up into
        # the badge.)
        if surf2 is not None:
            _room_below = (caption_rect.bottom - 1) - (line1_y + surf1.get_height())
            if _room_below < surf2.get_height() + line_gap:
                line_gap = max(0, _room_below - surf2.get_height())

        # No background panel -- just the outlined text. A thin black
        # outline (render the same glyphs in black at a few pixel offsets,
        # then the real color on top) keeps it readable over bright/busy
        # video the way a solid box used to guarantee, without covering
        # any of the picture behind it. Outline thickness scales with
        # caption_rect the same way font_size does, so it's proportionally
        # the same size at any window resolution.
        _outline_px = max(1, round(ref * (2.0 / 720.0)))
        _outline_color = (0, 0, 0)

        def _blit_outlined(surf_color, text, x, y):
            outline_surf = font.render(text, True, _outline_color)
            for _dx in range(-_outline_px, _outline_px + 1):
                for _dy in range(-_outline_px, _outline_px + 1):
                    if _dx == 0 and _dy == 0:
                        continue
                    screen.blit(outline_surf, (x + _dx, y + _dy))
            screen.blit(surf_color, (x, y))

        line_widths = [surf1.get_width()] + ([surf2.get_width()] if surf2 is not None else [])
        _block_w = max(line_widths)
        block_x = caption_rect.x + (caption_rect.width - _block_w) // 2

        if surf2 is None:
            _blit_outlined(surf1, line1_text, block_x + (_block_w - surf1.get_width()) // 2, line1_y)
        else:
            line2_y = line1_y + surf1.get_height() + line_gap
            _blit_outlined(surf1, line1_text, block_x + (_block_w - surf1.get_width()) // 2, line1_y)
            _blit_outlined(surf2, line2_text, block_x + (_block_w - surf2.get_width()) // 2, line2_y)
    except Exception as e:
        log.warning("_draw_caption_overlay: draw failed: %s", e)


_channel_playback_failures = {}   # zero-padded channel str -> {"file", "reason", "shown_at"}

# zero-padded channel str -> drive root (e.g. "D:\\") that a Visualizer
# channel's music load has already been confirmed to fail against. Checked
# up front on every visit to a Visualizer channel so a channel we already
# know is dead skips straight to static instead of re-attempting
# pygame.mixer.music.load() (and the brief flash of the idle visualizer
# that attempt produces) on every single return trip. Recorded on ANY load
# failure -- not gated on _unresponsive_drive_roots() already flagging the
# drive at that instant, since a drive that fails fast (file open rejected
# in a few ms, not a slow hang) can still answer os.path.exists() on the
# bare root instantly, meaning the OS-level health monitor may never flag
# it at all. See _drive_confirmed_recovered() for how/when this clears.
# Monotonically increasing id, one per play_file_segmented() call, so every
# log line touched by a single load attempt -- scheduler selection, path
# probe, VLC open, watchdog classification, mark-broken, substitute choice --
# can be grepped/traced together as one story instead of guessed at from
# timestamps and file names alone. itertools.count().__next__() is a single
# C-level op under the GIL, so this is safe to call from any thread
# (main loop, background watchdog, deferred-open threads) without a lock.
# Purely additive: nothing reads these ids to make a decision (yet -- see
# the "tri-state path checks" and "stop blacklisting on first ambiguous
# failure" work items, which will start consuming _last_attempt_reason).
_playback_attempt_ids = itertools.count(1)

# Sentinel returned by play_file_segmented() when a deferred (stop-race)
# open has been handed off to a background thread and genuinely has not
# succeeded or failed yet at the moment the call returns. Deliberately NOT
# True or False -- a caller that only checks truthiness (e.g. `if
# played_ok:` / `while not played_ok:`) must be updated to check `is
# _PLAYBACK_PENDING` explicitly, since silently falling through to either
# branch is exactly the bug this sentinel exists to prevent: treating an
# undecided attempt as a confirmed success (writes a false anchor) or a
# confirmed failure (blacklists a file that might still play fine). Real
# state changes for a pending attempt only ever happen later, from
# on_confirmed. A dedicated object (not None) so a caller that forgets a
# default argument doesn't accidentally match this by coincidence.
_PLAYBACK_PENDING = object()

# channel key ("05", etc.) -> the reason string most recently attached to
# that channel's playback attempt by play_file_segmented()/the watchdog.
# Read-only diagnostic breadcrumb for now.
_last_attempt_reason = {}

_visualizer_confirmed_dead_drive = {}

# Same idea as _visualizer_confirmed_dead_drive above, but for ordinary
# Video/Commercial TV-station channels: zero-padded channel key -> the
# drive root a previous load attempt confirmed dead on. Checked (and
# possibly cleared via _drive_confirmed_recovered) at the top of every
# change_channel() load of a station channel -- see the "scan every time
# the channel loads" handling there -- so a channel whose drive is known
# gone goes straight to Static on every subsequent load/auto-advance
# instead of repeating the multi-second retry-and-substitute storm each
# time, and automatically starts playing again the first load after the
# drive is positively confirmed responsive again.
_station_confirmed_dead_drive = {}

# zero-padded channel str -> consecutive count of the per-frame watchdog
# (see the finish-reason=="error" handling below) catching this channel's
# CURRENT file in a real VLC State.Error, as opposed to a normal Ended.
# Error is a reliable "this file itself failed" signal (unlike Ended, which
# is also how a perfectly normal episode finishes) -- but a schedule whose
# next few items are ALSO broken would otherwise just keep advancing
# through them at ~1.5s each, forever, since each individual play attempt
# still reports success at the moment it's issued and only errors out
# shortly after. Once this hits _WATCHDOG_ERROR_BAIL_AFTER for a channel,
# the frame that detects it registers a real channel failure and skips the
# usual advance-to-next-item call, so the render loop's own failure check
# takes over (real static + banner) instead of continuing to hot-loop.
# Reset to 0 the moment a finish is NOT tagged "error" (a real successful
# end-of-episode, or a channel switch away and back).
_watchdog_consecutive_errors = {}
_WATCHDOG_ERROR_BAIL_AFTER = 2

# zero-padded channel str -> {"count": N, "window_start_ms": ticks} tracking
# how many times in a row the WATCHDOG's spurious-blip handling (see
# "_spurious_blip" below) has resumed THIS channel's current file in place
# rather than trusting VLC's Ended/Stopped read. A one-off spurious blip is
# normal and self-heals -- see _SEEK_FRAME_READY_GRACE_MS's comment for the
# usual cause -- but if resuming keeps re-triggering the exact same glitch
# on the same already-open engine, resuming in place forever just repeats
# it every ~2.5-3s indefinitely, which only a real channel change (tearing
# down and reopening on a clean footing) would break. Once a channel hits
# _WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER resumes within
# _WATCHDOG_SPURIOUS_RESUME_WINDOW_MS, stop resuming in place and drop
# anchor trust instead (the same thing a manual channel-away-and-back
# does), so the schedule does a full, clean re-tune on its own instead of
# stacking another resume on top of an already-glitching player. Resets
# whenever the window elapses without hitting the cap, so a channel that
# only occasionally has a one-off blip is never penalized.
_watchdog_consecutive_spurious_resumes = {}
_WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER = 3
_WATCHDOG_SPURIOUS_RESUME_WINDOW_MS = 20000

# Roots _unresponsive_drive_roots() has flagged unresponsive at least once,
# so a later "not currently in that list" can be told apart from "was
# actually confirmed responsive again" vs. "this drive's failure mode never
# trips that check to begin with" (see _visualizer_confirmed_dead_drive above).
_drive_ever_confirmed_unresponsive = set()

# root -> the most recently known-failing file path on that root (the exact
# file whose failure caused a channel to latch into _station_confirmed_
# dead_drive / _visualizer_confirmed_dead_drive), so _drive_confirmed_
# recovered() has something real to probe. Kept as "most recent" rather
# than a list: if a newer failure lands on the same root, it's the more
# current evidence of what's actually being rejected right now.
_dead_drive_probe_file = {}


def _remember_dead_drive_probe_file(root, file_path):
    """Record `file_path` as the file to real-read-probe for `root`'s
    recovery. Call this at every site that latches a channel dead on a
    drive, right alongside setting _station_confirmed_dead_drive /
    _visualizer_confirmed_dead_drive, so _drive_confirmed_recovered() always
    has an up-to-date, real file to test recovery against -- see its
    docstring for why the root-only check can never see some failures
    recover on its own.
    """
    if root and file_path:
        _dead_drive_probe_file[root] = file_path


def _drive_confirmed_recovered(root):
    """True once `root` is confirmed recovered by either of two independent
    signals:

    1. Positively confirmed both unresponsive and, afterward, responsive
       again by the OS-level drive health monitor (root-level).
    2. A real, bounded open+read against the actual file that got this
       root latched dead has just succeeded (file-level).

    Signal 1 alone is deliberately NOT just "root isn't currently in
    _unresponsive_drive_roots()" -- some drive failures never make it into
    that list in the first place (the drive letter keeps answering
    os.path.exists() instantly even though every individual file read on it
    fails, which is exactly what a fast -- not slow/hung -- access rejection
    looks like). For those, "not currently flagged" would be true from the
    very first frame and would immediately clear any remembered failure,
    causing exactly the every-visit retry/flash this is meant to prevent.

    That's exactly the case signal 2 exists for: a drive that never trips
    the root check can still be proven readable again by actually reading
    real bytes back from the exact file that failed. Without it, a channel
    latched dead this way could never recover without an app restart --
    which used to be genuinely true here; see _dead_drive_probe_file.
    """
    if root is None:
        return False
    _now_bad = set(_unresponsive_drive_roots())
    _drive_ever_confirmed_unresponsive.update(_now_bad)
    if root in _drive_ever_confirmed_unresponsive and root not in _now_bad:
        _dead_drive_probe_file.pop(root, None)
        return True
    _probe_file = _dead_drive_probe_file.get(root)
    if _probe_file and media.probe_file_level_recovery(root, _probe_file) is True:
        log.info(
            "[DRIVE HEALTH] %s confirmed recovered via file-level probe of "
            "%s (root-level check never flagged this drive -- this is the "
            "fast-rejection failure mode)", root, _probe_file,
        )
        _dead_drive_probe_file.pop(root, None)
        return True
    return False


# Throttle for _sweep_all_recovered_dead_drives() below -- pygame.time
# ticks (ms) of the last sweep, so the main loop can call it every
# iteration without actually re-running the check 60x/sec.
_last_dead_drive_sweep_ticks = 0
_DEAD_DRIVE_SWEEP_INTERVAL_MS = 2000


def _sweep_all_recovered_dead_drives():
    """Clear every channel's dead-drive latch whose drive has actually
    recovered, regardless of whether that channel is the one currently
    on screen.

    _station_confirmed_dead_drive and _visualizer_confirmed_dead_drive are
    each only otherwise consulted (and popped) from the specific code path
    that loads/renders THAT channel -- change_channel()'s station load
    (~line 21712), the guide-preview highlight load (~line 7598/30490), and
    the visualizer tune-in load (~line 22078/31182). A channel that's
    latched dead and then never visited again -- never surfed to, never
    highlighted in the guide -- has no other path that ever calls
    _drive_confirmed_recovered() for it, so it stays on Static
    indefinitely even after the drive is confirmed fully healthy again,
    until either the user happens to land on it or the app restarts.
    Calling this once per main-loop tick (throttled above) means every
    latched channel's drive gets re-checked on the same cadence regardless
    of which channel is actually being watched, so recovery is never
    contingent on the user's navigation.
    """
    global _last_dead_drive_sweep_ticks
    _now = pygame.time.get_ticks()
    if _now - _last_dead_drive_sweep_ticks < _DEAD_DRIVE_SWEEP_INTERVAL_MS:
        return
    _last_dead_drive_sweep_ticks = _now

    for _ch_key, _root in list(_station_confirmed_dead_drive.items()):
        if _drive_confirmed_recovered(_root):
            _station_confirmed_dead_drive.pop(_ch_key, None)
            _clear_broken_files_for_root(_root)
            log.info("[DRIVE HEALTH] ch%s: %s confirmed recovered by background "
                      "sweep, cleared without waiting for a visit to this channel", _ch_key, _root)

    for _ch_key, _root in list(_visualizer_confirmed_dead_drive.items()):
        if _drive_confirmed_recovered(_root):
            _visualizer_confirmed_dead_drive.pop(_ch_key, None)
            log.info("[DRIVE HEALTH] ch%s (visualizer): %s confirmed recovered by "
                      "background sweep, cleared without waiting for a visit to this channel", _ch_key, _root)


CHANNEL_FAILURE_MESSAGE_MS = 30000

# Populated by play_file_segmented() whenever VLC itself throws while trying
# to open/start a file (media_new/set_media/play() raised) -- keyed by
# normalized path -> the exception text. _classify_playback_failure_reason()
# checks this first so a genuine VLC-side load failure gets reported as
# exactly that, instead of being lumped in with "failed scan" (which really
# just meant "we don't know why"). Cleared the moment that same path plays
# successfully (see play_file_segmented's success path).
_last_vlc_play_exception = {}


# User-facing prefixes for the shared status-banner slot (see
# _draw_status_banner_bar / _report_missing_media) and the per-channel
# banner (_draw_channel_failure_message), keyed by the "reason" a Static
# fallback (or a play_file_segmented failure) is tagged with. Anything not
# listed here falls back to a generic "PLAYBACK FAILED" prefix.
STATIC_FALLBACK_BANNER_PREFIX = {
    "missing_media":        "MEDIA NOT FOUND",
    "channel_config_missing": "CHANNEL CONFIG ERROR",
    "timeline_build_failed": "SCHEDULE BUILD FAILED",
    "schedule_exhausted":   "SCHEDULE ERROR",
    "no_show_selected":     "NO CONTENT MATCHED",
}

# Reasons a Static fallback can be tagged with that are *intentional*, not
# failures -- an explicitly disabled channel, or a schedule the user cleared
# on purpose. These are logged at a quiet level for traceability but never
# raise a banner (arming a "playback failed" banner every
# STATUS_BANNER_DURATION_MS for a state the user deliberately created would
# just be noise).
SILENT_STATIC_REASONS = {"no_media_scheduled", "channel_inactive"}


def _classify_playback_failure_reason(file_path):
    try:
        if file_path:
            _root = os.path.splitdrive(file_path)[0] + "\\" if os.name == "nt" else "/"
            if _root in _unresponsive_drive_roots():
                # Check this before anything below that touches the disk
                # (_cached_path_exists included) -- on a genuinely dead/
                # unresponsive drive that call can itself hang or time out,
                # and would otherwise misreport this as "missing file"
                # rather than what it actually is.
                return "drive not responding"
            _norm_for_vlc = os.path.normpath(file_path)
            _vlc_err = _last_vlc_play_exception.get(_norm_for_vlc)
            if _vlc_err:
                return f"VLC failed to load: {_vlc_err}"
        if not file_path or not _cached_path_exists(file_path):
            return "missing file"
        if db is not None:
            norm_p = os.path.normpath(file_path)
            if db.config.get("media_probe_cache", {}).get(norm_p, {}).get("confirmed_unplayable"):
                return "corrupt file"
    except Exception as e:
        log.warning("_classify_playback_failure_reason: classification failed for %s: %s", file_path, e)
    return "failed scan"


def _register_channel_playback_failure(ch_key, file_path, duration=None, block=None):
    try:
        _root = os.path.splitdrive(file_path)[0] + "\\" if file_path and os.name == "nt" else "/"
        if _root in _unresponsive_drive_roots():
            # This used to `return` here and drop the failure entirely,
            # reasoning that the shared "CHECK YOUR DRIVE" banner already
            # covered it -- but that banner is deliberately scoped to
            # whatever's actually driving the screen right now (see
            # _active_playback_drive_roots), so it doesn't fire for e.g. a
            # channel merely being previewed in the TV Guide. Suppressing
            # the registration too meant that channel's guide-preview box
            # (and the live channel's own failure render) had nothing to
            # key off of, and just sat on a flat buffering-style fill
            # forever instead of falling back to real static. Still log it
            # for traceability, but let it register like any other failure
            # so _channel_playback_failures / the guide preview / the live
            # failure render all pick it up correctly.
            log.warning(
                "[DEBUG DRIVE] _register_channel_playback_failure: channel %s "
                "failing because drive root %r is currently flagged "
                "unresponsive (file=%r, drive_type=%s). Registering as a "
                "normal channel failure rather than dropping it silently. "
                "If this fires for a drive that should always be available "
                "(e.g. C:), check the '[DRIVE HEALTH] ... marked "
                "unresponsive' log line right before this for why the probe "
                "on that root failed/timed out.",
                ch_key, _root, file_path,
                media._win_drive_type_raw(_root) if hasattr(media, "_win_drive_type_raw") else "?",
            )
    except Exception as _dbg_e:
        log.warning("[DEBUG DRIVE] _register_channel_playback_failure: drive-root check itself raised: %s", _dbg_e)
    existing = _channel_playback_failures.get(ch_key)
    now = pygame.time.get_ticks()
    if existing is not None and existing.get("file_path") == file_path:
        return
    _reason = _classify_playback_failure_reason(file_path)

    # Pull together every scrap of info we have on the video that failed,
    # for the log line -- duration/probe data if it was ever scanned, even
    # though the on-screen banner itself stays short.
    _known_duration = duration
    _norm_fail_path = os.path.normpath(file_path) if file_path else None
    if _known_duration is None and _norm_fail_path is not None:
        try:
            _known_duration = _get_cached_media_probe(_norm_fail_path).get("duration")
        except Exception:
            _known_duration = None
    _exists = _cached_path_exists(file_path) if file_path else False

    _channel_playback_failures[ch_key] = {
        "file_path": file_path,
        "file": os.path.basename(file_path) if file_path else "(unknown file)",
        "reason": _reason,
        "shown_at": now,
    }
    log.warning(
        "[CHANNEL FAILURE] Channel %s (block=%s): playback failed -- "
        "file=%r location=%r exists_on_disk=%s known_duration=%s reason=%s",
        ch_key, block, os.path.basename(file_path) if file_path else "(unknown)",
        file_path, _exists, _known_duration, _reason,
    )


def _clear_channel_playback_failure(ch_key):
    _channel_playback_failures.pop(ch_key, None)


def _confirm_playback_started(ch_key, attempt_id, file_path, seek_offset, slot_start_seek,
                               duration, mode, block, interior_cut, deferred,
                               extra_state=None):
    """The ONLY place that should ever write app_state["is_playing_video"],
    app_state["_live_playback_channel"], or a channel's playback_anchor for
    a successful play -- called from play_file_segmented()'s on_confirmed
    once VLC has actually, definitively accepted the file (synchronously,
    or from the deferred-open thread after a stop-race). Centralizing this
    (instead of each of play_file_segmented()'s ~6 call sites writing this
    state itself from the raw return value) is what makes it possible to
    guarantee a still-opening file is never recorded as already live: every
    caller passes an on_confirmed that lands here, and this function is the
    single choke point that decides whether the result is still current
    enough to act on.

    `extra_state`, if given, is a dict of additional app_state keys to set
    only on a confirmed success (e.g. {"loaded_preview_path_cache": path}) --
    lets call sites keep their own bookkeeping without each reimplementing
    the staleness guard below.
    """
    if vlc_engine is None or getattr(vlc_engine, "_current_attempt_id", None) != attempt_id:
        # A newer attempt has already superseded this one (another channel
        # change, or a substitute retry, started before this deferred open
        # finished) -- applying this result now would stomp a newer,
        # already-confirmed state with a stale one. The newer attempt owns
        # app_state/the anchor now; silently drop this one.
        log.info(
            "[ATTEMPT %s] on_confirmed(success, ch%s): stale -- current attempt is now %s, "
            "not applying this result", attempt_id, ch_key,
            getattr(vlc_engine, "_current_attempt_id", None) if vlc_engine else None,
        )
        return

    app_state["is_playing_video"] = True
    app_state["_live_playback_channel"] = ch_key
    _clear_channel_playback_failure(ch_key)
    if extra_state:
        app_state.update(extra_state)
    if deferred:
        print(f"[CHANNEL] Switched to video channel {ch_key} (confirmed after deferred open, attempt {attempt_id})")

    _anchor_seek = seek_offset
    try:
        _real_ms = vlc_engine.player.get_time()
        if _real_ms is not None and _real_ms >= 0:
            _real_s = _real_ms / 1000.0
            # If VLC is >2 s behind the scheduled target, the seek hasn't
            # landed yet -- keep the scheduled position, not ~0.
            if not (seek_offset and seek_offset > 0 and _real_s < seek_offset - 2.0):
                _anchor_seek = _real_s
    except Exception as _pos_err:
        log.warning(
            "_confirm_playback_started: could not read real VLC position for "
            "ch%s anchor, falling back to computed seek: %s", ch_key, _pos_err,
        )

    if db is not None and file_path:
        # wall_start is measured NOW, at actual confirmation time -- not
        # when the attempt was first issued. For a deferred confirmation,
        # real playback only just started; anchoring wall_start to the
        # earlier attempt time would make calculate_slotted_playback_state
        # believe more of the file had elapsed than actually has (elapsed =
        # now - wall_start would include the confirmation delay itself),
        # silently drifting the resumed position forward every time a
        # stop-race happens. Confirmation time is the only correct anchor
        # for "when did this file actually start playing".
        _wall_a = broadcast_clock.seconds_since_midnight()
        db.channels_db.setdefault(ch_key, {})["playback_anchor"] = {
            "file":            file_path,
            "wall_start":      _wall_a,
            "seek_offset":     _anchor_seek,
            "slot_start_seek": slot_start_seek,
            "duration":        duration,
            "mode":            mode,
            "block":           block,
            "interior_cut":    bool(interior_cut),
            # Absolute epoch timestamp, distinct from wall_start (seconds-
            # since-midnight, no date) -- lets a true boot-time anchor
            # resume (see calculate_slotted_playback_state's
            # allow_cold_anchor_resume branch) tell a genuinely recent
            # anchor apart from one that only LOOKS recent because
            # wall_start aliased across a ~24h-multiple outage.
            "anchor_written_at": broadcast_clock.now().timestamp(),
        }
        try:
            # Persistence split: this write touches ONLY playback_anchor --
            # nothing durable (schedules, broken_files, rotation) changed
            # alongside it (_clear_channel_playback_failure above only
            # touches an in-memory, never-persisted UI banner tracker). This
            # is also the single highest-frequency confirmed-play write in
            # the whole app, so routing it through the lightweight runtime-
            # only save (instead of save_settings_async's full config+
            # channels rewrite) keeps every ordinary channel change/
            # commercial cut/watchdog resume off the heavy disk-write path.
            db.save_playback_anchor()
        except Exception as e:
            log.warning("_confirm_playback_started: failed to persist playback_anchor for ch%s: %s", ch_key, e)


def _confirm_playback_failed(ch_key, attempt_id, file_path, deferred,
                              reason="deferred_open_failed", clear_live_channel=False):
    """Companion to _confirm_playback_started for the failure case -- a
    (usually deferred) open finished and VLC never actually accepted the
    file. Feeds the SAME ambiguous-failure counter/threshold every other
    playback failure goes through (_mark_file_broken), rather than a
    separate ad hoc path, so a drive-wide outage mid-stop-race still gets
    the drive-degraded bail-out and a single bad file still needs repeat
    failures before being blacklisted.
    """
    if vlc_engine is not None and getattr(vlc_engine, "_current_attempt_id", None) != attempt_id:
        log.info(
            "[ATTEMPT %s] on_confirmed(failure, ch%s): stale -- current attempt is now %s, "
            "not acting on this result", attempt_id, ch_key,
            getattr(vlc_engine, "_current_attempt_id", None) if vlc_engine else None,
        )
        return
    log.warning(
        "[ATTEMPT %s] Confirmed %sopen failure for ch%s: %s",
        attempt_id, "deferred " if deferred else "", ch_key, file_path,
    )
    if app_state.get("_live_playback_channel") == ch_key:
        app_state["is_playing_video"] = False
        if clear_live_channel:
            app_state["_live_playback_channel"] = ""
    if db is not None and file_path:
        _ch_info = db.channels_db.get(ch_key)
        if _ch_info is not None:
            try:
                _mark_file_broken(_ch_info, file_path, reason=reason)
            except Exception as e:
                log.warning("_confirm_playback_failed: _mark_file_broken failed for ch%s: %s", ch_key, e)
    try:
        _register_channel_playback_failure(ch_key, file_path)
    except Exception as e:
        log.warning("_confirm_playback_failed: _register_channel_playback_failure failed for ch%s: %s", ch_key, e)


def _draw_reason_banner_bar(screen, content_rect, label, scale=1.0):
    """Shared red-bar rendering for a failure/status label confined to
    content_rect. Both this and _draw_status_banner_bar are now drawn on the
    pre-composite virtual frame so they warp with the CRT/Bezel picture.

    Factored out of _draw_channel_failure_message so a second caller can
    build the same-looking banner from a label it already has, without
    needing a _channel_playback_failures registry entry to read one from --
    see _draw_channel_failure_message (registry-driven) and
    _draw_static_reason_banner (schedule-reason-driven) below.
    """
    try:
        font_size = max(9, round(18 * scale))
        font = _cached_sys_font("Arial", font_size, bold=True)
        text_surf = font.render(label, True, (255, 255, 255))
        pad_x, pad_y = max(4, round(14 * scale)), max(2, round(8 * scale))
        bar_w = text_surf.get_width() + pad_x * 2
        bar_h = text_surf.get_height() + pad_y * 2
        bar_w = min(bar_w, content_rect.width)
        bar_x = content_rect.x + (content_rect.width - bar_w) // 2
        bar_y = content_rect.bottom - bar_h - max(3, round(12 * scale))
        bar_surf = pygame.Surface((bar_w, bar_h), pygame.SRCALPHA)
        bar_surf.fill((120, 20, 20, 210))
        pygame.draw.rect(bar_surf, (255, 90, 90, 255), bar_surf.get_rect(), width=max(1, round(2 * scale)))
        screen.blit(bar_surf, (bar_x, bar_y))
        screen.blit(text_surf, (bar_x + pad_x, bar_y + pad_y))
    except Exception as e:
        log.warning("_draw_reason_banner_bar: draw failed: %s", e)


def _draw_channel_failure_message(screen, content_rect, ch_key, scale=1.0):
    try:
        entry = _channel_playback_failures.get(ch_key)
        if entry is None:
            return
        now = pygame.time.get_ticks()
        if now - entry["shown_at"] >= CHANNEL_FAILURE_MESSAGE_MS:
            return
        # "drive not responding" is a drive-wide condition, not a
        # file-specific playback failure.  The shared CHECK YOUR DRIVE
        # banner owns that case; drawing this entry too is what produced the
        # duplicate PLAYBACK FAILED + CHECK YOUR DRIVE pair.
        if _channel_failure_is_drive_wide(ch_key, entry):
            return
        _display_reason = entry['reason']
        if len(_display_reason) > 60:
            _display_reason = _display_reason[:57] + "..."
        label = f"PLAYBACK FAILED — {entry['file']} ({_display_reason})"
        _draw_reason_banner_bar(screen, content_rect, label, scale=scale)
    except Exception as e:
        log.warning("_draw_channel_failure_message: draw failed: %s", e)


def _draw_static_reason_banner(screen, content_rect, reason, reason_detail, scale=1.0):
    """Guide-preview-box counterpart to _draw_channel_failure_message, for a
    highlighted channel whose *schedule* resolved straight to Static
    (missing_media, channel_config_missing, timeline_build_failed, ... --
    see calculate_slotted_playback_state's Static return sites) rather than
    a VLC play attempt that was actually tried and failed.

    Those reasons never touch _channel_playback_failures -- there was
    nothing playable to even attempt loading, so play_file_segmented()/
    pygame.mixer.music.load() are never called and nothing ever registers a
    failure there. _draw_channel_failure_message has nothing to key off of
    for them, which is why the guide preview's Static-mode branch (the
    generic `else:` covering everything that isn't Video/Commercial/
    Visualizer/Visualizer_Empty) used to draw only the static noise and no
    banner at all for a highlighted TV station in this state, while the
    live full-screen fallback for the exact same reason already surfaces it
    via _report_missing_media/_draw_status_banner_bar. This reads the same
    reason/reason_detail that live path hands to _report_missing_media, and
    the same SILENT_STATIC_REASONS opt-out it uses -- an intentionally-idle
    channel (disabled, cleared schedule) still gets plain static in the
    preview with no banner, exactly like tuning to it live does.
    """
    if not reason or reason in SILENT_STATIC_REASONS:
        return
    _detail = reason_detail or "playback unavailable for this channel"
    _prefix = STATIC_FALLBACK_BANNER_PREFIX.get(reason, "PLAYBACK FAILED")
    label = f"{_prefix} — {_detail}"
    _draw_reason_banner_bar(screen, content_rect, label, scale=scale)

# Two independent bridge-frame caches, keyed by rendering context, instead
# of one shared global. The guide's preview box (small, px/py/pw/ph) and the
# fullscreen live-tv/DVD path (content_rect-sized) both fall back to
# "whatever the last decoded frame was" while a fresh VLC frame isn't ready
# yet -- but they are NOT the same frame. A single shared cache meant that
# storing the preview box's last frame (e.g. while previewing channel 06 in
# the guide) could then get picked up by the fullscreen fallback the instant
# you exited the guide onto a different channel (05), stretching that small
# preview frame up to fullscreen for a tick before the new channel's own
# video caught up -- the "old preview frame flashes fullscreen" bug.
# Keeping "preview" and "fullscreen" caches separate means each context can
# only ever bridge with its own last frame.
_LAST_VIDEO_FRAME_CONTEXTS = ("preview", "fullscreen")
_last_video_frame = {ctx: None for ctx in _LAST_VIDEO_FRAME_CONTEXTS}
_last_video_frame_raw = {ctx: None for ctx in _LAST_VIDEO_FRAME_CONTEXTS}
# The fit aspect (see _snap_standard_aspect) each cached frame was laid out
# with, kept per frame so a cached-frame redraw fits it exactly the way the
# fresh frame was -- not by whatever file is current by then.
_last_video_frame_fit_aspect = {ctx: None for ctx in _LAST_VIDEO_FRAME_CONTEXTS}
def _store_last_video_frame(surf, raw_surf=None, context="fullscreen", fit_aspect=None):
    """Caches the effects-applied frame for on-screen fallback display
    (_blit_last_video_frame), and separately caches the RAW pre-effects
    frame (raw_surf) so that fallback's Pan & Scan analysis stays
    consistent with the two live-decode call sites -- both of which
    already pass the raw frame as analysis_surf to
    _blit_video_with_screen_mode (see its docstring). Without this, the
    handful of ticks where no new VLC frame has arrived yet (frame-rate
    mismatch, brief buffering) fell back to re-analyzing the cached
    EFFECTS-applied frame instead, so Pan & Scan's cut/motion thresholds
    -- calibrated against raw footage -- would occasionally compare
    against a frame processed differently than its neighbors. raw_surf
    defaults to surf itself for callers that have no effects pipeline
    (DVD menus, visualizers) and are already handing over the true
    frame.

    fit_aspect: the fit aspect this frame was laid out with, if any -- see
    _last_video_frame_fit_aspect.

    context selects which independent cache ("preview" or "fullscreen")
    this frame belongs to -- see the module comment above
    _LAST_VIDEO_FRAME_CONTEXTS for why these must not share one cache."""
    _last_video_frame_fit_aspect[context] = fit_aspect
    try:
        _last_video_frame[context] = surf.copy()  # detach from VLC's reused byte buffer
    except Exception as e:
        log.warning("_store_last_video_frame: surf.copy() failed: %s", e)
    try:
        _last_video_frame_raw[context] = (raw_surf if raw_surf is not None else surf).copy()
    except Exception as e:
        log.warning("_store_last_video_frame: raw_surf.copy() failed: %s", e)
def _blit_last_video_frame(screen, x, y, w, h, apply_screen_mode=True, context="fullscreen", outer_rect=None):
    frame = _last_video_frame.get(context)
    if frame is None:
        return False
    try:
        if apply_screen_mode:
            # Fullscreen bridge frames must lay out exactly like the live
            # full-window frames -- see _video_screen_mode_rect's "FIX
            # (drop the pixel-aspect correction entirely)" comment.
            # pixel_aspect is always 1.0 now (both here and on the live-
            # frame call sites): the picture rides through Bezel's own
            # per-axis squish unmarked, same as every other content type.
            # mode: only the fullscreen context is inside the simulated
            # tube (see _bezel_video_fit_mode) -- the guide's small
            # preview box is not part of the Bezel stretch model and
            # keeps using whatever Screen Mode is actually selected.
            _pa = 1.0
            _fit_a = _last_video_frame_fit_aspect.get(context)
            if context == "fullscreen":
                try:
                    _pa = _video_pixel_aspect(screen.get_width(), screen.get_height(),
                                              _fit_a or frame.get_width() / frame.get_height())
                except Exception:
                    _pa = 1.0
            _mode = _bezel_video_fit_mode() if context == "fullscreen" else None
            _rect = pygame.Rect(x, y, w, h)
            if outer_rect is not None and (w < outer_rect.width or h < outer_rect.height):
                # (x, y, w, h) is the same true-4:3-vs-window boxed target
                # the live-frame call sites use (see _video_screen_mode_
                # rect) -- narrower than outer_rect (content_rect) whenever
                # Bezel is on. Without this, the gap between the two never
                # gets painted on a "no fresh frame this tick, reuse the
                # last one" tick, since _blit_video_with_screen_mode below
                # only fills its own (narrower) rect, leaving whatever was
                # drawn underneath on the previous frame showing through.
                screen.fill(_video_bar_color(), outer_rect)
            _blit_video_with_screen_mode(screen, frame, _rect, mode=_mode,
                                          analysis_surf=_last_video_frame_raw.get(context),
                                          pixel_aspect=_pa, fit_aspect=_fit_a)
        else:
            screen.blit(pygame.transform.smoothscale(frame, (w, h)), (x, y))
        return True
    except Exception:
        return False
def _has_last_video_frame(context="fullscreen"):
    return _last_video_frame.get(context) is not None
def _clear_last_video_frame(keep_shot_memory=False, context=None):
    """Clears the bridge-frame cache. context=None (the default) clears
    BOTH the preview and fullscreen caches, for callers that mean "start
    completely fresh" (app reset, stopping playback outright). Pass an
    explicit context to clear only that one cache -- e.g. the guide's
    row/channel-highlight-changed sites only want to drop the stale
    PREVIEW frame and must leave a still-live fullscreen bridge frame
    alone."""
    if context is None:
        for ctx in _LAST_VIDEO_FRAME_CONTEXTS:
            _last_video_frame[ctx] = None
            _last_video_frame_raw[ctx] = None
            _last_video_frame_fit_aspect[ctx] = None
    else:
        _last_video_frame[context] = None
        _last_video_frame_raw[context] = None
        _last_video_frame_fit_aspect[context] = None
    # A new video source (channel change, file reload, Screen Mode
    # change, etc.) has no relationship to wherever Pan & Scan's tracked
    # offset last drifted to on the OLD source -- always restart centered.
    # keep_shot_memory=True is for callers that know this is the SAME
    # content just being re-decoded (a Screen Mode reopen), so the
    # learned shot library survives the toggle -- see
    # _reset_pan_scan_state() for why that distinction matters.
    _reset_pan_scan_state(keep_shot_memory=keep_shot_memory)
    # NOTE: the watermark reads _last_screen_mode_picture_rect (see
    # _watermark_bounds_rect), which _blit_video_with_screen_mode()
    # overwrites on every call regardless of source -- nothing extra
    # to clear here on a source change.

def _seed_last_video_frame(dst_context, src_context):
    """Copies the src_context bridge frame (effects-applied + raw) over
    the dst_context one, in place of a clear.

    Guide-exit warm continuation (see change_channel) intentionally
    leaves vlc_engine running and skips the usual _clear_last_video_frame
    (context="fullscreen") call, because nothing about playback actually
    stopped. But the "fullscreen" cache was never being written to while
    the guide was open -- only "preview" was, on every decoded frame (see
    the guide-preview render loop) -- so it's still holding whatever
    frame was on screen before the guide was ever opened, which can be a
    completely different channel than the one just warm-continued onto.
    Skipping the clear avoided a wrong-channel flash turning into a
    blank/black one, but left the stale wrong-channel frame itself as the
    fallback fullscreen paints until vlc_engine's next fresh frame lands.
    Seeding "fullscreen" from "preview" here closes that gap: same file,
    same position, so it's a correct bridge frame instead of a stale
    one -- indistinguishable from the picture already on screen a moment
    ago in the preview box."""
    try:
        if _last_video_frame.get(src_context) is not None:
            _last_video_frame[dst_context] = _last_video_frame[src_context].copy()
        if _last_video_frame_raw.get(src_context) is not None:
            _last_video_frame_raw[dst_context] = _last_video_frame_raw[src_context].copy()
        _last_video_frame_fit_aspect[dst_context] = _last_video_frame_fit_aspect.get(src_context)
    except Exception as e:
        log.warning("_seed_last_video_frame: %s -> %s failed: %s", src_context, dst_context, e)

STATIC_TRANSITION_MS = 1500

DIGIT_ENTRY_SINGLE_MS = 2500
DIGIT_ENTRY_CONFIRM_MS = 350

# Set whenever guide navigation state (col/row/channel/abs_time) changes, so
# the background preloader thread (_guide_preload_worker) can wake up and
# rebuild the cached guide frame immediately instead of waiting for its next
# scheduled ~0.5s poll.
_guide_dirty_event = threading.Event()

GUIDE_PREVIEW_SETTLE_MS = 500

GUIDE_PREVIEW_LOAD_TIMEOUT_MS = 2500

PLAYBACK_STALL_TIMEOUT_MS = 10000

PLAYBACK_INITIAL_BUFFER_TIMEOUT_MS = 20000

# How long a channel can go with no new decoded frame before the on-screen
# fallback stops trusting the last frozen frame / cosmetic transition-style
# preference and just shows real static -- well under
# PLAYBACK_STALL_TIMEOUT_MS so a genuinely stuck channel (e.g. its file is
# on a drive that died mid-episode) visibly reads as "no signal" for a few
# seconds before the stall watchdog below gives up and surfs away, rather
# than silently freezing on the last good frame the whole time.
STALL_FORCES_STATIC_MS = 3000

# During a mid-stream episode/commercial handoff, VLC can deliver the first
# video frame before DirectSound has opened the replacement audio stream.
# Keep the transition surface up briefly so the new picture does not lead the
# new audio. Channel changes already have STATIC_TRANSITION_MS as their
# startup shield; this shorter hold is for the content-change path that does
# not pass through change_channel().
AUDIO_SYNC_HOLD_MS = 500

# A State.Ended/Stopped read that persists past the debounce above still
# isn't proof the file actually finished -- VLC can report a terminal state
# spuriously mid-playback (the same glitch class the debounce already
# targets), and acting on it triggers a full reload/advance, which is what
# reads on screen as a brief flash to static and back. Cross-check the
# terminal-state read against VLC's own reported position vs. its own
# reported length (both come straight from the engine, not the scheduler's
# duration estimate) before trusting it: only treat it as a real finish if
# playback position is within this many ms of the known length. If the
# length isn't known yet, there's nothing to cross-check against, so fall
# back to the state-only debounce.
_END_PROXIMITY_MS = 2000

WEDGED_STOP_TIMEOUT_S = 5

# NOTE: a personal boot-time anchor resume window (_BOOT_ANCHOR_MAX_AGE_S /
# _BOOT_ANCHOR_RESUME_WINDOW_S) previously lived here. It let a cold restart
# within ~30 minutes resume the exact paused file/second, like a DVR pause.
# That behavior was explicitly rejected by the user: this is a retro TV
# broadcast emulator, not a DVR -- there is no viewer-side pause/resume
# concept at any outage length. Removed outright rather than left disabled,
# so it can't be silently re-enabled later. See calculate_slotted_playback_
# state's cold-boot handling: every real restart now always falls through to
# the normal wall-clock schedule reconstruction, same as tuning into a live
# channel.

# How long play_file_segmented() waits, synchronously, for a pre-emptive
# stop() on the previous stream to actually finish before it's safe to
# call set_media()/play() on the next one. Calling those while stop() is
# still tearing down the previous stream races libVLC's own state
# machine -- the root cause behind the "buffer too late" frame drops on
# clip transitions and the spurious "reported ended" [WATCHDOG] events.
# Kept short: player.stop() on a healthy, non-stalled drive normally
# finishes in low single-digit milliseconds, so this is invisible in the
# common case. If it's ever exceeded, play_file_segmented() defers the
# open to a background thread instead of blocking further -- see its
# race-guard comment for the rest of that path.
_PLAY_SEGMENTED_STOP_FAST_WAIT_S = 0.05

# How long _seek_when_ready() will wait, after VLC first reports
# State.Playing with a known length, for the actual first post-warmup
# video frame to reach _vid_display_callback before issuing the seek.
# "Playing + known length" only means the file is open -- it does NOT
# mean the decode/render pipeline is empty. A preroll frame decoded at
# position 0 can still be in flight at that point, and calling
# set_time() out from under it is what produces the huge "buffer too
# late (-N us): dropped" clock-desync reads in vlc-debug.log (N tracks
# the seek target almost exactly), which is what intermittently flips
# VLC into a bogus Ended/Stopped state right after a resume -- and THAT
# is what the WATCHDOG's spurious-blip handling was looping on during
# fast channel-surfing. Bounded and short: the real first frame normally
# arrives within tens of ms of Playing (see vlc-debug.log timelines), so
# this is invisible in the common case; if it's ever exceeded (e.g. an
# unusual codec/audio-only edge case that never calls the display
# callback), _seek_when_ready seeks anyway rather than hanging.
_SEEK_FRAME_READY_GRACE_MS = 600

# True: the scheduled starting position is handed to VLC when the file is
# opened (":start-time"), so playback begins at that spot instead of opening
# at 0:00 and jumping there a moment later. _seek_when_ready() stays as the
# check and the fallback -- it only issues its own seek when VLC did not
# actually start near the target. Set to False to put every open back on
# open-at-0:00-then-seek.
SEEK_AT_OPEN = True

# How close a scheduled seek target is allowed to get to a file's cached
# duration before change_channel()'s seek-guard forces a fresh ffprobe
# instead of trusting the cache. See that guard's own comment for why:
# a cached duration this close to the seek target is the one case where
# a stale/placeholder value (e.g. a rounded default rather than a real
# probe result) reliably breaks the seek instead of just being imprecise.
_SEEK_GUARD_TAIL_MARGIN_S = 5.0



HEARTBEAT_WATCHDOG_TIMEOUT_MS = 45000

VLC_DEBUG_LOG_PATH = None

_vlc_log_queue = queue.Queue(maxsize=5000)

VLC_LOG_STALL_WARN_MS = 30000

def _start_guide_preview_load(hl_ch, hl_state):
    """Kick off (or, for a confirmed-dead channel, register the failure for)
    a guide-preview VLC load of hl_ch/hl_state's file.

    Factored out so the exact same load logic can run from two call sites:
    the render loop's own per-frame check (row switches, dead-drive
    recovery, load-timeout retries -- still gated there behind
    guide_preview_settled/not-already-in-flight/cache-mismatch, unchanged)
    and change_channel()'s guide-entry setup, which now fires this the
    instant we land on the guide instead of waiting for the render loop to
    notice current_channel == "04" on its next pass. Since the guide
    preview shares the single live vlc_engine with full-screen playback,
    the earliest this can possibly start is right after the old channel's
    content has been stopped -- which change_channel() already does
    earlier in the same call -- so firing it there instead of on the next
    render frame gives VLC the whole static/black transition burst as a
    head start on decoding, rather than only starting once the transition
    has already begun playing out and the guide is on screen.

    Caller is responsible for confirming vlc_engine is not None and
    hl_state["mode"] is Video/Commercial before calling.
    """
    _gp_dead_root = _station_confirmed_dead_drive.get(hl_ch)
    if _gp_dead_root is not None and _drive_confirmed_recovered(_gp_dead_root):
        _station_confirmed_dead_drive.pop(hl_ch, None)
        _clear_broken_files_for_root(_gp_dead_root)
        _gp_dead_root = None
    if _gp_dead_root is not None:
        app_state["loaded_preview_path_cache"] = hl_state["file"]
        app_state["guide_preview_loading"] = False
        _register_channel_playback_failure(
            hl_ch, hl_state["file"],
            duration=hl_state.get("duration"), block=hl_state.get("block"),
        )
        return
    try:
        vlc_engine.player.audio_set_mute(True)
    except Exception:
        pass
    app_state["_video_pending_unmute"] = True
    vlc_engine.stop()
    # The scheduler already computes the exact broadcast position. Do not
    # add a fixed startup pad: buffering time is variable, so a fixed
    # adjustment would make every guide preview seek systematically
    # inaccurate.
    _VLC_STARTUP_LATENCY_S = 0.0

    def _gp_on_confirmed(success, attempt_id, deferred,
                          _hl_ch=hl_ch, _hl_state=dict(hl_state)):
        if success:
            _confirm_playback_started(
                _hl_ch, attempt_id, _hl_state["file"],
                _hl_state.get("seek", 0) + _VLC_STARTUP_LATENCY_S,
                _hl_state.get("seek_slot_offset", 0),
                _hl_state.get("duration", 1800),
                _hl_state.get("mode", "Video"),
                _hl_state.get("block", "Morning"),
                _hl_state.get("interior_cut", False),
                deferred,
            )
        else:
            _confirm_playback_failed(_hl_ch, attempt_id, _hl_state.get("file"), deferred,
                                      reason="guide_preview_open_failed")

    # Stamped BEFORE the call, not after -- see the mid-stream-content-change
    # race note in change_channel(). Guide previews share the one live
    # vlc_engine, so a stale read here is exactly as able to trigger a
    # spurious duplicate open as any other call site.
    app_state["last_video_play_started_at"] = pygame.time.get_ticks()
    vlc_engine.play_file_segmented(
        hl_state["file"],
        hl_state["seek"],
        gain=_lookup_file_gain(hl_ch, hl_state["file"]),
        defer_unmute=True,
        on_confirmed=_gp_on_confirmed,
    )
    # Same bookkeeping every other real play_file_segmented() call site does
    # -- this is what the render loop's is_video_finished check (and, in
    # turn, the background continuity watchdog) uses to avoid mistaking a
    # video that only just started for one that's already ended.
    _mute_guard_log("ARM (guide preview load)", ch=hl_ch, filepath=hl_state["file"])
    app_state["loaded_preview_path_cache"] = hl_state["file"]
    app_state["guide_preview_loading"] = True
    app_state["guide_preview_load_started_ms"] = pygame.time.get_ticks()
    # NOTE: _live_playback_channel and playback_anchor are now written from
    # _gp_on_confirmed above, ONLY once VLC actually confirms this file is
    # open -- not unconditionally here. Previously this was set the instant
    # play_file_segmented() was CALLED, before it had even returned,
    # regardless of whether the file ever actually loaded; on a stop-race
    # (see play_file_segmented's [STOP RACE GUARD]) that recorded this
    # channel as "live" and persisted an anchor for a file that hadn't been
    # opened yet -- for the guide preview specifically, since return value
    # was never even captured here before.


def _arm_warm_transition_shield(engine, burst_ms):
    """Cosmetically cover a guide warm-continuation switch (ch05 <-> the
    guide previewing ch05, in either direction) with the configured
    Transition Type, without touching playback itself.

    The warm-continuation paths (see _guide_entry_warm_skip_stop /
    _guide_exit_warm_skip_stop in change_channel) deliberately never
    stop/reload vlc_engine -- that's the whole point of "warm": the file
    and position don't actually change, only whether it's shown
    full-screen or in the guide's preview box. Leave that alone. This just
    mutes audio for a fixed, burst_ms-long window (the caller has already
    armed the matching visual burst via channel_switch_black_until /
    guide_preview_*_until, which the existing render code already knows
    how to paint) and unmutes 1ms before that window ends on its own timer
    -- not on the frame that first notices the window is over, which is at
    least one frame (and, under load, sometimes noticeably more) late and
    produces audio that visibly lags the picture coming back.
    """
    try:
        engine.player.audio_set_mute(True)
    except Exception:
        pass

    def _do_unmute():
        time.sleep(max(0, burst_ms - 1) / 1000.0)
        try:
            engine.player.audio_set_mute(False)
        except Exception:
            pass

    import threading as _t
    _t.Thread(target=_do_unmute, daemon=True).start()


def _arm_guide_preview_transition():
    _transition_style = db.config.get("transition_type", "black") if db is not None else "black"
    if _transition_style == "static":
        app_state["guide_preview_black_until"] = 0
        app_state["guide_preview_static_until"] = pygame.time.get_ticks() + STATIC_TRANSITION_MS
    else:
        app_state["guide_preview_static_until"] = 0
        app_state["guide_preview_black_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS
    app_state["guide_preview_settle_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS

    # Reset load-tracking state for the new preview target.
    app_state["loaded_preview_path_cache"] = ""
    app_state["guide_preview_loading"] = False
    app_state["guide_preview_load_started_ms"] = 0

    # Mirror the VLC force-mute below for the visualizer preview's music
    # channel. Without this, pygame.mixer.music just keeps playing under
    # the static burst -- every downstream branch that would normally stop
    # it (Visualizer / Visualizer_Empty / the Video-Commercial preview's
    # own stop call) is gated behind "shield not active", so none of them
    # run again until the transition window ends.
    if pygame.mixer.music.get_busy():
        pygame.mixer.music.stop()
    # The guide preview may have been the last owner of the shared mixer.
    # Clear ownership before the new channel's activation is scheduled so a
    # visualizer cannot mistake preview audio for its live station audio.
    app_state["music_owner"] = ""
    app_state["guide_preview_music_track"] = ""

    if vlc_engine is not None and getattr(vlc_engine, "player", None) is not None:
        try:
            vlc_engine.player.audio_set_mute(True)
        except Exception:
            pass
    app_state["_video_pending_unmute"] = True
    _mute_guard_log("ARM (guide row switch)", ch=app_state.get("highlighted_guide_channel"))

_GUIDE_HL_STATE_REFRESH_MS = 1000

# How long we keep riding a resolved Video/Commercial file for a given guide
# highlight before asking the scheduler again. calculate_slotted_playback_state()
# walks the channel's whole raw_tracks list and sums each track's duration via
# resolve_track_duration(media_probe_cache, ...) -- for any track that hasn't
# been ffprobed yet that call falls back to a 1800s default. Background
# loudness/duration probes land continuously (see [MEDIA DURATION] /
# [LOUDNESS PROBE] logs) and overwrite those defaults with real numbers, so
# the *same* wall-clock instant can sum to a different cumulative total from
# one call to the next -- which walks the position pointer into a completely
# different episode. Re-walking the schedule on every refresh would mean
# landing on a new "current" file about once a second while someone just
# sat on a channel in the TV Guide -- reloading VLC and re-arming the mute
# each time, which shows up as the preview picture/static flickering on
# and off. Real live playback never hits this because it has its own
# trusted-anchor fast path (see _anchor_trusted above) that skips the walk
# entirely once a file is actually loaded and playing; the guide preview has
# no such anchor for a channel that isn't the one live on screen, so it's
# always taking the slow, probe-sensitive path. Riding the same resolved file
# and advancing its seek locally between refreshes avoids re-walking the
# schedule while probes are still in flight for that channel's tracks.
_GUIDE_HL_STATE_HOLD_MS = 8000


def _capture_guide_preview_position(ch_key):
    """Save the exact position of the preview before surfing to another row."""
    ch_key = str(ch_key).zfill(2)
    if ch_key != str(app_state.get("_live_playback_channel", "")).zfill(2):
        return
    if vlc_engine is None or getattr(vlc_engine, "player", None) is None:
        return
    try:
        current_ms = vlc_engine.player.get_time()
        current_media = vlc_engine.player.get_media()
        current_mrl = current_media.get_mrl() if current_media else ""
        if current_ms is None or current_ms < 0 or not current_mrl:
            return
        from urllib.parse import unquote as _unquote_preview
        current_file = os.path.normpath(
            _unquote_preview(current_mrl.replace("file:///", "")))
        now_ticks = pygame.time.get_ticks()
        preview_cache = app_state.setdefault("_guide_preview_position_cache", {})
        preview_cache[ch_key] = {
            "file": current_file,
            "seek": current_ms / 1000.0,
            "duration": max(1.0, (vlc_engine.player.get_length() or 0) / 1000.0),
            "captured_ticks": now_ticks,
        }
    except Exception as _preview_snapshot_err:
        log.debug("guide preview position snapshot unavailable: %s", _preview_snapshot_err)


def _get_guide_hl_playback_state(ch_key, slot="hl"):
    ch_key = str(ch_key).zfill(2)
    now_ticks = pygame.time.get_ticks()

    # Returning to a previously previewed row resumes the exact preview
    # position instead of re-resolving the schedule. Re-resolving can select
    # the next commercial or restart the current commercial when the shared
    # VLC engine is changed between guide rows.
    preview_cache = app_state.get("_guide_preview_position_cache", {})
    preview_resume = preview_cache.get(ch_key)
    if preview_resume and preview_resume.get("file"):
        _resume_seek = preview_resume.get("seek", 0) + (
            now_ticks - preview_resume.get("captured_ticks", now_ticks)
        ) / 1000.0
        _resume_dur = preview_resume.get("duration", 0)
        # The saved position only stays valid while the file it tracks is
        # still playing. Once it has run to its end (or its length was never
        # known, so that can't be told), the entry is dropped and the
        # schedule decides what is on -- otherwise the preview keeps
        # "resuming" an already-finished file at a position past its end
        # (black picture) and never moves on to the next show.
        if _resume_dur > 1.0 and _resume_seek < _resume_dur:
            resumed = dict(preview_resume)
            resumed["mode"] = (
                "Commercial"
                if _is_commercial_file_for_channel(ch_key, preview_resume["file"])
                else "Video"
            )
            resumed["seek"] = _resume_seek
            resumed["block"] = ""
            return resumed
        preview_cache.pop(ch_key, None)

    # If this channel's content is the thing actually loaded/warm-continuing
    # in vlc_engine right now (_live_playback_channel), calculate_slotted_
    # playback_state() hits its own trusted-anchor fast path for it -- a
    # cheap dict-field read, not the probe-sensitive full raw_tracks walk
    # this hold-cache exists to shield against (see the comment on
    # _GUIDE_HL_STATE_HOLD_MS above). Riding a locally-advanced stale seek
    # for up to 8s is strictly worse than just asking fresh every time in
    # that case: it's what let the background channel keep "looking" like
    # an old, already-finished item long after it had genuinely moved on,
    # producing a visible snap/glitch once the hold finally expired. Only
    # fall back to the ride-and-hold behavior below for channels that
    # AREN'T the live one, where the slow-path risk this cache was built
    # for still applies.
    _live_ch_now = app_state.get("_live_playback_channel", "")
    if _live_ch_now and ch_key == str(_live_ch_now).zfill(2):
        return calculate_slotted_playback_state(ch_key)

    cache_key = f"_guide_hl_state_cache_{slot}"
    cache = app_state.get(cache_key)
    if cache is not None and cache.get("ch") == ch_key:
        age_ms = now_ticks - cache.get("ts", -_GUIDE_HL_STATE_HOLD_MS)
        cached_state = cache.get("state", {})
        if (cached_state.get("mode") in ("Video", "Commercial")
                and cached_state.get("file")
                and age_ms < _GUIDE_HL_STATE_HOLD_MS):
            # Same file we already resolved for this highlight -- just move
            # its seek forward by however long it's actually been, instead of
            # re-walking the schedule (and risking a different-file result).
            ridden_state = dict(cached_state)
            ridden_state["seek"] = cached_state.get("seek", 0) + (age_ms / 1000.0)
            return ridden_state
        if age_ms < _GUIDE_HL_STATE_REFRESH_MS:
            return cached_state
    state = calculate_slotted_playback_state(ch_key)
    app_state[cache_key] = {"ch": ch_key, "state": state, "ts": now_ticks}
    return state

