HWND_TOPMOST    = -1
HWND_NOTOPMOST  = -2
SWP_NOMOVE      = 0x0002
SWP_NOSIZE      = 0x0001
SWP_SHOWWINDOW  = 0x0040
SW_RESTORE      = 9
SW_SHOWMAXIMIZED = 3
_WINDOW_COMMAND_EVENT = pygame.USEREVENT + 17


def _win32_force_foreground(hwnd):
    if sys.platform != "win32" or not hwnd:
        return False
    u32 = ctypes.windll.user32
    try:
        fg_hwnd = u32.GetForegroundWindow()
        if fg_hwnd == hwnd:
            return True

        cur_thread_id = ctypes.windll.kernel32.GetCurrentThreadId()
        fg_thread_id = u32.GetWindowThreadProcessId(fg_hwnd, None) if fg_hwnd else 0

        attached = False
        if fg_thread_id and fg_thread_id != cur_thread_id:
            try:
                attached = bool(u32.AttachThreadInput(cur_thread_id, fg_thread_id, True))
            except Exception:
                attached = False

        try:
            u32.AllowSetForegroundWindow(-1)
            u32.ShowWindow(hwnd, SW_RESTORE)
            u32.BringWindowToTop(hwnd)
            u32.SetForegroundWindow(hwnd)
            u32.SetActiveWindow(hwnd)
            u32.SetFocus(hwnd)
        finally:
            if attached:
                try:
                    u32.AttachThreadInput(cur_thread_id, fg_thread_id, False)
                except Exception:
                    pass

        return u32.GetForegroundWindow() == hwnd
    except Exception:
        return False


if sys.platform == "win32" and pygame_hwnd:
    ctypes.windll.user32.AllowSetForegroundWindow(-1)
    pygame.time.wait(100)
    ctypes.windll.user32.SetWindowPos(pygame_hwnd, HWND_TOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW)
    _focus_ok = _win32_force_foreground(pygame_hwnd)
    pygame.time.wait(50)
    ctypes.windll.user32.SetWindowPos(pygame_hwnd, HWND_NOTOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW)

    # The two calls above are a focus-steal trick (flash topmost, grab
    # foreground, drop back to normal z-order) and run unconditionally for
    # every boot, windowed or fullscreen. That last SetWindowPos always
    # un-pins topmost -- which silently undid the fullscreen/kiosk topmost
    # pin set earlier (see "_set_window_topmost(_boot_win_hwnd, topmost=True)"
    # above, guarded by _BOOT_FULLSCREEN): the window would end up NOT
    # topmost by the time boot finished, in fullscreen mode, defeating the
    # Keep fullscreen windows topmost after the focus-steal sequence.
    if _BOOT_FULLSCREEN:
        _set_window_topmost(pygame_hwnd, topmost=True)

    print(f"Window focus acquired={_focus_ok} (AttachThreadInput trick); "
          f"shell layer restored above window. at", time.time(), flush=True)

if sys.platform == "win32" and pygame_hwnd:
    _WM_APPCOMMAND   = 0x0319
    _WM_SYSCOMMAND   = 0x0112
    _SC_MINIMIZE     = 0xF020
    _GWLP_WNDPROC    = -4
    _FAPPCOMMAND_MASK = 0xF000

    _APPCOMMAND_TO_SDL_SC = {
        11: 286,
        12: 285,
        49: 286,
        50: 285,
    }

    _WndProcType = ctypes.WINFUNCTYPE(
        ctypes.c_ssize_t,
        ctypes.c_void_p,
        ctypes.c_uint,
        ctypes.c_size_t,
        ctypes.c_ssize_t,
    )

    ctypes.windll.user32.GetWindowLongPtrW.restype  = ctypes.c_void_p
    ctypes.windll.user32.GetWindowLongPtrW.argtypes = [ctypes.c_void_p, ctypes.c_int]
    ctypes.windll.user32.SetWindowLongPtrW.restype  = ctypes.c_void_p
    ctypes.windll.user32.SetWindowLongPtrW.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
    ctypes.windll.user32.CallWindowProcW.restype  = ctypes.c_ssize_t
    ctypes.windll.user32.CallWindowProcW.argtypes = [
        ctypes.c_void_p,
        ctypes.c_void_p,
        ctypes.c_uint,
        ctypes.c_size_t,
        ctypes.c_ssize_t,
    ]

    # NOTE: WM_APPCOMMAND handling below turns hardware media keys into SDL
    # key events; it is load-bearing.

    _orig_wndproc_ptr = None  # set below; pinned raw address of pygame/SDL's own WNDPROC

    def _app_wndproc(hwnd, msg, wParam, lParam):
        try:
            if msg == _WM_SYSCOMMAND and (int(wParam) & 0xFFF0) == _SC_MINIMIZE:
                # In the maximized-windowed state, the minus button means
                # "return to the fixed one-square window", not "hide in the

                # taskbar". The fixed window itself still uses normal Windows
                # minimize behavior because this branch only applies while
                # windowed_maximized is true.
                _state = globals().get("app_state")
                if (isinstance(_state, dict)
                        and _state.get("windowed_maximized", False)
                        and not _state.get("is_fullscreen", False)):
                    pygame.event.post(pygame.event.Event(
                        _WINDOW_COMMAND_EVENT,
                        window_action="restore_fixed_from_maximized_minimize",
                    ))
                    return 0
            elif msg == _WM_APPCOMMAND:
                lp = lParam & 0xFFFFFFFF
                hiword = (lp >> 16) & 0xFFFF
                cmd_id = hiword & ~_FAPPCOMMAND_MASK

                sc = _APPCOMMAND_TO_SDL_SC.get(cmd_id)
                if not sc:
                    sc = 500 + cmd_id
                pk = sc | _SDLK_MASK
                pygame.event.post(pygame.event.Event(
                    pygame.KEYDOWN, key=pk, scancode=sc, mod=0, unicode=""))
                pygame.event.post(pygame.event.Event(
                    pygame.KEYUP, key=pk, scancode=sc, mod=0, unicode=""))
                return 1  # tell Windows we handled it; suppress default action
        except Exception as _wndproc_err:
            log.warning(f"[APPCOMMAND] wndproc error (message passed through): {_wndproc_err}")
        return ctypes.windll.user32.CallWindowProcW(_orig_wndproc_ptr, hwnd, msg, wParam, lParam)

    try:
        _APPCMD_WNDPROC_PTR = _WndProcType(_app_wndproc)  # pinned — must not be GC'd
        _orig_wndproc_ptr = ctypes.windll.user32.SetWindowLongPtrW(
            pygame_hwnd, _GWLP_WNDPROC, ctypes.cast(_APPCMD_WNDPROC_PTR, ctypes.c_void_p))
        if _orig_wndproc_ptr:
            print("[BOOT] WM_APPCOMMAND diagnostic subclass installed.", flush=True)
        else:
            print("[APPCOMMAND] SetWindowLongPtrW returned NULL — subclass inactive.", flush=True)
    except Exception as _subclass_err:
        log.warning(f"[APPCOMMAND] subclass install failed: {_subclass_err}")


pygame.mouse.set_visible(False)

# Boot-splash progress bar geometry, measured directly against
# retro_tv_loading.png's own native pixel grid (2560x1440): the little
# cartoon TV's black-plastic body sits at roughly x=905-1488, y=409-934,
# leaving a clear blue gap from y=934 down to ~1015 (where the big TV's
# own screen-edge ring darkens) before the speaker-grille/red-light row's
# art would be crowded. The bar centers in that gap, under the cartoon
# TV's horizontal center. All four numbers are native-image pixels; both
# draw sites multiply by art_scale (dest_w / _lbg_w) so this stays correct
# at any window size. Re-measure these against the actual art any time
# retro_tv_loading.png is replaced -- they're specific to this image, not
# a proportion that holds for a differently laid-out splash.
# Shrunk down from the original 320x16 (it was crowding the cartoon TV's
# own on-screen art) and nudged a little further down the same blue gap
# to sit closer to the bottom of it instead of dead-center -- still fully
# clear of both the cartoon TV's body above and the speaker-grille row
# below at every art_scale.
_LOAD_BAR_CENTER_X = 1196
_LOAD_BAR_CENTER_Y = 988
_LOAD_BAR_WIDTH = 260
_LOAD_BAR_HEIGHT = 12
_LOAD_BAR_FONT_SIZE = 34
_LOAD_BAR_TEXT_GAP = 3   # was 10 -- tightened so the "NN%" label sits right
                          # above the bar instead of floating away from it.

base_dir = os.path.dirname(resolve_main_dir())
img_path = os.path.join(base_dir, "main", "images", "loading", "retro_tv_loading.png")

if os.path.exists(img_path):
    loading_bg_surface = pygame.image.load(img_path).convert()
    _lbg_w, _lbg_h = loading_bg_surface.get_size()
    _lbg_dest_w, _lbg_dest_h, _lbg_dest_x, _lbg_dest_y = _letterbox_fit(
        _lbg_w, _lbg_h, WINDOW_WIDTH, WINDOW_HEIGHT)
    screen.fill((1, 1, 1))  # bar color — not pure black, which is reserved as a transparency key elsewhere
    screen.blit(pygame.transform.scale(loading_bg_surface, (_lbg_dest_w, _lbg_dest_h)),
                (_lbg_dest_x, _lbg_dest_y))

    _init_art_scale = _lbg_dest_w / _lbg_w if _lbg_w else 1.0
    init_w = max(60, int(_LOAD_BAR_WIDTH * _init_art_scale))
    init_h = max(3, int(_LOAD_BAR_HEIGHT * _init_art_scale))

    init_x = _lbg_dest_x + int(_LOAD_BAR_CENTER_X * _init_art_scale) - init_w // 2
    init_y = _lbg_dest_y + int(_LOAD_BAR_CENTER_Y * _init_art_scale) - init_h // 2
    
    pygame.draw.rect(screen, (20, 30, 20), (init_x, init_y, init_w, init_h), border_radius=3)
    
    if DETECTED_ASPECT_RATIO != "4:3":
        try:
            _init_font_size = max(9, int(_LOAD_BAR_FONT_SIZE * _init_art_scale))
            _init_text_gap = max(2, int(_LOAD_BAR_TEXT_GAP * _init_art_scale))
            f_init_load = pygame.font.SysFont("Courier New", _init_font_size, bold=True)
            lbl_init_txt = f_init_load.render("0%", True, (0, 255, 128))
            
            # Centers the 0% digits exactly above the bar
            init_txt_x = _lbg_dest_x + int(_LOAD_BAR_CENTER_X * _init_art_scale) - lbl_init_txt.get_width() // 2
            init_txt_y = init_y - lbl_init_txt.get_height() - _init_text_gap
            screen.blit(lbl_init_txt, (init_txt_x, init_txt_y))
        except Exception as txt_init_err:
            log.warning(f"Could not pre-stamp frame-zero typography: {txt_init_err}")
    
    pygame.display.flip()
    print("Loading image displayed immediately. at", time.time(), flush=True)
else:
    loading_bg_surface = None
    screen.fill((5, 5, 5))
    pygame.display.flip()
    print("No loading image - using fallback black screen.")

pygame.event.pump()
print("Loading screen visible - window has popped up. at", time.time(), flush=True)


