# Contexts where the commit step (_fe_close) only ever honors a single
# picked file -- see each branch's own "Single-file pick -- take only
# the first checked file" comment. _fe_add_selected_to_queue() must
# replace, not append, whenever one of these is the active context (see
# that function's own docstring for why appending silently breaks
# picking a new file). "add_bios" is deliberately NOT in this set: its
# commit branch is a genuine multi-file pick (copies every checked file
# in, then auto-ranks which one becomes active), so accumulating
# several checked files there is intended behavior, not this bug.
_FE_SINGLE_PICK_MODES = {"libretro_core", "console_splash", "menu_bg", "watermark_select"}


_FE_LEFT_ITEMS_TTL_MS = 2000
_fe_left_items_cache = {"pc": None, "qa": None, "ts": -1_000_000}


def _fe_compute_this_pc_items():
    items = []
    if sys.platform == "win32":
        try:
            import ctypes as _cfe
            bitmask = _cfe.windll.kernel32.GetLogicalDrives()
            for i in range(26):
                if bitmask & (1 << i):
                    letter = chr(65 + i)
                    drive  = f"{letter}:\\"
                    items.append({"label": drive, "path": drive, "indent": 1, "is_header": False})
        except Exception:
            for letter in "CDEF":
                drive = f"{letter}:\\"
                if os.path.exists(drive):
                    items.append({"label": drive, "path": drive, "indent": 1, "is_header": False})
    else:
        items.append({"label": "/  (root)", "path": "/", "indent": 1, "is_header": False})
    return items


def _fe_compute_quick_access_items():
    items = []
    home = os.path.expanduser("~")
    seen = set()
    for name in ["Desktop", "Downloads", "Videos", "Documents", "Pictures", "Music"]:
        candidates = [os.path.join(home, name)]
        if sys.platform == "win32":
            candidates.append(os.path.join(os.environ.get("USERPROFILE", home), name))
        for p in candidates:
            # Guard with the same drive-responsiveness check playback uses
            # (media._is_drive_responsive) before touching the filesystem --
            # a cheap in-memory lookup against the background health monitor,
            # never a blocking syscall itself -- so a home folder that
            # happens to sit on a sleeping/disconnected/network drive can't
            # hang this on a raw os.path.isdir() call.
            if not media._is_drive_responsive(p):
                continue
            if os.path.isdir(p) and p not in seen:
                seen.add(p)
                items.append({"label": name, "path": p, "indent": 1, "is_header": False})
                break
    return items


def _fe_refresh_left_items_if_stale():
    """Caches both left-panel lists (drive letters + quick-access folders)
    with a short TTL so they aren't recomputed from scratch -- including a
    GetLogicalDrives() syscall and up to a dozen os.path.isdir()
    filesystem checks -- every single frame the file explorer is open.
    None of this ever changes meaningfully within a browsing session --
    drive letters and the user's home-folder layout don't shift moment to
    moment -- so a short TTL cache is exactly as fresh as it needs to be."""
    now = pygame.time.get_ticks()
    if (_fe_left_items_cache["pc"] is None
            or (now - _fe_left_items_cache["ts"]) >= _FE_LEFT_ITEMS_TTL_MS):
        _fe_left_items_cache["pc"] = _fe_compute_this_pc_items()
        _fe_left_items_cache["qa"] = _fe_compute_quick_access_items()
        _fe_left_items_cache["ts"] = now
    return _fe_left_items_cache["pc"], _fe_left_items_cache["qa"]


def _fe_get_this_pc_items():
    return _fe_refresh_left_items_if_stale()[0]


def _fe_get_quick_access_items():
    return _fe_refresh_left_items_if_stale()[1]


def _fe_left_layout(content_h):
    n1 = len(_fe_get_this_pc_items())
    n2 = len(_fe_get_quick_access_items())
    avail    = max(0, content_h - 2 * _FE_LEFT_ROW_H)   # minus the two fixed headers
    natural1 = n1 * _FE_LEFT_ROW_H
    natural2 = n2 * _FE_LEFT_ROW_H
    if natural1 + natural2 <= avail:
        h1, h2 = natural1, natural2
    elif natural1 <= avail // 2:
        h1 = natural1
        h2 = avail - h1
    elif natural2 <= avail // 2:
        h2 = natural2
        h1 = avail - h2
    else:
        h1 = avail // 2
        h2 = avail - h1
    rows1 = h1 // _FE_LEFT_ROW_H
    rows2 = h2 // _FE_LEFT_ROW_H
    return rows1, rows2


def _fe_get_saved_locations():
    """Return the raw list of saved-location paths (right-panel shortcuts)."""
    return db.config.get("fe_saved_locations", []) if db is not None else []


def _fe_get_saved_rows_top(content_y):
    return content_y + _FE_ADDLOC_HDR_H + 12


def _fe_get_addloc_rect(rp_x, rp_w, content_y, content_h):
    h = _FE_BTN_H - 6
    w = _FE_ADDLOC_W
    x = rp_x + (rp_w - w) // 2
    n_saved = len(_fe_get_saved_locations())
    y = _fe_get_saved_rows_top(content_y) + n_saved * _FE_LEFT_ROW_H + 12
    max_y = content_y + content_h - h - 8
    y = min(y, max_y)
    return pygame.Rect(x, y, w, h)


def _fe_add_saved_location():
    if db is None:
        return
    items = app_state.get("file_explorer_items", [])
    sel   = app_state.get("file_explorer_selection", set())
    if len(sel) != 1:
        return
    idx = next(iter(sel))
    if not (0 <= idx < len(items)) or items[idx]["type"] != "dir":
        return
    p = os.path.normpath(items[idx]["path"])
    saved = db.config.setdefault("fe_saved_locations", [])
    if p not in saved:
        saved.append(p)
        db.save_settings()


def _fe_remove_saved_location(path):
    """Remove a folder from the saved 'Add File Location' shortcuts list."""
    if db is None:
        return
    saved = db.config.get("fe_saved_locations", [])
    norm  = os.path.normpath(path)
    if norm in saved:
        saved.remove(norm)
        db.save_settings()


def _fe_get_items(path, valid_exts):
    """List `path`'s contents for the file explorer.

    A shortcut/symlink entry (.lnk, .url, or a POSIX symlink) is followed
    to whatever real file/folder it points at -- via
    media.resolve_dir_entry -- so a project folder organized with
    shortcuts (e.g. one channel's folder pointing at another channel's
    show folder instead of duplicating it) is browsed exactly like a
    real sub-folder or file would be, and the shortcut's own extension/
    " - Shortcut" suffix never shows up in the listed name.

    Every listed name also gets this context's "hide extra text"
    treatment -- clean_video_display_title for a video-extension
    listing, clean_music_display_title for an audio-extension listing,
    same cleaners the TV Guide / DVD splash / now-playing card use, so a
    show's season/rip-tag junk or a track's album-branding junk reads
    identically everywhere it's shown. Anything else (ROM folders, core
    files, image assets, etc.) is left as its shortcut-stripped name."""
    if not path:
        return []
    if not _is_drive_responsive(path):
        return []
    folders = []  # [(display_name, real_path)]
    files   = []  # [(display_name, real_path)]
    try:
        with os.scandir(path) as it:
            for entry in it:
                try:
                    kind, real_path, disp_name = media.resolve_dir_entry(entry.path, entry.name)
                except OSError:
                    # One unreadable/vanished/broken-shortcut entry must not abort the whole listing.
                    continue
                if kind == "dir":
                    folders.append((disp_name, real_path))
                elif kind == "file":
                    if valid_exts is None or os.path.splitext(real_path.lower())[1] in valid_exts:
                        files.append((disp_name, real_path))
    except (PermissionError, OSError):
        return []

    # Folders get the same treatment as this listing's files when the
    # context is unambiguously video or audio -- a show/album organized
    # as a rip-style folder name should hide the same junk a file of
    # that type would.
    folder_cleaner = None
    if valid_exts:
        if valid_exts & media.VIDEO_DISPLAY_EXTS:
            folder_cleaner = media.clean_video_display_title
        elif valid_exts & media.AUDIO_DISPLAY_EXTS:
            folder_cleaner = media.clean_music_display_title

    folders.sort(key=lambda x: x[0].lower())
    files.sort(key=lambda x: x[0].lower())
    result = []
    for disp_name, real_path in folders:
        label = folder_cleaner(disp_name) if folder_cleaner else disp_name
        result.append({"type": "dir", "name": label or disp_name, "path": real_path})
    for disp_name, real_path in files:
        ext = os.path.splitext(real_path)[1]
        label = media.clean_display_title_for_ext(disp_name, ext)
        result.append({"type": "file", "name": label or disp_name, "path": real_path})
    return result


def _fe_context_key(context):
    if not context:
        return None
    mode = context.get("mode")
    if mode == "schedule":
        return f"schedule:{context.get('ch','')}:{context.get('block','')}"
    if mode == "commercial":
        return f"commercial:{context.get('ch','')}:{context.get('block','')}"
    if mode == "holiday":
        return f"holiday:{context.get('ch','')}:{context.get('hkey','')}"
    if mode == "ch03_menu_music":
        return "ch03_menu_music"
    if mode == "scan_for_roms":
        return "scan_for_roms"
    if mode == "scan_for_cores":
        return "scan_for_cores"
    if mode == "add_roms":
        return f"add_roms:{context.get('console_key', '')}"
    return None


_fe_label_cache = {}


def _fe_cached_label(font, text, color):
    """Small cache for file-explorer row-label surfaces, avoiding a fresh
    font.render() call for every visible row every frame at 60fps -- for
    the item list, the two "This PC"/"Quick Access" left-panel sections,
    and the saved-locations panel, that's dozens of glyph-rasterization
    calls a frame even when the mouse hasn't moved and nothing on screen
    has actually changed (a row's label only changes when its text, or
    its hover/selection/checked color, changes). Re-rendering unmoved
    rows is pure wasted work competing with everything else in the frame
    (video decode, CRT shader, ...).

    Keyed on the exact (font, text, color) triple, so a cache hit is always
    pixel-identical to a fresh render -- this never trades away correctness
    for speed, it just avoids redoing work whose result can't have changed.
    Cleared on every directory navigation (see _fe_navigate) so it never
    grows past "this one directory's rows, in the couple of color variants
    they can appear in" regardless of how long a browsing session runs.
    """
    key = (id(font), text, color)
    surf = _fe_label_cache.get(key)
    if surf is None:
        surf = font.render(text, True, color)
        _fe_label_cache[key] = surf
    return surf


_FE_ICON_W = 14   # folder-glyph bounding-box width, in px
_FE_ICON_H = 11   # folder-glyph bounding-box height, in px
_FE_ICON_GAP = 6  # gap between the glyph and the item name that follows it


def _fe_draw_folder_icon(screen, x, y, color):
    """Draws a small closed-folder glyph with its top-left corner at (x, y).

    Only directory rows draw this -- file rows leave the space blank -- so a
    folder is visually distinct from a file at a glance instead of both
    looking like plain text rows. `color` carries the "has added/checked
    content somewhere inside" state (see has_added_inside in _fe_render):
    passing ADDED_C lights the icon itself up in place of a bracketed
    "[*] " text prefix for that case.
    """
    tab_w = _FE_ICON_W - 5
    tab_h = 3
    pygame.draw.rect(screen, color, (x, y, tab_w, tab_h))
    pygame.draw.rect(screen, color, (x, y + tab_h, _FE_ICON_W, _FE_ICON_H - tab_h))


def _fe_open(title, valid_exts, context):
    """Launch the file explorer overlay. Non-blocking — main loop drives it.

    valid_exts: a set of lowercase extensions (e.g. {".zip", ".7z"}) to
    show only matching files, an empty set() to show folders only (no
    files at all -- used by the bulk folder-scan pickers), or None to
    show every file regardless of extension (BIOS dumps, etc. show up
    in all sorts of formats). An empty set is NOT the same as "no
    filter" here -- membership in an empty set is never true -- so
    "allow everything" must be spelled as None, not set().
    """
    app_state["file_explorer_active"]         = True
    app_state["file_explorer_title"]          = title
    app_state["file_explorer_exts"]           = valid_exts
    app_state["file_explorer_cwd"]            = None
    app_state["file_explorer_items"]          = []
    app_state["file_explorer_scroll"]         = 0
    app_state["file_explorer_selection"]      = set()
    app_state["file_explorer_sel_anchor"]     = 0
    app_state["file_explorer_drag_start"]     = None
    app_state["file_explorer_drag_cur"]       = None
    app_state["file_explorer_last_click_ms"]  = 0
    app_state["file_explorer_last_click_idx"] = -1
    app_state["file_explorer_checked"]        = _fe_existing_schedule_paths(context)
    app_state["file_explorer_done_requested"] = False
    # Bump the session id and clear expand-in-flight bookkeeping. A folder
    # walk still running from an earlier session (e.g. user backed out and
    # reopened for a different channel) will finish tagged with a stale
    # session id and get dropped by _fe_poll_expand instead of merging into
    # this channel's checked list.
    app_state["file_explorer_session_id"]     = app_state.get("file_explorer_session_id", 0) + 1
    app_state["file_explorer_expand_pending"] = 0
    app_state["file_explorer_expand_started_ms"] = 0
    with app_state["file_explorer_expand_lock"]:
        app_state["file_explorer_expand_result"] = None
    app_state["file_explorer_context"]        = context
    app_state["file_explorer_left_sel"]       = -1
    app_state["file_explorer_left_scroll_pc"] = 0
    app_state["file_explorer_left_scroll_qa"] = 0
    app_state["file_explorer_rect"]           = None
    pygame.mouse.set_visible(True)
    surf = pygame.display.get_surface()
    if surf:
        sw, sh = surf.get_size()
        pygame.mouse.set_pos(sw // 2, sh // 2)
        snap = pygame.Surface((sw, sh))
        snap.blit(surf, (0, 0))
        app_state["_fe_snapshot"] = snap

    ck = _fe_context_key(context)
    if ck and db is not None:
        remembered = db.config.get("fe_last_cwd", {}).get(ck)
        if remembered and os.path.isdir(remembered):
            _fe_navigate(remembered)


def _fe_navigate(path):
    app_state["file_explorer_cwd"]        = path
    app_state["file_explorer_scroll"]     = 0
    app_state["file_explorer_selection"]  = set()
    app_state["file_explorer_sel_anchor"] = 0
    app_state["file_explorer_drag_start"] = None
    app_state["file_explorer_drag_cur"]   = None
    # Clear the stale listing right away -- see the docstring note above
    # this function for why leaving the old folder's rows on screen while
    # the new one is still being read is a problem, not just cosmetic.
    app_state["file_explorer_items"] = []
    pygame.event.clear(pygame.KEYDOWN)
    # New directory -> an entirely new set of row labels, so the cached
    # rasterized surfaces for the old listing are dead weight. Clearing
    # here (rather than letting it grow for the whole session) keeps
    # _fe_label_cache bounded to roughly "one directory's worth of rows,
    # in a couple of color variants" instead of accumulating every name
    # ever seen across a long browsing session.
    _fe_label_cache.clear()

    app_state["file_explorer_scan_request_id"] += 1
    req_id = app_state["file_explorer_scan_request_id"]
    with app_state["file_explorer_scan_lock"]:
        app_state["file_explorer_scan_result"] = None

    if path is None:
        app_state["file_explorer_items"]          = []
        app_state["file_explorer_scan_pending"]    = False
        app_state["file_explorer_scan_started_ms"] = 0
        return

    app_state["file_explorer_scan_pending"]    = True
    app_state["file_explorer_scan_started_ms"] = pygame.time.get_ticks()

    _valid_exts = app_state.get("file_explorer_exts", set())
    threading.Thread(
        target=_fe_scan_worker,
        args=(req_id, path, _valid_exts),
        daemon=True,
    ).start()


def _fe_scan_worker(req_id, path, valid_exts):
    items = _fe_get_items(path, valid_exts)
    with app_state["file_explorer_scan_lock"]:
        if req_id == app_state["file_explorer_scan_request_id"]:
            app_state["file_explorer_scan_result"] = items


def _fe_poll_scan():
    if not app_state.get("file_explorer_scan_pending", False):
        return

    with app_state["file_explorer_scan_lock"]:
        result = app_state["file_explorer_scan_result"]
        if result is not None:
            app_state["file_explorer_scan_result"] = None

    if result is not None:
        app_state["file_explorer_items"]          = result
        app_state["file_explorer_scan_pending"]    = False
        app_state["file_explorer_scan_started_ms"] = 0
        # Resolve a DONE that was deferred waiting on this scan (see the
        # "done" button handler). Only actually close if nothing else is
        # also still pending -- otherwise just let the now-populated list
        # render so the user can pick from it and press DONE again for real.
        if (app_state.get("file_explorer_done_requested", False)
                and app_state.get("file_explorer_expand_pending", 0) <= 0):
            app_state["file_explorer_done_requested"] = False
            _fe_close(True)
        return

    started_ms = app_state.get("file_explorer_scan_started_ms", 0)
    timeout_ms = app_state.get("file_explorer_scan_timeout_ms", 6000)
    if started_ms and (pygame.time.get_ticks() - started_ms) > timeout_ms:
        app_state["file_explorer_scan_request_id"] += 1  # invalidate the still-running thread's eventual result
        app_state["file_explorer_scan_pending"]    = False
        app_state["file_explorer_scan_started_ms"] = 0
        # Same stranded-DONE fallback _fe_poll_expand uses: don't leave the
        # picker looking permanently stuck if the folder scan never reports
        # back (e.g. unresponsive drive) after DONE was already clicked.
        if app_state.get("file_explorer_done_requested", False):
            app_state["file_explorer_done_requested"] = False
            _fe_close(True)


def _fe_poll_expand():
    result = None
    with app_state["file_explorer_expand_lock"]:
        result = app_state["file_explorer_expand_result"]
        if result is not None:
            app_state["file_explorer_expand_result"] = None
    if result is None:
        pending    = app_state.get("file_explorer_expand_pending", 0)
        started_ms = app_state.get("file_explorer_expand_started_ms", 0)
        timeout_ms = app_state.get("file_explorer_expand_timeout_ms", 6000)
        if pending > 0 and started_ms and (pygame.time.get_ticks() - started_ms) > timeout_ms:
            app_state["file_explorer_expand_request_id"] += 1  # invalidate any still-running thread's eventual result
            app_state["file_explorer_expand_pending"]    = 0
            app_state["file_explorer_expand_started_ms"] = 0
            # Don't strand a pending DONE click behind a scan that will
            # never report back (e.g. a folder on an unresponsive drive) --
            # finish with whatever was found before the timeout instead of
            # leaving the picker looking permanently stuck.
            if app_state.get("file_explorer_done_requested", False):
                app_state["file_explorer_done_requested"] = False
                _fe_close(True)
        return
    op, found, session_id = result
    if session_id != app_state.get("file_explorer_session_id", 0):
        # This walk belongs to a picker session that's since been closed
        # (the user backed out / opened a different channel's explorer
        # while it was still running) -- drop it instead of merging a
        # previous channel's files into this one's checked list.
        return
    app_state["file_explorer_expand_pending"] = max(0, app_state.get("file_explorer_expand_pending", 1) - 1)
    if app_state["file_explorer_expand_pending"] == 0:
        app_state["file_explorer_expand_started_ms"] = 0
    if op == "add":
        checked = app_state.setdefault("file_explorer_checked", [])
        checked_set = set(checked)
        for fp in found:
            if fp not in checked_set:
                checked_set.add(fp)
                checked.append(fp)
    elif op == "remove":
        to_remove = set(found)
        _locked = _fe_locked_playing_path(app_state.get("file_explorer_context", {}))
        if _locked and _locked in to_remove:
            # Same protection as the single-file remove path: a folder-level
            # remove (selecting a directory, then REMOVE SELECTED) walks
            # everything under it in the background -- don't let that sweep
            # up the file that's actively playing live right now.
            to_remove.discard(_locked)
            print(f"[FILE EXPLORER] Skipped removing {os.path.basename(_locked)} "
                  f"from folder-remove -- it's currently playing live on this channel.")
        checked = app_state.get("file_explorer_checked", [])
        app_state["file_explorer_checked"] = [f for f in checked if f not in to_remove]

    # If the user hit DONE while this (or another) folder expand was still
    # in flight, finish the job for them now instead of leaving them stuck
    # looking at a picker that appears to have ignored their click.
    if (app_state.get("file_explorer_done_requested", False)
            and app_state.get("file_explorer_expand_pending", 0) <= 0):
        app_state["file_explorer_done_requested"] = False
        _fe_close(True)


def _fe_go_up():
    cwd = app_state.get("file_explorer_cwd")
    if not cwd:
        return
    parent = os.path.dirname(cwd)
    _fe_navigate(None if parent == cwd else parent)



CH03_MUSIC_CHANNEL_ID = 2   # pygame.mixer.Channel reserved for ch03 menu

_ch03_music_sound_cache = {}     # track path -> (loaded pygame.mixer.Sound, playback_path_used)


def _get_ch03_music_channel():
    """Return the dedicated pygame Channel used for ch03 menu music."""
    return pygame.mixer.Channel(CH03_MUSIC_CHANNEL_ID)


def _resolve_compressor_playback_path(path):
    """Return the path that should actually be handed to a pygame loader
    for this track: a cached compressed render if one already exists and
    Loudness Scan is on, otherwise the raw source path (kicking off a
    background bake first, so the *next* load picks up the compressed
    version -- same "play raw now, hot-patch once the background pass
    lands" shape the per-file gain probe already uses for these paths).

    This is what makes ch03 game-channel music and the music visualizer
    get the same dynamics-compressor treatment TV stations and the DVD
    player already get live via VLC's --audio-filter=compressor, even
    though pygame has no live audio-filter chain to attach one to.
    """
    if not path:
        return path
    if db is None or not db.config.get("loudness_scan_enabled", True):
        return path
    _cached = get_cached_compressor_bake(path)
    if _cached:
        return _cached
    # No baked render yet -- kick a background bake and play the raw file
    # this time. The bake function has its own in-flight guard, so it's
    # safe to call this on every load attempt without piling up duplicate
    # ffmpeg processes for the same file.
    threading.Thread(
        target=bake_compressor_pass, args=(path,), daemon=True,
        name="compressor-bake",
    ).start()
    return path


def _load_ch03_music_sound(path):
    # Cache value is (Sound, playback_path_it_was_loaded_from) rather than
    # just the Sound, so a compressed bake that lands *after* the first
    # load (or a Loudness Scan toggle flip) is actually picked up on the
    # next play instead of the stale raw-audio buffer sticking around
    # forever -- pygame.Sound has no live-filter equivalent to hot-patch
    # in place, so "reload when the intended source changes" is the
    # closest match to how the VLC side hot-patches file_gain in place.
    _playback_path = _resolve_compressor_playback_path(path)
    _cached = _ch03_music_sound_cache.get(path)
    if _cached is not None and _cached[1] == _playback_path:
        return _cached[0]
    try:
        snd = pygame.mixer.Sound(_playback_path)
        _ch03_music_sound_cache[path] = (snd, _playback_path)
        return snd
    except Exception as e:
        log.warning(f"[CH03 MUSIC] Failed to load '{_playback_path}': {e}")
        return None


def _ch03_music_is_playing():
    """True if the dedicated ch03 music channel is actively playing."""
    return _get_ch03_music_channel().get_busy()


def _ch03_music_is_stalled():
    return False


def _set_ch03_menu_music_volume(raw_vol, muted=False):
    try:
        eff_vol = 0 if muted else _perceptual_volume_pct(raw_vol, min_db=STACKED_GAIN_MIN_DB)
        track_gain = _effective_loudness_gain(app_state.get("ch03_menu_music_gain", 1.0))
        gain = max(0.0, min(1.0, (eff_vol / 100.0) * MUSIC_GAIN * track_gain))
        _get_ch03_music_channel().set_volume(gain)
    except Exception as e:
        log.warning("_set_ch03_menu_music_volume: set_volume failed: %s", e)


def _set_dvd_volume(raw_vol, muted=False):
    try:
        if dvd_engine is None or game_deck is None:
            return
        if not getattr(game_deck, "dvd_playback_active", False):
            return
        if getattr(game_deck, "dvd_iso_backgrounded", False):
            return
        dvd_engine.set_volume(int(raw_vol), bool(muted))
    except Exception as e:
        log.warning("_set_dvd_volume: set_volume failed: %s", e)


def _apply_loudness_setting_live():
    """Reapply the current loudness policy to every active audio path.

    The Loudness Scan setting is a gain gate, not just a preference for the
    next file.  Existing VLC and pygame playback must be updated immediately
    when the toggle changes; otherwise the UI can say On/Off while the
    already-playing show continues at its previous gain.
    """
    if db is None:
        return
    _raw_volume = int(db.config.get("global_volume", 70))
    _muted = bool(db.config.get("is_muted", False))
    _target_gain = _perceptual_volume_pct(_raw_volume) / 100.0
    _music_gain = _perceptual_volume_pct(
        _raw_volume, min_db=STACKED_GAIN_MIN_DB
    ) / 100.0

    try:
        if vlc_engine is not None:
            vlc_engine.set_volume(_raw_volume, _muted)
    except Exception as e:
        log.warning("_apply_loudness_setting_live: main VLC refresh failed: %s", e)
    try:
        _set_dvd_volume(_raw_volume, _muted)
    except Exception as e:
        log.warning("_apply_loudness_setting_live: DVD refresh failed: %s", e)
    try:
        if static_audio is not None:
            static_audio.set_volume(
                _target_gain * _effective_loudness_gain(_STATIC_AUDIO_GAIN)
            )
    except Exception as e:
        log.warning("_apply_loudness_setting_live: static audio refresh failed: %s", e)
    try:
        pygame.mixer.music.set_volume(
            _music_gain * MUSIC_GAIN
            * _effective_loudness_gain(app_state.get("active_music_gain", 1.0))
        )
        pygame.mixer.Channel(1).set_volume(
            _music_gain * MUSIC_GAIN
            * _effective_loudness_gain(app_state.get("active_music_gain", 1.0))
        )
    except Exception as e:
        log.warning("_apply_loudness_setting_live: pygame music refresh failed: %s", e)
    try:
        if game_deck is not None and hasattr(game_deck, "set_libretro_volume"):
            game_deck.set_libretro_volume(_raw_volume, _muted)
        if game_deck is not None and hasattr(game_deck, "set_audio_volume"):
            game_deck.set_audio_volume(_raw_volume, _muted)
    except Exception as e:
        log.warning("_apply_loudness_setting_live: game-deck audio refresh failed: %s", e)
    _set_ch03_menu_music_volume(_raw_volume, _muted)
    log.info(
        "[LOUDNESS] Live gain policy reapplied: enabled=%s volume=%s muted=%s",
        bool(db.config.get("loudness_scan_enabled", True)),
        _raw_volume,
        _muted,
    )



ALL_REMOTE_ACTION_IDS = [a for a, _ in REMOTE_REMAP_ACTIONS] + [a for a, _ in NUMBER_REMAP_ACTIONS]

_REMAP_CAPTURE_DEDUP_MS = 600

MUSIC_GAIN = 1.0


def check_remap_conflict(db_inst, app_state, action_id, key_code):
    dvd_bindings = db_inst.config.get("dvd_bindings", {}) if db_inst is not None else {}
    dvd_label_by_action = dict(DVD_MAP_ACTIONS)
    for dvd_action_id, dvd_default_key in DVD_MAP_DEFAULTS.items():
        dvd_key = dvd_bindings.get(dvd_action_id, dvd_default_key)
        if dvd_key == key_code:
            return dvd_label_by_action.get(dvd_action_id, dvd_action_id) + " (DVD remote)"
    session_used = app_state.get("_remap_used_keys", [])
    if key_code in session_used:
        return "an action already mapped this session"
    return None


def set_remote_binding(db_inst, action, key_code):
    if db_inst is None:
        return
    bindings = db_inst.config.setdefault("remote_bindings", {})
    for act in ALL_REMOTE_ACTION_IDS:
        bindings.setdefault(act, CANONICAL_REMOTE_KEYS.get(act))

    bindings[action] = key_code

    db_inst.config["remote_bindings"] = bindings
    db_inst.save_settings()
    print(f"[REMOTE REMAP] '{action}' bound to {remote_key_label(key_code)}")


def translate_remote_key(db_inst, raw_key):
    if db_inst is None:
        return raw_key
    bindings = db_inst.config.get("remote_bindings", {})
    if not bindings:
        return raw_key
    for action, canon_key in CANONICAL_REMOTE_KEYS.items():
        if bindings.get(action, canon_key) == raw_key:
            return canon_key
    return raw_key


def set_dvd_binding(db_inst, action, key_code):
    if db_inst is None:
        return
    bindings = db_inst.config.setdefault("dvd_bindings", {})
    for act, canon in DVD_MAP_DEFAULTS.items():
        bindings.setdefault(act, canon)
    bindings[action] = key_code
    db_inst.config["dvd_bindings"] = bindings
    db_inst.save_settings()
    if game_deck is not None:
        try:
            game_deck.refresh_from_config(db_inst.config)
        except Exception as _e:
            log.warning(f"[DVD REMAP] game_deck refresh failed: {_e}")
    print(f"[DVD REMAP] '{action}' bound to {remote_key_label(key_code)}")


_CH03_DEFAULT_MUSIC_GAIN_PRECACHED = 0.31


def _ensure_ch03_menu_music_seeded():
    """Seed the ch03 menu-music playlist with the shipped default track if
    the playlist is still empty.

    Called once at boot, independent of the current channel, so the
    shipped default track ("gamemusic.mp3") is discoverable to the
    background loudness precache pass (_gather_probe_priority_queue) --
    which only scans db.config["ch03_menu_music"] when that list is
    non-empty -- immediately rather than only after channel 03 has been
    visited at least once.

    The seeded entry also carries gamemusic.mp3's known gain up front (see
    _CH03_DEFAULT_MUSIC_GAIN_PRECACHED, the same fix applied to
    static.wav): gamemusic.mp3 is a fixed shipped asset, from
    "[LOUDNESS PROBE] ch03 menu music 'gamemusic.mp3': gain x0.31" in
    app_log.txt, so first playback doesn't need to wait for a background
    scan to correct it away from the unscanned default of 1.0. A bare
    string entry (no "gain" key) would force that 1.0 default in
    _start_ch03_menu_music's `candidate.get("gain", 1.0)` lookup; seeding a
    dict with "gain" already set avoids it entirely.

    Unlike static.wav, there is no automatic safety net here if gamemusic.mp3
    is ever replaced with a different file at the same path: the background
    scanner explicitly skips any playlist entry that already has a "gain"
    key (see _gather_probe_priority_queue's ch03_menu_music tier), so a
    pre-seeded gain is permanent until changed by hand. If gamemusic.mp3 is
    ever swapped out, delete its "gain" key (or the whole ch03_menu_music
    config entry) so it gets re-measured, and update the constant below to
    match the new value once logged.
    """
    if db is None:
        return
    if db.config.get("ch03_menu_music", []):
        return
    _default = os.path.join(resolve_main_dir(), "audio", "gamemusic.mp3")
    if os.path.isfile(_default):
        db.config["ch03_menu_music"] = [
            {"path": _default, "gain": _CH03_DEFAULT_MUSIC_GAIN_PRECACHED}
        ]
        db.save_settings()
        print(f"[CH03 MUSIC] Seeded default track: {os.path.basename(_default)}")


def _start_ch03_menu_music():
    if db is None:
        return
    if app_state.get("current_channel") != "03":
        return
    if not db.config.get("ch03_menu_music_enabled", True):
        return
    _ensure_ch03_menu_music_seeded()
    playlist = db.config.get("ch03_menu_music", [])
    if not playlist:
        return
    if _ch03_music_is_playing():
        return
    playlist_len = len(playlist)
    track = None
    track_gain = 1.0
    for _attempt in range(playlist_len):
        idx = app_state.get("ch03_menu_music_idx", 0) % playlist_len
        candidate = playlist[idx]
        cand_path = candidate.get("path", "") if isinstance(candidate, dict) else str(candidate)
        if cand_path and os.path.isfile(cand_path):
            track = cand_path
            track_gain = candidate.get("gain", 1.0) if isinstance(candidate, dict) else 1.0
            break
        app_state["ch03_menu_music_idx"] = (idx + 1) % playlist_len
    if track is None:
        log.warning("[CH03 MUSIC] No playable tracks found in playlist -- all files missing.")
        return
    sound = _load_ch03_music_sound(track)
    if sound is None:
        app_state["ch03_menu_music_idx"] = (idx + 1) % len(playlist)
        return
    try:
        app_state["ch03_menu_music_gain"] = track_gain
        # Menu music must stay aware of a Static-transition burst still
        # covering the picture (channel_switch_black_until), the same way
        # every other audio source on ch03 (the libretro core / legacy-exe
        # game audio) is ducked via _ch03_static_mute_active in
        # _ch03_activate. Force-mute for the duration of the burst here
        # too, and let the same "_ch03_static_mute_active" restore in the
        # main loop (which already un-ducks the game audio at burst end)
        # un-duck this too.
        _mm_burst_active = (
            (db.config.get("transition_type", "black") if db else "black") == "static"
            and pygame.time.get_ticks() < app_state.get("channel_switch_black_until", 0)
        )
        _set_ch03_menu_music_volume(
            db.config.get("global_volume", 70),
            db.config.get("is_muted", False) or _mm_burst_active)
        if _mm_burst_active:
            app_state["_ch03_static_mute_active"] = True
        _get_ch03_music_channel().play(sound)
        app_state["ch03_menu_music_track"] = track
        app_state["ch03_menu_music_started_at"] = pygame.time.get_ticks()
        print(f"[CH03 MUSIC] Playing track {idx + 1}/{len(playlist)}: {os.path.basename(track)}")
    except Exception as _e:
        log.warning(f"[CH03 MUSIC] Failed to play '{track}': {_e}")
        app_state["ch03_menu_music_idx"] = (idx + 1) % len(playlist)


def _stop_ch03_menu_music():
    """Stop ch03 menu music if it is currently playing."""
    try:
        _get_ch03_music_channel().stop()
    except Exception as e:
        log.warning("_stop_ch03_menu_music: channel.stop() failed: %s", e)
    app_state["ch03_menu_music_track"] = ""
    app_state["ch03_menu_music_started_at"] = 0


def _adjust_ss_timer(delta, wrap=False):
    _cur_min = db.config.get("ch03_screensaver_timeout_min", 5)
    if wrap:
        _new_min = 5 if _cur_min >= 30 else _cur_min + delta
    elif delta < 0:
        _new_min = max(5, _cur_min + delta)
    else:
        _new_min = min(30, _cur_min + delta)
    db.config["ch03_screensaver_timeout_min"] = _new_min
    db.save_settings()
    log.warning(f"[GAMES] ch03 screen saver timeout = {db.config['ch03_screensaver_timeout_min']} min")


def _toggle_ss():
    """Flip the ch03 screen-saver enabled flag and persist it."""
    db.config["ch03_screensaver_enabled"] = not db.config.get("ch03_screensaver_enabled", True)
    db.save_settings()
    print(f"[GAMES] ch03 screen saver = {db.config['ch03_screensaver_enabled']}")


def _toggle_menu_music():
    """Flip the ch03 menu-music enabled flag, start/stop playback, and persist."""
    db.config["ch03_menu_music_enabled"] = not db.config.get("ch03_menu_music_enabled", True)
    db.save_settings()
    if db.config["ch03_menu_music_enabled"]:
        _start_ch03_menu_music()
    else:
        _stop_ch03_menu_music()
    print(f"[GAMES] ch03 menu music enabled = {db.config['ch03_menu_music_enabled']}")


def _toggle_all_consoles():
    from game_deck import CONSOLE_ORDER
    enabled_map = db.config.setdefault("consoles_enabled", {})
    others = [c for c in CONSOLE_ORDER if c != "DVD"]
    all_on = bool(others) and all(enabled_map.get(c, False) for c in others)
    new_state = not all_on
    for c in others:
        enabled_map[c] = new_state
    db.save_settings()
    if game_deck is not None:
        game_deck.refresh_from_config(db.config)
    print(f"[GAMES] all consoles set to {'ON' if new_state else 'OFF'} (DVD unaffected)")


def _toggle_all_profiles():
    db.config["all_profiles_sync"] = not db.config.get("all_profiles_sync", False)
    _mark_settings_dirty()
    print(f"[GAMES] all_profiles_sync (All Settings) = {db.config['all_profiles_sync']}")


def _adjust_all_settings_sync_profile(step, wrap=False):
    cur = int(db.config.get("all_profiles_sync_target", 1))
    new = cur + step
    if wrap:
        new = ((new - 1) % 3) + 1
    else:
        new = max(1, min(3, new))
    db.config["all_profiles_sync_target"] = new
    _mark_settings_dirty()
    print(f"[GAMES] all_profiles_sync_target (Sync Profile) = {new}")


def _sync_profile_setting_across_consoles(source_console, profile_num, key, value):
    if db is None or not db.config.get("all_profiles_sync", False):
        return
    if profile_num != int(db.config.get("all_profiles_sync_target", 1)):
        return
    from game_deck import CONSOLE_ORDER
    all_profiles_db = db.config.setdefault("console_profiles", {})
    for con in CONSOLE_ORDER:
        if con == source_console:
            continue
        profiles = (all_profiles_db
                    .setdefault(con, {"active": 1, "profiles": {}})
                    .setdefault("profiles", {}))
        if profile_num not in profiles and str(profile_num) in profiles:
            profiles[profile_num] = profiles.pop(str(profile_num))
        cfg = profiles.setdefault(profile_num, {"auto_save": False, "auto_load": False})
        cfg[key] = value
        if (game_deck is not None
                and getattr(game_deck, "_libretro_console", None) == con
                and int(db.config.get("console_profiles", {}).get(con, {}).get("active", 1)) == profile_num):
            if key == "auto_save":
                game_deck._libretro_auto_save = value
            elif key == "auto_load":
                game_deck._libretro_auto_load = value
            elif key == "border_enabled" and hasattr(game_deck, "set_border_live"):
                game_deck.set_border_live(value)
            elif key == "border_style" and hasattr(game_deck, "set_border_style_live"):
                game_deck.set_border_style_live(value)
            elif key == "screen_size":
                game_deck._libretro_screen_size = value
    print(f"[GAMES] all_profiles_sync mirrored {key}={value} from {source_console} "
          f"Profile {profile_num} (Sync Profile) to Profile {profile_num} on every other console")


def _set_console_bezel_enabled(console, profile_num, value):
    """Module-level version of the GAMES_SAVE_PROFILE screen's TV bezel
    toggle (used for both handheld and home-console bezels), callable from
    outside that menu layer -- needed so the Yes/No burn-in warning popup
    (which is handled in the global show_clear_confirm block, not nested
    inside that menu layer) can commit the change once the user confirms."""
    profiles = (db.config
                .setdefault("console_profiles", {})
                .setdefault(console, {"active": 1, "profiles": {}})
                .setdefault("profiles", {}))
    if profile_num not in profiles and str(profile_num) in profiles:
        profiles[profile_num] = profiles.pop(str(profile_num))
    cfg = profiles.setdefault(profile_num, {"auto_save": False, "auto_load": False})
    cfg["border_enabled"] = value
    _sync_profile_setting_across_consoles(console, profile_num, "border_enabled", value)
    db.save_settings()
    if (game_deck is not None
            and getattr(game_deck, "_libretro_console", None) == console
            and int(db.config.get("console_profiles", {}).get(console, {}).get("active", 1)) == profile_num):
        if hasattr(game_deck, "set_border_live"):
            game_deck.set_border_live(value)
        else:
            game_deck._libretro_border_enabled = value
    return value


def _set_console_bezel_style(console, profile_num, style):
    """Module-level version of the GAMES_SAVE_PROFILE screen's per-console
    TV bezel style picker (home/game consoles only -- see
    BORDER_CONSOLES_HOME), mirroring _set_console_bezel_enabled."""
    profiles = (db.config
                .setdefault("console_profiles", {})
                .setdefault(console, {"active": 1, "profiles": {}})
                .setdefault("profiles", {}))
    if profile_num not in profiles and str(profile_num) in profiles:
        profiles[profile_num] = profiles.pop(str(profile_num))
    cfg = profiles.setdefault(profile_num, {"auto_save": False, "auto_load": False})
    cfg["border_style"] = style
    _sync_profile_setting_across_consoles(console, profile_num, "border_style", style)
    db.save_settings()
    if (game_deck is not None
            and getattr(game_deck, "_libretro_console", None) == console
            and int(db.config.get("console_profiles", {}).get(console, {}).get("active", 1)) == profile_num):
        if hasattr(game_deck, "set_border_style_live"):
            game_deck.set_border_style_live(style)
        else:
            game_deck._libretro_border_style = style
    return style


def _fe_add_selected_to_queue():
    items      = app_state.get("file_explorer_items", [])
    sel        = app_state.get("file_explorer_selection", set())
    context    = app_state.get("file_explorer_context", {})
    valid_exts = app_state.get("file_explorer_exts", set())
    # Single-file-pick contexts (see _FE_SINGLE_PICK_MODES) must replace
    # rather than append here: their commit step only ever honors
    # checked[0], so if an earlier pick from this same browsing session
    # is still sitting at the front of the list, adding a different file
    # later just grows the list -- the old pick keeps silently winning
    # at commit, so selecting a new core/splash/etc. looks like it did
    # nothing (the old one stays "active"), because it never actually
    # got applied. Starting fresh here instead makes each Add Selected a
    # real replace for these, matching how the UI reads (only ever one
    # file picked at a time). Every other context keeps the normal
    # append-to-queue behavior.
    if context.get("mode", "") in _FE_SINGLE_PICK_MODES:
        checked = []
        app_state["file_explorer_checked"] = checked
    else:
        checked = app_state.setdefault("file_explorer_checked", [])
    checked_set = set(checked)   # one O(n) pass, not one per candidate file
    dirs_to_expand = []
    for idx in sorted(sel):
        if not (0 <= idx < len(items)):
            continue
        item = items[idx]
        p    = item["path"]
        if item["type"] == "dir":
            dirs_to_expand.append(p)
        elif item["type"] == "file":
            fp = os.path.normpath(p)
            if fp not in checked_set:
                checked_set.add(fp)
                checked.append(fp)
    app_state["file_explorer_selection"] = set()
    if dirs_to_expand:
        app_state["file_explorer_expand_request_id"] += 1
        req_id = app_state["file_explorer_expand_request_id"]
        session_id = app_state.get("file_explorer_session_id", 0)
        if app_state.get("file_explorer_expand_pending", 0) == 0:
            app_state["file_explorer_expand_started_ms"] = pygame.time.get_ticks()
        app_state["file_explorer_expand_pending"] += 1
        threading.Thread(
            target=_fe_expand_worker,
            args=(req_id, "add", dirs_to_expand, valid_exts, session_id),
            daemon=True,
        ).start()


def _fe_add_selected_rom_folder():
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})
    ck      = context.get("console_key", "")

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    from game_deck import ROM_EXTENSIONS
    exts = set(ROM_EXTENSIONS.get(ck, []))
    n_found = 0
    try:
        if _is_drive_responsive(picked_dir):
            with os.scandir(picked_dir) as it:
                for entry in it:
                    if entry.is_file() and os.path.splitext(entry.name.lower())[1] in exts:
                        n_found += 1
    except Exception as _se:
        log.warning(f"[GAMES] Could not count ROMs in {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_found
    app_state["file_explorer_checked"]   = [""] * n_found
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] {ck}: {n_found} ROM(s) found in {picked_dir}")


def _fe_add_selected_scan_folder():
    """"Scan For Roms" folder pick — unlike _fe_add_selected_rom_folder this
    isn't tied to one console, so it just marks the picked folder and gives
    a quick, cheap depth-1 preview (how many immediate subfolders' names
    match a known console) rather than the full recursive scan, which
    happens for real at commit time via game_deck.bulk_scan_for_roms()."""
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    from game_deck import match_console_for_folder_name
    n_matched = 0
    try:
        if _is_drive_responsive(picked_dir):
            base_name = os.path.basename(picked_dir.rstrip("\\/"))
            if match_console_for_folder_name(base_name):
                n_matched = 1  # the picked folder itself is console-named
            else:
                with os.scandir(picked_dir) as it:
                    for entry in it:
                        if entry.is_dir() and match_console_for_folder_name(entry.name):
                            n_matched += 1
    except Exception as _se:
        log.warning(f"[GAMES] Could not preview {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_matched
    # Sentinel so the footer reads "folder selected" -- the real recursive
    # scan (which is what actually finds/counts roms) only runs on commit.
    app_state["file_explorer_checked"]   = ["x"]
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] Scan For Roms: {picked_dir} selected "
          f"({n_matched} console-named folder(s) matched at top level)")


def _fe_add_selected_scan_cores_folder():
    """"Scan For Cores" folder pick -- cheap depth-2 preview (how many
    *_libretro.dll files sit directly in the picked folder, or one level
    down, e.g. a RetroArch root whose actual cores/ folder is the child
    being previewed) rather than the full recursive scan, which happens
    for real at commit time via game_deck.bulk_scan_for_cores()."""
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    n_matched = 0
    try:
        if _is_drive_responsive(picked_dir):
            with os.scandir(picked_dir) as it:
                for entry in it:
                    if entry.is_file() and entry.name.lower().endswith("_libretro.dll"):
                        n_matched += 1
                    elif entry.is_dir() and not entry.name.startswith((".", "$")):
                        try:
                            with os.scandir(entry.path) as it2:
                                for entry2 in it2:
                                    if entry2.is_file() and entry2.name.lower().endswith("_libretro.dll"):
                                        n_matched += 1
                        except Exception:
                            pass
    except Exception as _se:
        log.warning(f"[GAMES] Could not preview {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_matched
    # Sentinel so the footer reads "folder selected" -- the real recursive
    # scan (which is what actually finds/copies cores) only runs on commit.
    app_state["file_explorer_checked"]   = ["x"]
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] Scan For Cores: {picked_dir} selected "
          f"({n_matched} core .dll(s) found within 2 levels)")


def _fe_expand_worker(req_id, op, dir_paths, valid_exts, session_id=0):
    ignored_dirs = {
        "sample", "samples", "extras", "extra", "bonus", "featurettes",
        "behind the scenes", "trailers", "trailer", "subs", "subtitles",
        "loudness",
    }
    found = []
    seen = set()
    for p in dir_paths:
        if not _is_drive_responsive(p):
            continue
        # Shortcut/symlink-aware walk -- a channel's project folder can
        # reference another folder's content via a .lnk/.url/symlink
        # instead of duplicating files on disk, and this should be
        # picked up here exactly like a real sub-folder would be.
        for fp in media.iter_files_resolving_shortcuts(
                p, ignored_dir_names=ignored_dirs, valid_exts=valid_exts,
                is_drive_responsive=_is_drive_responsive):
            fp = os.path.normpath(fp)
            if fp not in seen:
                seen.add(fp)
                found.append(fp)
    with app_state["file_explorer_expand_lock"]:
        app_state["file_explorer_expand_result"] = (op, found, session_id)


def _get_part_group_key(norm_path):
    if not norm_path:
        return None
    info = _movie_part_info({"path": norm_path})
    if info is None:
        return None
    base, _num = info
    return f"{os.path.dirname(norm_path).lower()}::{base}"


def _get_part_group_gain_cache_entry(group_key):
    if db is None or not group_key:
        return None
    return db.config.get("_part_group_gain_cache", {}).get(group_key)


def _set_part_group_anchor_gain(group_key, norm_path, gain):
    if db is None or not group_key or gain is None:
        return
    cache = db.config.setdefault("_part_group_gain_cache", {})
