def _get_cached_media_probe(norm_path):
    if db is None:
        return {}
    return db.config.get("media_probe_cache", {}).get(norm_path, {})


# --- Loudness-result checkpointing ---------------------------------------
# A finished gain used to live only in memory until some caller's batch save
# (every 5-25 files) or the clean-quit save happened to run, so a hard kill,
# crash or watchdog relaunch could throw away a whole batch of finished scans
# and redo them next launch. Now every stored gain schedules a throttled save:
# at most one write per _PROBE_CHECKPOINT_MIN_INTERVAL_S, with a trailing save
# so the last results of a burst are never left unsaved.
_PROBE_CHECKPOINT_MIN_INTERVAL_S = 8.0
_probe_checkpoint_lock = threading.Lock()
_probe_checkpoint_last = 0.0
_probe_checkpoint_timer = None


def _probe_checkpoint_save_now():
    global _probe_checkpoint_last, _probe_checkpoint_timer
    with _probe_checkpoint_lock:
        _probe_checkpoint_last = time.monotonic()
        _probe_checkpoint_timer = None
    try:
        if db is not None:
            db.save_settings_async()
    except Exception as _cp_e:
        log.warning(f"[PROBE CHECKPOINT] save failed (non-fatal): {_cp_e}")


def _checkpoint_probe_cache():
    global _probe_checkpoint_timer
    if db is None:
        return
    with _probe_checkpoint_lock:
        _wait = _PROBE_CHECKPOINT_MIN_INTERVAL_S - (time.monotonic() - _probe_checkpoint_last)
        if _wait > 0:
            if _probe_checkpoint_timer is None:
                _probe_checkpoint_timer = threading.Timer(_wait, _probe_checkpoint_save_now)
                _probe_checkpoint_timer.daemon = True
                _probe_checkpoint_timer.start()
            return
    _probe_checkpoint_save_now()


def _store_cached_media_probe(norm_path, duration=None, gain=None, dims=None):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    _wrote_measurement = False
    _gain_written = False
    if duration and duration > 0:
        entry["duration"] = int(duration)
        entry["duration_source"] = "probed"
        _wrote_measurement = True
    if gain:
        entry["gain"] = gain
        _wrote_measurement = True
        _gain_written = True
    if dims and len(dims) == 2 and dims[0] and dims[1]:
        entry["dims"] = [int(dims[0]), int(dims[1])]
        _wrote_measurement = True
    if _wrote_measurement:
        # Provenance fingerprint (fix #7): stamp what the file looked like
        # AT THE MOMENT it was actually measured, so a later check can tell
        # "still the same file" apart from "this path was replaced/
        # re-encoded since we last probed it". Without this, a swapped-in
        # file with a different real length keeps serving its old, now-
        # wrong duration forever -- silently reshaping the timeline around
        # a number that's no longer true, with nothing to ever notice.
        # A cache entry from before this fix simply has no fingerprint;
        # every reader below treats that as "unknown, trust it" rather
        # than forcing a mass re-probe of an existing library on upgrade.
        try:
            _st = os.stat(norm_path)
            entry["measured_at"] = time.time()
            entry["measured_mtime"] = _st.st_mtime
            entry["measured_size"] = _st.st_size
        except OSError:
            pass
    if _gain_written:
        # After the fingerprint stamp above so the saved entry is complete.
        _checkpoint_probe_cache()


def _media_probe_fingerprint_stale(norm_path, entry):
    """True only if `entry` (a media_probe_cache value) carries a
    provenance fingerprint from _store_cached_media_probe AND a live stat()
    of norm_path no longer matches it -- i.e. the file has been genuinely
    replaced/modified since its duration/gain/dims were last measured.

    An entry with no fingerprint (written before this fix, or missing
    fields for any reason) is never treated as stale here -- see the
    module note above _store_cached_media_probe for why that matters.
    """
    if not isinstance(entry, dict):
        return False
    _mtime = entry.get("measured_mtime")
    _size = entry.get("measured_size")
    if _mtime is None or _size is None:
        return False
    try:
        _st = os.stat(norm_path)
    except OSError:
        return False
    return _st.st_mtime != _mtime or _st.st_size != _size


# ---------------------------------------------------------------------------
# Orphan pruning for the persisted per-path caches. Each of these caches
# exists purely to avoid redoing one-time work (a probe, a caption resolve,
# a gain measurement, a renormalization pass) on a file we've already
# handled -- once that file is gone from disk for good, its entry is
# reuse-value-zero and just sits in the config JSON forever otherwise.
#
# dvd_resume_positions is deliberately NOT included here: a resume position
# is something worth restoring (e.g. an external drive that's merely
# unplugged, not gone), so it stays out of this sweep regardless of
# whether the file is currently reachable.
# ---------------------------------------------------------------------------

# media_probe_cache / caption_cache are keyed by os.path.normpath(...).lower()
_LOWERCASED_KEY_PATH_CACHES = ("media_probe_cache", "caption_cache")
# dvd_gain_cache / _renorm_sweep_processed are keyed by plain os.path.normpath(...)
_RAW_KEY_PATH_CACHES = ("dvd_gain_cache", "_renorm_sweep_processed")

_ORPHAN_CACHE_PRUNE_INTERVAL_S = 1800  # every 30 minutes -- pure housekeeping, no rush


def _prune_orphaned_path_caches():
    """Drop entries from the persisted per-path caches whose file no
    longer exists on disk. Uses _cached_path_exists() (not a raw
    os.path.exists()) so a drive that's merely unresponsive right now
    fails OPEN and its entries are left alone, rather than getting wiped
    out just because it's temporarily unreachable.

    Also self-heals media_probe_cache entries for files that are still
    present but have been replaced/re-encoded since they were last
    measured (fix #7): a file can go stale without ever going missing, so
    that can't be caught by the orphan check above. Reuses this same
    already-scheduled periodic pass rather than adding a second background
    loop just for this.
    """
    if db is None:
        return {}
    removed_counts = {}
    for cache_name in _LOWERCASED_KEY_PATH_CACHES + _RAW_KEY_PATH_CACHES:
        cache = db.config.get(cache_name)
        if not cache:
            continue
        orphans = [k for k in cache.keys() if not _cached_path_exists(k)]
        for k in orphans:
            cache.pop(k, None)
        if orphans:
            removed_counts[cache_name] = len(orphans)

    _probe_cache = db.config.get("media_probe_cache")
    if _probe_cache:
        _stale_fp = [k for k, v in _probe_cache.items()
                     if _media_probe_fingerprint_stale(k, v)]
        for k in _stale_fp:
            _probe_cache.pop(k, None)
        if _stale_fp:
            removed_counts["media_probe_cache (stale fingerprint)"] = len(_stale_fp)
            log.info(
                "[DURATION PROVENANCE] %d file(s) changed on disk since "
                "their duration/gain/dims were last measured -- cleared "
                "their stale probe cache entr%s so they get re-measured "
                "instead of continuing to use numbers for a file that no "
                "longer exists in that form: %s",
                len(_stale_fp), "y" if len(_stale_fp) == 1 else "ies", _stale_fp[:5],
            )

    if removed_counts:
        total = sum(removed_counts.values())
        log.info(
            "[CACHE PRUNE] removed %d orphaned entr%s for files no longer "
            "on disk: %s", total, "y" if total == 1 else "ies", removed_counts,
        )
        try:
            db.save_settings_async()
        except Exception as e:
            log.warning(f"[CACHE PRUNE] save after prune failed: {e}")
    return removed_counts


def _orphan_cache_prune_loop():
    """Background sweep that periodically runs _prune_orphaned_path_caches().
    Long interval on purpose -- this is bookkeeping, not anything the UI
    is waiting on, and every path in every cache gets a fresh existence
    check each pass (real disk I/O -- an os.stat/os.path.exists per cached
    path, potentially thousands of them).

    FIX: previously had no pause/pace logic at all -- a fixed 30-minute
    sleep regardless of what else was going on, so this sweep could still
    land its one disk-I/O-heavy pass in the middle of a game or a
    heavy-effects menu purely by chance. Now delegates to the same shared
    checks every other background tier uses: waits out
    _background_scan_should_pause() before starting a pass (so it never
    kicks off while a game is actually being played or frame time is
    already past FRAME_STALL_HARD_MS), and paces the between-pass interval
    through _background_scan_pace_seconds() so the already-long interval
    stretches out further under sustained load instead of firing on a
    fixed clock regardless.
    """
    if _app_shutting_down.wait(_background_scan_pace_seconds(_ORPHAN_CACHE_PRUNE_INTERVAL_S)):
        return
    while True:
        while _background_scan_should_pause():
            if _app_shutting_down.wait(2.0):
                return
        try:
            _prune_orphaned_path_caches()
        except Exception as e:
            log.warning(f"[CACHE PRUNE] sweep iteration failed: {e}")
        if _app_shutting_down.wait(_background_scan_pace_seconds(_ORPHAN_CACHE_PRUNE_INTERVAL_S)):
            return


_LOUDNESS_TIMEOUT_BACKOFF_S = (600, 1800, 7200, 21600)


def _loudness_backoff_seconds(streak):
    idx = min(max(streak, 1) - 1, len(_LOUDNESS_TIMEOUT_BACKOFF_S) - 1)
    return _LOUDNESS_TIMEOUT_BACKOFF_S[idx]


def _loudness_probe_in_cooldown(norm_path):
    if db is None or not norm_path:
        return False
    entry = db.config.get("media_probe_cache", {}).get(norm_path, {})
    next_retry = entry.get("loudness_next_retry_ts")
    if not next_retry:
        return False
    _in_cooldown = time.time() < next_retry
    if _in_cooldown:
        # Logged so a file sitting at the front of every priority tier
        # doesn't silently never get probed (no [LOUDNESS PROBE], no
        # timeout warning, nothing) with no way to tell "hasn't been
        # reached yet" apart from "actively being skipped" from the log
        # alone. Throttled per-path so a file sitting in a multi-hour
        # backoff (see _LOUDNESS_TIMEOUT_BACKOFF_S) doesn't spam this on
        # every sweep pass / tune-in / toggle check.
        _log_warn_throttled(
            f"loudness_cooldown_{norm_path}",
            "[LOUDNESS PROBE] Skipping '%s' -- still in post-timeout cooldown "
            "for %.0fs more (streak %s)",
            os.path.basename(norm_path), next_retry - time.time(),
            entry.get("loudness_timeout_streak", "?"),
            interval=60.0,
        )
    return _in_cooldown


def _record_loudness_timeout(norm_path):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    streak = entry.get("loudness_timeout_streak", 0) + 1
    entry["loudness_timeout_streak"] = streak
    backoff = _loudness_backoff_seconds(streak)
    entry["loudness_next_retry_ts"] = time.time() + backoff
    log.warning(f"[LOUDNESS PROBE] {os.path.basename(norm_path)}: timed out on every "
          f"window (streak {streak}) -- backing off {backoff}s before retrying")


def _clear_loudness_timeout_streak(norm_path):
    if db is None or not norm_path:
        return
    entry = db.config.get("media_probe_cache", {}).get(norm_path)
    if entry and ("loudness_timeout_streak" in entry or "loudness_next_retry_ts" in entry):
        entry.pop("loudness_timeout_streak", None)
        entry.pop("loudness_next_retry_ts", None)


_probe_dispatch_lock = threading.Lock()
_probe_dispatch_inflight = set()


def _probe_marker_path():
    """Path to the tiny standalone "currently probing this" marker file.
    Deliberately NOT part of the main config JSON: that snapshot can be
    large and its save is debounced/threaded, so forcing a full config
    write before every single file probe (there can be hundreds in one
    scan) would be slow and defeats the purpose -- we need this marker to
    be on disk, fsynced, *before* the probe starts, every single time,
    cheaply. A one-line sidecar file gets us that durability without the
    overhead."""
    if db is None:
        return None
    return os.path.join(db.base_dir, "_probe_inflight.json")


def _write_probe_marker(norm_p, field):
    """Durably record that a probe is about to start, so a crash / force
    -close / power loss mid-probe leaves proof on disk of exactly which
    file+field was in flight. fsync'd and atomically renamed into place so
    a kill at any point either leaves the old marker or the new one, never
    a half-written one."""
    marker_path = _probe_marker_path()
    if not marker_path:
        return
    try:
        import json as _json
        tmp_path = marker_path + ".tmp"
        with open(tmp_path, "w") as f:
            _json.dump({"path": norm_p, "field": field, "ts": time.time()}, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, marker_path)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to write probe-in-progress marker: {e}")


def _clear_probe_marker(norm_p, field):
    """Remove the in-flight marker once a probe finishes (success, failure,
    or exception -- _release_probe's finally: block guarantees this runs
    either way). Only clears it if it still matches what we started, so a
    stale clear from an old/finished probe can't stomp a newer marker."""
    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return
    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
        if marker.get("path") == norm_p and marker.get("field") == field:
            os.remove(marker_path)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to clear probe-in-progress marker: {e}")


def _note_probe_started(norm_p, field):
    """Breadcrumb of whatever's actively being probed right now. The
    in-memory copy on db.config rides along on whatever save already
    happens next, and is also backed by a durable on-disk marker (see
    _write_probe_marker) so a hard kill mid-probe is reliably caught on
    the next boot."""
    if db is None:
        return
    db.config["_last_probe_started"] = {"path": norm_p, "field": field, "ts": time.time()}
    _write_probe_marker(norm_p, field)


def _note_probe_finished(norm_p, field):
    if db is None:
        return
    marker = db.config.get("_last_probe_started")
    if marker and marker.get("path") == norm_p and marker.get("field") == field:
        db.config.pop("_last_probe_started", None)
    _clear_probe_marker(norm_p, field)


def _claim_probe(norm_p, field):
    key = (norm_p, field)
    with _probe_dispatch_lock:
        if key in _probe_dispatch_inflight:
            return False
        _probe_dispatch_inflight.add(key)
        _note_probe_started(norm_p, field)
        return True


def _release_probe(norm_p, field):
    with _probe_dispatch_lock:
        _probe_dispatch_inflight.discard((norm_p, field))
        _note_probe_finished(norm_p, field)


def _probe_duration_guarded(norm_p):
    if not _claim_probe(norm_p, "duration"):
        return None
    try:
        return get_media_duration(norm_p)
    finally:
        _release_probe(norm_p, "duration")


def _probe_dims_guarded(norm_p):
    if not _claim_probe(norm_p, "dims"):
        return None
    try:
        return get_media_video_dimensions(norm_p)
    finally:
        _release_probe(norm_p, "dims")


SHOW_SMOOTH_TOLERANCE_DB = 0.3
_show_loudness_floor = {}
_show_loudness_floor_lock = threading.Lock()


def _get_show_smoothing_key(norm_path):
    if not norm_path:
        return None
    parent = os.path.basename(os.path.dirname(norm_path))
    info = _season_folder_base(parent)
    if info:
        return info[1]
    if _bare_season_number(parent) is not None:
        grandparent = os.path.basename(os.path.dirname(os.path.dirname(norm_path)))
        return _normalize_show_key(grandparent) if grandparent else None
    return None


def _apply_show_loudness_smoothing(norm_p, gain, shortfall_info):
    show_key = _get_show_smoothing_key(norm_p)
    if show_key is None or not shortfall_info:
        return gain
    achieved = shortfall_info.get("achieved_lufs")
    measured = shortfall_info.get("measured_lufs")
    peak_capped = shortfall_info.get("peak_capped")
    if achieved is None or measured is None:
        return gain
    with _show_loudness_floor_lock:
        floor = _show_loudness_floor.get(show_key)
        if peak_capped:
            if floor is None or achieved < floor:
                _show_loudness_floor[show_key] = achieved
            return gain
        if floor is not None and achieved > floor + SHOW_SMOOTH_TOLERANCE_DB:
            _smoothed_gain = min(gain, 10 ** ((floor - measured) / 20.0))
            print(f"[LOUDNESS PROBE] *** SHOW SMOOTHED *** {os.path.basename(norm_p)}: "
                  f"would land at {achieved:.1f} LUFS (uncapped) but a peak-limited sibling "
                  f"in this show already established a {floor:.1f} LUFS floor -- "
                  f"matched down to x{_smoothed_gain:.2f} so this episode doesn't stand out "
                  f"louder than its neighbors")
            return _smoothed_gain
    return gain


def _probe_loudness_guarded(norm_p, out_shortfall=None, **kwargs):
    """out_shortfall: optional dict the caller passes in to get back the
    raw measurement (measured_lufs, achieved_lufs, peak_capped, etc.) that
    produced the returned gain -- see get_media_loudness_gain's
    shortfall_out docs. Kept as a separate param (not folded into
    **kwargs/shortfall_out) so this function's own internal
    _shortfall_info -- used for show-smoothing regardless of whether the
    caller wants it back -- is never overwritten by a caller-supplied dict.
    """
    _group_key = _get_part_group_key(norm_p)
    if _group_key:
        _group_entry = _get_part_group_gain_cache_entry(_group_key)
        if _group_entry and os.path.normpath(_group_entry.get("anchor_path", "")) != norm_p:
            print(f"[LOUDNESS PROBE] '{os.path.basename(norm_p)}' is part of the same "
                  f"title as already-scanned '{os.path.basename(_group_entry.get('anchor_path', ''))}' "
                  f"-- reusing its gain x{_group_entry.get('gain', 1.0):.2f} instead of "
                  f"re-measuring this part independently.")
            if out_shortfall is not None:
                out_shortfall["measured_lufs"] = None  # reused, not freshly measured
            return _group_entry.get("gain", 1.0)

    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_media_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if _gain is not None:
            _gain = _apply_show_loudness_smoothing(norm_p, _gain, _shortfall_info)
        if _group_key and _gain is not None:
            _set_part_group_anchor_gain(_group_key, norm_p, _gain)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


def _probe_music_loudness_guarded(norm_p, out_shortfall=None, **kwargs):
    """Music counterpart to _probe_loudness_guarded, used only by
    _music_precache_worker(). Calls get_music_loudness_gain (MUSIC_TARGET_
    LUFS + the dedicated music semaphore) instead of get_media_loudness_
    gain, and skips the multi-part-episode grouping/show-smoothing logic
    above -- those exist for TV shows split across files, which standalone
    music tracks never are.

    out_shortfall: same passthrough as _probe_loudness_guarded's own
    out_shortfall -- see its docstring.
    """
    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_music_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


UNPLAYABLE_STRIKE_THRESHOLD = 3

def _register_unplayable_strike(norm_path, reason):
    if db is None or not norm_path:
        return 0
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    count = entry.get("unplayable_strikes", 0) + 1
    entry["unplayable_strikes"] = count
    entry["unplayable_reason"] = reason
    if count >= UNPLAYABLE_STRIKE_THRESHOLD:
        entry["confirmed_unplayable"] = True
    print(f"[PLAYABILITY PROBE] Strike {count}/{UNPLAYABLE_STRIKE_THRESHOLD} for "
          f"'{os.path.basename(norm_path)}' -- {reason}")
    return count


def _mark_confirmed_no_audio(norm_path, reason):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    entry["confirmed_no_audio"] = True
    entry["no_audio_reason"] = reason
    print(f"[PLAYABILITY PROBE] Confirmed no audible content in "
          f"'{os.path.basename(norm_path)}' -- {reason}")


def _seed_probe_cache_from_schedules():
    if db is None:
        return 0
    try:
        cache = db.config.setdefault("media_probe_cache", {})
    except Exception:
        return 0
    channels = getattr(db, "channels_db", None)
    if not isinstance(channels, dict):
        return 0
    seeded = 0
    for _ch_id, ch_info in list(channels.items()):
        if not isinstance(ch_info, dict):
            continue
        schedules = ch_info.get("schedules", {})
        if not isinstance(schedules, dict):
            continue
        for _block_name, entries in list(schedules.items()):
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                path = entry.get("path")
                if not path:
                    continue
                dur = entry.get("duration")
                gain = entry.get("gain")
                has_real_dur = isinstance(dur, (int, float)) and not isinstance(dur, bool) and dur > 0
                has_gain = isinstance(gain, (int, float)) and not isinstance(gain, bool)
                if not (has_real_dur or has_gain):
                    continue
                try:
                    norm = os.path.normpath(str(path))
                except Exception:
                    continue
                existing = cache.get(norm)
                if not isinstance(existing, dict):
                    existing = {}
                    cache[norm] = existing
                if has_real_dur and not existing.get("duration"):
                    existing["duration"] = int(dur)
                    seeded += 1
                if has_gain and existing.get("gain") is None:
                    existing["gain"] = gain
    return seeded


def _register_probe_batch(batch_id, ch_key, container_key, sub_key, remaining_paths):
    """Record a batch probe pass (e.g. newly-added files from the file
    explorer) so it can be picked back up if the app goes down mid-pass --
    otherwise those files just silently sit unprobed until something else
    happens to re-trigger them."""
    if db is None:
        return
    batches = db.config.setdefault("_active_probe_batches", {})
    batches[batch_id] = {
        "ch": ch_key,
        "container": container_key,
        "sub": sub_key,
        "remaining": list(remaining_paths),
        "ts": time.time(),
    }


def _update_probe_batch_progress(batch_id, remaining_paths):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None and batch_id in batches:
        batches[batch_id]["remaining"] = list(remaining_paths)
        batches[batch_id]["ts"] = time.time()


def _clear_probe_batch(batch_id):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None:
        batches.pop(batch_id, None)


def _report_interrupted_probe_marker():
    """Startup check: if the last run died mid-probe (crash, force-close,
    power loss, task-killed, etc.), find out which file+field was in
    flight and treat whatever's cached for it as untrustworthy -- even if
    a value already made it into the cache. A probe cut off mid-parse can
    still leave a stray/partial value behind (this is how a 22-minute
    episode ends up cached as 41 seconds), and there's no way to tell a
    good cached value from a bad one after the fact just by looking at it
    -- so we don't guess, we just clear that one field and let it get
    re-probed clean. Only the one path+field the marker points at is
    touched; everything else in the cache is left alone."""
    if db is None:
        return
    db.config.pop("_last_probe_started", None)

    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return

    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] could not read leftover probe marker "
                    f"(removing it): {e}")
        try:
            os.remove(marker_path)
        except Exception:
            pass
        return

    path = marker.get("path")
    field = marker.get("field")

    try:
        os.remove(marker_path)
    except Exception:
        pass

    if not path or not field:
        return

    norm_p = os.path.normpath(path)
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.get(norm_p)
    had_cached_value = bool(entry and field in entry)
    if entry and field in entry:
        entry.pop(field, None)

    log.warning(
        f"[MEDIA PRECACHE] Last run was interrupted mid-probe on "
        f"'{os.path.basename(path)}' ({field})" +
        (" -- had a cached value already, but clearing it since a probe "
         "that got cut off mid-parse can't be trusted; queuing a clean "
         "re-probe." if had_cached_value else
         " -- no cached value yet; queuing a probe.")
    )

    def _requeue():
        try:
            if field == "duration":
                _probe_duration_guarded(norm_p)
            elif field == "dims":
                _probe_dims_guarded(norm_p)
            elif field == "gain":
                if _is_drive_degraded(norm_p):
                    log.warning("[MEDIA PRECACHE] not re-probing gain for %s right now -- "
                                "its drive looks degraded (%s)",
                                os.path.basename(norm_p), _drive_latency_summary(norm_p))
                else:
                    _probe_loudness_guarded(norm_p)
        except Exception as e:
            log.warning(f"[MEDIA PRECACHE] re-probe of interrupted file "
                        f"'{os.path.basename(norm_p)}' ({field}) failed: {e}")

    threading.Thread(target=_requeue, daemon=True).start()


def _resume_interrupted_probe_batches():
    """Startup check: pick back up any batch probe passes (file-explorer
    additions) that were still in progress when the app last went down,
    instead of leaving those files unprobed until something else happens
    to touch them again."""
    if db is None:
        return
    batches = db.config.get("_active_probe_batches", {})
    if not batches:
        return
    for batch_id, info in list(batches.items()):
        remaining = info.get("remaining") or []
        if not remaining:
            _clear_probe_batch(batch_id)
            continue
        
        threading.Thread(
            target=_probe_and_patch_durations,
            args=(info.get("ch"), info.get("container"), info.get("sub"), remaining),
            kwargs={"_resume_batch_id": batch_id},
            daemon=True,
        ).start()


def _invalidate_gains_for_target_lufs_change():
    if db is None:
        return 0
    # Keyed on both TARGET_LUFS and LOUDNESS_CONVERGENCE_DB -- a change to
    # either one changes what gain a file should end up with, so either
    # one changing needs to invalidate every cached gain the same way.
    #
    # BUG FIX: this key used to be a tuple. It's saved to retro_config.json
    # and comes back as a LIST on the next launch, and in Python a list is
    # never == a tuple -- so every boot looked like a "target change" and
    # wiped every cached gain (media_probe_cache, schedule asset gains, pair
    # gains), forcing full re-scans and different volumes on every restart.
    # Store it as a list and compare element-wise so a JSON round trip (or
    # any int/float difference) can't fake a change.
    _gain_cache_key = [float(TARGET_LUFS), float(LOUDNESS_CONVERGENCE_DB)]
    _last_target = db.config.get("_gain_cache_target_lufs")
    db.config["_gain_cache_target_lufs"] = _gain_cache_key
    if _last_target is not None:
        try:
            _last_norm = [float(_v) for _v in _last_target]
        except (TypeError, ValueError):
            _last_norm = None  # legacy/garbled value -- treat as a real change once
        if (_last_norm is not None
                and len(_last_norm) == len(_gain_cache_key)
                and all(abs(_a - _b) < 1e-9 for _a, _b in zip(_last_norm, _gain_cache_key))):
            return 0
    _cleared = 0
    _cache = db.config.get("media_probe_cache", {})
    for _entry in _cache.values():
        if isinstance(_entry, dict) and "gain" in _entry:
            del _entry["gain"]
            _cleared += 1
    for _ch_info in db.channels_db.values():
        if not isinstance(_ch_info, dict):
            continue
        for _container_key in ("schedules", "holiday_schedules"):
            _pools = _ch_info.get(_container_key, {})
            if not isinstance(_pools, dict):
                continue
            for _pool in _pools.values():
                if not isinstance(_pool, list):
                    continue
                for _asset in _pool:
                    if not isinstance(_asset, dict):
                        continue
                    for _gkey in ("gain", "pair_ep1_gain", "pair_ep2_gain"):
                        if _gkey in _asset:
                            del _asset[_gkey]
                            _cleared += 1
    _group_cache = db.config.get("_part_group_gain_cache", {})
    if isinstance(_group_cache, dict) and _group_cache:
        _cleared += len(_group_cache)
        _group_cache.clear()
    return _cleared


def _invalidate_stale_fallback_gains():
    if db is None:
        return 0
    _cleared = 0
    _cache = db.config.get("media_probe_cache", {})
    for _entry in _cache.values():
        _g = _entry.get("gain")
        if isinstance(_g, (int, float)) and not isinstance(_g, bool) and _g == 1.0:
            del _entry["gain"]
            _cleared += 1
    for _ch_info in db.channels_db.values():
        if not isinstance(_ch_info, dict):
            continue
        for _container_key in ("schedules", "holiday_schedules"):
            _pools = _ch_info.get(_container_key, {})
            if not isinstance(_pools, dict):
                continue
            for _pool in _pools.values():
                if not isinstance(_pool, list):
                    continue
                for _asset in _pool:
                    if not isinstance(_asset, dict):
                        continue
                    for _gkey in ("gain", "pair_ep1_gain", "pair_ep2_gain"):
                        _g = _asset.get(_gkey)
                        if isinstance(_g, (int, float)) and not isinstance(_g, bool) and _g == 1.0:
                            del _asset[_gkey]
                            _cleared += 1
    return _cleared


def _reconcile_mismatched_pair_gains():
    if db is None:
        return 0
    channels = getattr(db, "channels_db", None)
    if not isinstance(channels, dict):
        return 0
    reset = 0
    probe_cache = db.config.get("media_probe_cache", {})
    for ch_info in channels.values():
        if not isinstance(ch_info, dict):
            continue
        for container_key in ("schedules", "holiday_schedules"):
            for pool in ch_info.get(container_key, {}).values():
                if not isinstance(pool, list):
                    continue
                for entry in pool:
                    if not isinstance(entry, dict) or not entry.get("is_pair"):
                        continue
                    g1 = entry.get("pair_ep1_gain")
                    g2 = entry.get("pair_ep2_gain")
                    if g1 is None or g2 is None:
                        continue  # not (yet) fully probed either way -- normal pass handles it
                    if abs(float(g1) - float(g2)) < 1e-6:
                        continue  # already consistent, including under the new combined logic
                    entry.pop("gain", None)
                    entry.pop("pair_ep1_gain", None)
                    entry.pop("pair_ep2_gain", None)
                    for _pk in ("pair_ep1_path", "pair_ep2_path"):
                        _p = entry.get(_pk)
                        if not _p:
                            continue
                        _np = os.path.normpath(_p)
                        if _np in probe_cache:
                            probe_cache[_np].pop("gain", None)
                    reset += 1
    return reset


def _clear_all_cached_loudness_gains():
    """Strip every cached gain value (media_probe_cache + per-episode
    pair/single gain fields in channel schedules/holiday_schedules) so
    affected files re-probe clean on next play, instead of staying stuck
    on a value computed under a ceiling/target that no longer applies.
    Shared by both the one-time LUFS-target migration and the Loudness
    Scan ceiling toggle, since both invalidate the same cached values
    for the same reason."""
    if db is None:
        return 0
    cleared = 0
    cache = db.config.get("media_probe_cache", {})
    for entry in cache.values():
        if not isinstance(entry, dict):
            continue
        if "gain" in entry:
            del entry["gain"]
            cleared += 1
    channels = getattr(db, "channels_db", None)
    if isinstance(channels, dict):
        for ch_info in channels.values():
            if not isinstance(ch_info, dict):
                continue
            for container_key in ("schedules", "holiday_schedules"):
                pools = ch_info.get(container_key, {})
                if not isinstance(pools, dict):
                    continue
                for pool in pools.values():
                    if not isinstance(pool, list):
                        continue
                    for asset in pool:
                        if not isinstance(asset, dict):
                            continue
                        for gkey in ("gain", "pair_ep1_gain", "pair_ep2_gain"):
                            if gkey in asset:
                                del asset[gkey]
                                cleared += 1
    return cleared


def _reset_all_loudness_gains_for_target_change():
    if db is None:
        return 0
    if db.config.get("_lufs23_migration_done"):
        return 0
    cleared = _clear_all_cached_loudness_gains()
    db.config["_lufs23_migration_done"] = True
    return cleared


_MUSIC_TARGET_MIGRATION_KEY = "_music_target_v2_migration_done"
_MUSIC_FILE_EXTS = (".mp3", ".flac", ".wav", ".ogg", ".oga", ".m4a", ".aac", ".wma", ".opus")


def _reset_music_gains_for_new_target():
    """One-time: clear cached MUSIC gains so they re-probe under the new
    MUSIC_TARGET_LUFS / MUSIC_GAIN_FLOOR (see media.py). Gains cached under
    the old -24 target would otherwise sit next to newly probed ones at a
    different reference level.

    Only audio files are touched -- video/TV gains are left exactly as they
    are. The bundled ch03 default music (its gain is a fixed, deliberately
    trusted constant, _CH03_DEFAULT_MUSIC_GAIN_PRECACHED) is skipped so the
    menu music level doesn't change.
    """
    if db is None or db.config.get(_MUSIC_TARGET_MIGRATION_KEY):
        return 0

    def _is_pinned_default(g):
        try:
            return abs(float(g) - _CH03_DEFAULT_MUSIC_GAIN_PRECACHED) < 1e-9
        except (TypeError, ValueError):
            return False

    cleared = 0
    cache = db.config.get("media_probe_cache", {})
    for _path, entry in cache.items():
        if (isinstance(entry, dict) and "gain" in entry
                and str(_path).lower().endswith(_MUSIC_FILE_EXTS)
                and not _is_pinned_default(entry["gain"])):
            del entry["gain"]
            cleared += 1
    channels = getattr(db, "channels_db", None)
    if isinstance(channels, dict):
        for ch_info in channels.values():
            if not isinstance(ch_info, dict):
                continue
            for container_key in ("schedules", "holiday_schedules"):
                pools = ch_info.get(container_key, {})
                if not isinstance(pools, dict):
                    continue
                for pool in pools.values():
                    if not isinstance(pool, list):
                        continue
                    for asset in pool:
                        if not isinstance(asset, dict):
                            continue
                        _ap = str(asset.get("path", asset.get("file", "")))
                        if (_ap.lower().endswith(_MUSIC_FILE_EXTS)
                                and "gain" in asset
                                and not _is_pinned_default(asset["gain"])):
                            del asset["gain"]
                            cleared += 1
    db.config[_MUSIC_TARGET_MIGRATION_KEY] = True
    return cleared


_RENORM_LOG_BASENAMES = ("app_log.txt", "app_log1.txt", "app_log2.txt", "app_log3.txt")

_RENORM_CLAMP_LINE_RE = re.compile(
    r"\*\*\* CLAMPED \((?P<side>BOOST|ATTENUATION), (?P<reason>[A-Z ]+) LIMIT\) \*\*\*\s*"
    r"(?:Pair\s+)?(?P<names>.+?):\s*needed.*?"
    r"\((?P<shortfall>[\d.]+)dB short of target\)"
)


def _gather_renorm_targets_from_app_logs(threshold_db=None):
    if threshold_db is None:
        threshold_db = RENORM_SHORTFALL_THRESHOLD_DB
    log_dir = globals().get("_app_log_dir") or os.path.dirname(os.path.abspath(sys.argv[0]))
    targets = {}
    for fname in _RENORM_LOG_BASENAMES:
        fpath = os.path.join(log_dir, fname)
        if not os.path.isfile(fpath):
            continue
        try:
            with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                for line in f:
                    if "*** CLAMPED (BOOST" not in line and "*** CLAMPED (ATTENUATION, TRUE PEAK" not in line:
                        continue
                    m = _RENORM_CLAMP_LINE_RE.search(line)
                    if not m:
                        continue
                    side = m.group("side")
                    reason = m.group("reason").strip()
                    if side == "ATTENUATION" and reason != "TRUE PEAK":
                        continue
                    try:
                        shortfall = float(m.group("shortfall"))
                    except (TypeError, ValueError):
                        continue
                    names_part = m.group("names")
                    names = [n.strip() for n in names_part.split(" + ")] if " + " in names_part else [names_part.strip()]
                    for name in names:
                        name = os.path.basename(name)
                        if not name:
                            continue
                        if shortfall > targets.get(name, {}).get("shortfall", -1.0):
                            targets[name] = {"shortfall": shortfall, "side": side, "reason": reason}
        except Exception as e:
            _log_warn_throttled("rtv_L5486", f"[RENORM SWEEP] couldn't read {fname} (non-fatal): {e}")
    return {
        name: info for name, info in targets.items()
        if info["shortfall"] > (
            RENORM_PEAK_SHORTFALL_THRESHOLD_DB if info.get("reason") == "TRUE PEAK"
            else threshold_db
        )
    }


def _resolve_renorm_target_paths(targets):
    if db is None or not targets:
        return []
    by_basename = {}
    for norm_p in db.config.get("media_probe_cache", {}).keys():
        by_basename.setdefault(os.path.basename(norm_p), []).append(norm_p)
    resolved = []
    seen = set()
    for name, info in targets.items():
        for norm_p in by_basename.get(name, []):
            if norm_p in seen:
                continue
            if not _cached_path_exists(norm_p):
                continue
            seen.add(norm_p)
            resolved.append((norm_p, info))
    return resolved


def _is_commercial_file_for_channel(ch_key, path):
    """True if `path` is one of ch_key's own configured commercial clips.

    Several places in this file snapshot whatever VLC actually has loaded
    right now (to correct for drift against the scheduler's own bookkeeping)
    and need to label that file as "Video" or "Commercial". Those reads only
    know the raw path on disk, so they check it against this channel's own
    configured commercial clips instead of hardcoding "Video" or guessing
    from a bare "commercial" substring in the path, either of which would
    mislabel a real commercial the moment its folder isn't literally named
    that. A wrong "Video" label here is what would let a commercial's raw
    filename leak into the guide as if it were an episode, and let its slot
    get spliced open as a bogus extra guide entry instead of staying merged
    into the show it interrupts.
    """
    if db is None or not path:
        return False
    try:
        norm_path = os.path.normpath(os.path.abspath(str(path))).lower()
    except Exception:
        return False
    ch_info = db.channels_db.get(str(ch_key).zfill(2), {})
    for _casset in ch_info.get("schedules", {}).get("Commercials", []):
        _cp = _casset.get("path", _casset.get("file", "")) if isinstance(_casset, dict) else str(_casset)
        if not _cp:
            continue
        try:
            if os.path.normpath(os.path.abspath(_cp)).lower() == norm_path:
                return True
        except Exception:
            continue
    return False


def _gather_all_commercial_paths():
    if db is None:
        return []
    seen = set()
    paths = []
    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True):
            continue
        if ch_info.get("server_locked", False):
            continue
        if not ch_info.get("commercials_enabled", False):
            continue
        for _casset in ch_info.get("schedules", {}).get("Commercials", []):
            _cp = _casset.get("path", _casset.get("file", "")) if isinstance(_casset, dict) else str(_casset)
            if not _cp:
                continue
            norm_p = os.path.normpath(os.path.abspath(_cp))
            if norm_p in seen:
                continue
            if not _cached_path_exists(norm_p):
                continue
            seen.add(norm_p)
            paths.append(norm_p)
    return paths


def _pick_next_renorm_target(pending_map):
    if not pending_map:
        return None
    if db is None or 'app_state' not in globals():
        return max(pending_map, key=lambda p: pending_map[p]["shortfall"])

    watched = str(app_state.get("current_channel", "")).zfill(2)
    ch_info = db.channels_db.get(watched, {}) if watched else {}

    # Tier 0: now playing on the watched channel.
    if watched:
        try:
            now_state = _get_probe_now_state(watched)
            cur_file = now_state.get("file", "") if isinstance(now_state, dict) else ""
            if cur_file:
                norm_cur = os.path.normpath(os.path.abspath(cur_file))
                if norm_cur in pending_map:
                    return norm_cur
        except Exception:
            pass

    # Tier 1: commercials scheduled for the watched channel's breaks.
    if ch_info.get("commercials_enabled", False):
        for _casset in ch_info.get("schedules", {}).get("Commercials", []):
            _cp = _casset.get("path", _casset.get("file", "")) if isinstance(_casset, dict) else str(_casset)
            if not _cp:
                continue
            norm_p = os.path.normpath(os.path.abspath(_cp))
            if norm_p in pending_map:
                return norm_p

    # Tier 2: next up in the watched channel's lineup.
    try:
        ordered, _block_key = _get_channel_ordered_content(watched, ch_info)
        if ordered:
            now_state = _get_probe_now_state(watched)
            cur_file = now_state.get("file", "") if isinstance(now_state, dict) else ""
            upcoming = _next_n_from_ordered(ordered, cur_file, n=4)
            for entry in upcoming:
                for p in _paths_from_entry(entry):
                    if not p:
                        continue
                    norm_p = os.path.normpath(os.path.abspath(p))
                    if norm_p in pending_map:
                        return norm_p
    except Exception:
        pass

    # Tier 3: fallback -- worst logged/assumed shortfall in the remaining set.
    return max(pending_map, key=lambda p: pending_map[p]["shortfall"])


def _invalidate_gain_cache_for_path(norm_p):
    if db is None or not norm_p:
        return
    cache = db.config.get("media_probe_cache", {})
    entry = cache.get(norm_p)
    if isinstance(entry, dict):
        entry.pop("gain", None)
        entry.pop("loudness_timeout_streak", None)
        entry.pop("loudness_next_retry_ts", None)
    _group_key = _get_part_group_key(norm_p)
    if _group_key:
        _group_cache = db.config.get("_part_group_gain_cache", {})
        _group_entry = _group_cache.get(_group_key)
        if _group_entry and os.path.normpath(_group_entry.get("anchor_path", "")) == norm_p:
            del _group_cache[_group_key]
    dvd_cache = db.config.get("dvd_gain_cache", {})
    if norm_p in dvd_cache:
        del dvd_cache[norm_p]
    for pl_entry in db.config.get("ch03_menu_music", []):
        if isinstance(pl_entry, dict) and os.path.normpath(pl_entry.get("path", "")) == norm_p:
            pl_entry.pop("gain", None)
    channels = getattr(db, "channels_db", None)
    if not isinstance(channels, dict):
        return
    for ch_info in channels.values():
        if not isinstance(ch_info, dict):
            continue
        for container_key in ("schedules", "holiday_schedules"):
            pools = ch_info.get(container_key, {})
            if not isinstance(pools, dict):
                continue
            for pool in pools.values():
                if not isinstance(pool, list):
                    continue
                for asset in pool:
                    if not isinstance(asset, dict):
                        continue
                    _ap = os.path.normpath(asset.get("path", asset.get("file", "")))
                    if _ap == norm_p:
                        asset.pop("gain", None)
                        continue
                    if asset.get("is_pair"):
                        _p1 = os.path.normpath(asset.get("pair_ep1_path", ""))
                        _p2 = os.path.normpath(asset.get("pair_ep2_path", ""))
                        if norm_p == _p1:
                            asset.pop("pair_ep1_gain", None)
                            asset.pop("gain", None)
                        elif norm_p == _p2:
                            asset.pop("pair_ep2_gain", None)
                            asset.pop("gain", None)


def _is_renorm_ledger_entry_current(entry):
    if not isinstance(entry, dict):
        return False
    if entry.get("status") == "failed":
        return True
    return entry.get("target_lufs") == TARGET_LUFS


def _run_two_pass_renormalization_sweep():
    if db is None:
        return
    try:
        targets = _gather_renorm_targets_from_app_logs()
    except Exception as e:
        log.warning(f"[RENORM SWEEP] failed to parse app logs for targets (non-fatal): {e}")
        targets = {}
    try:
        resolved = _resolve_renorm_target_paths(targets) if targets else []
    except Exception as e:
        log.warning(f"[RENORM SWEEP] failed to resolve target paths (non-fatal): {e}")
        resolved = []
    try:
        commercial_paths = _gather_all_commercial_paths()
    except Exception as e:
        log.warning(f"[RENORM SWEEP] failed to gather commercial pool (non-fatal): {e}")
        commercial_paths = []
    _already = {p for p, _ in resolved}
    for norm_p in commercial_paths:
        if norm_p not in _already:
            resolved.append((norm_p, {"shortfall": 0.0, "side": "BOOST"}))
            _already.add(norm_p)
    if not resolved:
        return
    ledger = db.config.setdefault("_renorm_sweep_processed", {})
    pending_map = {p: info for p, info in resolved
                   if not _is_renorm_ledger_entry_current(ledger.get(p))}
    if not pending_map:
        return
    total_pending = len(pending_map)
    print(f"[RENORM SWEEP] {total_pending} file(s) queued for one-time two-pass "
          f"re-encode (of {len(resolved)} total candidate(s) -- clamp-shortfall "
          f"matches + full commercial pool, {len(ledger)} already processed in "
          f"a prior run). Priority: now-playing -> current break's commercials "
          f"-> next-up -> everything else, re-evaluated live as you watch.")
    fixed = still_short = failed = 0
    while pending_map:
        _live_ledger = db.config.get("_renorm_sweep_processed", {})
        if _live_ledger:
            pending_map = {p: info for p, info in pending_map.items()
                           if not _is_renorm_ledger_entry_current(_live_ledger.get(p))}
            if not pending_map:
                break
        norm_p = _pick_next_renorm_target(pending_map)
        if norm_p is None:
            break
        # Same playback backoff the regular loudness probe pass already
        # uses: pause here (don't skip) while a video is actively playing,
        # a game is actually being played, or a heavy-effects menu is
        # open, so this sweep's ffmpeg work never competes with any of
        # those for CPU/disk. FIX: this used to only check is_playing_video
        # -- a full two-pass ffmpeg re-encode would happily run flat-out
        # while a game was live on ch03, which is exactly the kind of
        # background work _background_scan_should_pause() exists to catch
        # (it never got wired in here). Re-checked every 2s so it resumes
        # promptly once the blocker clears. This only covers the gap
        # *before* a file starts; should_abort (below) covers the blocker
        # showing up mid-file.
        while (app_state.get("is_playing_video", False)
               or _background_scan_should_pause()
               or _menu_open_with_heavy_effects()):
            if _app_shutting_down.wait(2.0):
                return
        info = pending_map.pop(norm_p)
        # Passed into every ffmpeg pass renormalize_file_two_pass runs --
        # polled every ~0.4s so a file already mid-encode gets terminated
        # within a fraction of a second of playback starting, instead of
        # running to completion regardless (that's what was causing the
        # frame-gap stalls). Nothing has been written to the real file yet
        # at any point an abort can land, so this is always safe to retry.
        # Same fix as the pre-file gate above: a game starting mid-encode
        # now aborts it just as promptly as video starting does.
        _should_abort = lambda: (app_state.get("is_playing_video", False)
                                  or _is_game_actively_playing()
                                  or _menu_open_with_heavy_effects())
        shortfall = info["shortfall"]
        side = info.get("side", "BOOST")
        reason = info.get("reason", "")
        _peak_only = (side == "ATTENUATION") or (side == "BOOST" and reason == "TRUE PEAK")
        if _peak_only:
            _dur = None
            use_dynamic = True
            _lra1 = LOUDNORM_RENORM_LRA
            _lra2 = LOUDNORM_RENORM_LRA_AGGRESSIVE
        else:
            _dur = _probe_duration_seconds_fast(norm_p)
            use_dynamic = _dur is not None and _dur <= RENORM_DYNAMIC_MAX_DURATION_SECONDS
            _lra1 = RENORM_DYNAMIC_LRA if use_dynamic else LOUDNORM_RENORM_LRA
            _lra2 = RENORM_DYNAMIC_LRA_AGGRESSIVE if use_dynamic else LOUDNORM_RENORM_LRA_AGGRESSIVE

        try:
            result = renormalize_file_two_pass(norm_p, lra=_lra1, dynamic=use_dynamic,
                                                should_abort=_should_abort)
            if result.get("status") == "still_short":
                result = renormalize_file_two_pass(norm_p, lra=_lra2, dynamic=use_dynamic,
                                                    should_abort=_should_abort)
            if result.get("status") == "interrupted":
                # Playback started mid-encode -- nothing was written, so
                # just put it back at the front of the queue rather than
                # treating it as processed. The `while is_playing_video`
                # check at the top of the loop will hold here until
                # playback ends, then this same file gets picked up again.
                pending_map[norm_p] = info
                continue
            status = result.get("status", "failed")
            ledger = db.config.setdefault("_renorm_sweep_processed", {})
            ledger[norm_p] = {
                "status": status,
                "pre_lufs": result.get("pre_lufs"),
                "post_lufs": result.get("post_lufs"),
                "shortfall_db": result.get("shortfall_db"),
                "error": result.get("error"),
                "logged_shortfall_db": shortfall,
                "side": side,
                "peak_only_mode": _peak_only,
                "dynamic_mode": use_dynamic,
                "target_lufs": TARGET_LUFS,
                "ts": time.time(),
            }
            if status in ("fixed", "still_short"):
                _invalidate_gain_cache_for_path(norm_p)
                if status == "fixed":
                    fixed += 1
                else:
                    still_short += 1
            else:
                failed += 1
        except Exception as e:
            ledger = db.config.setdefault("_renorm_sweep_processed", {})
            ledger[norm_p] = {"status": "failed", "error": str(e), "ts": time.time()}
            failed += 1
            _log_warn_throttled("rtv_L5756", f"[RENORM SWEEP] {os.path.basename(norm_p)}: unexpected error -- {e}")
        try:
            db.save_settings_async()
        except Exception:
            pass
    log.warning(f"[RENORM SWEEP] Done -- {fixed} fixed, {still_short} improved but still "
          f"short (physical true-peak ceiling reached even at the aggressive LRA), "
          f"{failed} failed/skipped. Fixed/improved files will pick up a fresh, "
          f"accurate gain on their next normal loudness probe.")
    try:
        db.save_settings_async(force=True)
    except Exception:
        pass


def _fe_remove_selected_from_queue():
    items      = app_state.get("file_explorer_items", [])
    sel        = app_state.get("file_explorer_selection", set())
    checked    = app_state.get("file_explorer_checked", [])
    valid_exts = app_state.get("file_explorer_exts", set())
    context    = app_state.get("file_explorer_context", {})
    locked_path = _fe_locked_playing_path(context)
    to_remove  = set()
    dirs_to_expand = []
    _blocked_live = False
    for idx in sorted(sel):
        if not (0 <= idx < len(items)):
            continue
        item = items[idx]
        p    = item["path"]
        if item["type"] == "dir":
            dirs_to_expand.append(p)
        elif item["type"] == "file":
            np_ = os.path.normpath(p)
            if locked_path and np_ == locked_path:
                # Can't pull the file that's actively playing live right now
                # out of its own schedule -- leave it checked/scheduled.
                _blocked_live = True
                continue
            to_remove.add(np_)
    if _blocked_live:
        print(f"[FILE EXPLORER] Skipped removing {os.path.basename(locked_path)} -- "
              f"it's currently playing live on this channel.")
    app_state["file_explorer_checked"]  = [f for f in checked if f not in to_remove]
    app_state["file_explorer_selection"] = set()
    if dirs_to_expand:
        app_state["file_explorer_expand_request_id"] += 1
        req_id = app_state["file_explorer_expand_request_id"]
        session_id = app_state.get("file_explorer_session_id", 0)
        if app_state.get("file_explorer_expand_pending", 0) == 0:
            app_state["file_explorer_expand_started_ms"] = pygame.time.get_ticks()
        app_state["file_explorer_expand_pending"] += 1
        threading.Thread(
            target=_fe_expand_worker,
            args=(req_id, "remove", dirs_to_expand, valid_exts, session_id),
            daemon=True,
        ).start()


def _fe_managed_delete_dir(context):
    """The one folder, if any, where "Remove Selected" is allowed to mean
    "delete from disk" for this context -- the console's own cores folder
    for "Select Libretro Core", or its system/BIOS folder for "Add BIOS".
    Anywhere else (the user browsing around to go find a file to bring in)
    "Remove Selected" only ever deselects, never deletes."""
    mode = context.get("mode", "")
    if mode == "libretro_core":
        return context.get("emu_folder", "")
    if mode == "add_bios":
        return context.get("bios_dir", "")
    return ""


def _fe_in_managed_delete_dir(context):
    managed_dir = _fe_managed_delete_dir(context)
    cwd = app_state.get("file_explorer_cwd")
    return bool(managed_dir) and bool(cwd) and os.path.normpath(cwd) == os.path.normpath(managed_dir)


def _fe_delete_selected_files():
    """"Remove Selected" in a managed-folder browser (see
    _fe_managed_delete_dir -- currently "Select Libretro Core" and "Add
    BIOS") can't just uncheck like it does everywhere else in the file
    explorer -- what's listed there isn't a schedule/queue entry, it's an
    actual file sitting on disk. The only thing "remove" can sensibly mean
    here is deleting the file. Only called while browsing that managed
    folder itself (see _fe_in_managed_delete_dir) -- selecting files
    elsewhere and hitting Remove Selected always just deselects instead.
    Anything deleted is also dropped from the checked list so it can't
    still end up picked as active once the explorer closes, and the
    listing is refreshed so it disappears immediately instead of
    lingering until the next navigate."""
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    checked = app_state.get("file_explorer_checked", [])
    deleted = set()
    for idx in sorted(sel):
        if not (0 <= idx < len(items)):
            continue
        item = items[idx]
        if item["type"] != "file":
            continue  # don't delete/recurse into subfolders from here
        p = item["path"]
        try:
            os.remove(p)
            deleted.add(os.path.normpath(p))
            
        except Exception as e:
            _log_warn_throttled("rtv_L5864", f"[FILE EXPLORER] Could not delete {p}: {e}")
    if deleted:
        app_state["file_explorer_checked"] = [f for f in checked if os.path.normpath(f) not in deleted]
    _fe_navigate(app_state.get("file_explorer_cwd"))


def _is_usa_bios_filename(fname):
    """Whether a BIOS dump's filename indicates a USA/NTSC-U region dump.

    Real BIOS dumps almost never spell the region out -- they use Sony's
    model-number convention instead (SCPHxxxx, PSone SCPH10x): the last
    digit of the number is the region -- 0 = Japan, 1 = USA, 2 = Europe
    (SCPH1000/1001/1002, SCPH5500/5501/5502, SCPH9000/9001/9002, etc.).
    SCPH7003 is a known real exception (still a USA dump despite the "3").
    Still also matches an explicit "usa"/"ntsc-u" in the name in case a
    file was manually renamed to say so."""
    lower = fname.lower()
    if "usa" in lower or "ntsc-u" in lower or "(u)" in lower:
        return True
    base = re.sub(r"[^a-z0-9]", "", os.path.splitext(lower)[0])
    if base == "scph7003":
        return True
    m = re.fullmatch(r"scph(\d{3,4})", base)
    return bool(m and m.group(1).endswith("1"))


# Best-to-worst order across every region at once, per the person's own
# ranking (screenshotted best-overall / excellent-alternative / good-backup
# picks for each of North America, Europe/Oceania, and Japan). USA entries
# come first as a block, then PAL, then Japan, so picking the lowest index
# present in a folder automatically gives "prefer USA, else PAL, else
# Japan" while still respecting the tier within whichever region is used.
_BIOS_KNOWN_PRIORITY = [
    "scph5501",  # USA -- best overall
    "scph7001",  # USA -- excellent alternative
    "scph1001",  # USA -- good backup
    "scph5502",  # PAL -- best overall
    "scph7002",  # PAL -- excellent alternative
    "scph1002",  # PAL -- good backup
    "scph5500",  # Japan -- best overall
    "scph7000",  # Japan -- excellent alternative
    "scph1000",  # Japan -- good backup
]


def _bios_region_rank(fname):
    """0=USA, 1=PAL/Europe, 2=Japan, 3=unrecognized -- fallback ranking for
    a BIOS file that isn't one of the 9 known dumps in _BIOS_KNOWN_PRIORITY
    (a renamed file or an uncommon dump), so even an unlisted file still
    sorts by the same USA > PAL > Japan country preference, using the same
    model-number convention _is_usa_bios_filename relies on."""
    lower = fname.lower()
    if "usa" in lower or "ntsc-u" in lower or "(u)" in lower:
        return 0
    if "pal" in lower or "europe" in lower or "(e)" in lower:
        return 1
    if "japan" in lower or "ntsc-j" in lower or "(j)" in lower:
        return 2
    base = re.sub(r"[^a-z0-9]", "", os.path.splitext(lower)[0])
    if base == "scph7003":
        return 0  # known real USA exception despite the "3"
    m = re.fullmatch(r"scph(\d{3,4})", base)
    if m:
        last_digit = m.group(1)[-1]
        if last_digit == "1":
            return 0
        if last_digit == "2":
            return 1
        if last_digit == "0":
            return 2
    return 3


def _bios_priority_key(fname):
    """Sort key for auto-picking the best BIOS file available in a folder
    -- lower sorts first / wins. One of the 9 known real dumps sorts by
    its exact best-to-worst rank; anything else falls back to region-only
    sorting (still USA > PAL > Japan) and then alphabetically within that
    region, so a mix of known and unknown files still resolves sensibly."""
    base = re.sub(r"[^a-z0-9]", "", os.path.splitext(fname.lower())[0])
    if base in _BIOS_KNOWN_PRIORITY:
        return (0, _BIOS_KNOWN_PRIORITY.index(base), base)
    return (1, _bios_region_rank(fname), base)


def _fe_resolve_active_core_name(console_key, emu_folder):
    """Which core .dll in this console's folder is actually live right now.

    Mirrors build_core_for_console()'s own selection order exactly, so what
    gets highlighted in the "Select Libretro Core" browser always matches
    what will actually load next launch: the saved emulator_config.json
    pick if that file is still sitting in the folder, otherwise whichever
    file this project's own core metadata (PREFERRED_CORE_ORDER via
    resolve_preferred_core_filename in game_deck.py -- not anything read
    from RetroArch itself) would pick instead."""
    import json as _json
    from game_deck import resolve_emulator_config_path
    try:
        cfg_path = resolve_emulator_config_path()
        with open(cfg_path, "r", encoding="utf-8") as fp:
            cfg = _json.load(fp)
    except Exception:
        cfg = {}
    saved = cfg.get(console_key)
    try:
        dll_files = [f for f in os.listdir(emu_folder) if f.lower().endswith(".dll")]
    except Exception:
        dll_files = []
    if saved:
        for fname in dll_files:
            if fname.lower() == saved.lower():
                return fname
    from game_deck import resolve_preferred_core_filename
    return resolve_preferred_core_filename(console_key, dll_files)


def _fe_resolve_active_bios_name(console_key, bios_dir):
    """Which BIOS file in this console's system folder is actually the
    active one right now. Mirrors the "Add BIOS" commit logic's own pick
    order exactly, so what's highlighted always matches what's actually
    active: the saved active_bios pick if that file is still sitting in
    the folder, otherwise whichever file ranks best by _bios_priority_key
    (USA > PAL > Japan, tiered within each region -- see
    _BIOS_KNOWN_PRIORITY)."""
    saved = db.config.get("active_bios", {}).get(console_key, "") if db is not None else ""
    try:
        files = sorted(f for f in os.listdir(bios_dir) if os.path.isfile(os.path.join(bios_dir, f)))
    except Exception:
        files = []
    if saved:
        for fname in files:
            if fname.lower() == saved.lower():
                return fname
    return min(files, key=_bios_priority_key) if files else None


def _drop_media_from_pool(ch_key, sub_key, norm_p, reason, container_key=None):
    containers = [container_key] if container_key else ["schedules", "holiday_schedules"]
    for _ck in containers:
        entries = db.channels_db.get(ch_key, {}).get(_ck, {}).get(sub_key, [])
        if not entries:
            continue
        kept = [e for e in entries
                if not (isinstance(e, dict)
                        and os.path.normpath(e.get("path", e.get("file", ""))) == norm_p)]
        if len(kept) == len(entries):
            continue
        db.channels_db[ch_key][_ck][sub_key] = kept
        
        return True
    return False


def _drop_pair_from_pool(ch_key, sub_key, norm_p1, norm_p2, reason, container_key=None):
    """Same removal as _drop_media_from_pool, but for a two-file paired
    entry (is_pair=True, pair_ep1_path/pair_ep2_path) instead of a plain
    single-path entry -- a paired entry has no "path"/"file" key for the
    normal matcher above to find, so it needs its own match on both
    pair paths together."""
    containers = [container_key] if container_key else ["schedules", "holiday_schedules"]
    for _ck in containers:
        entries = db.channels_db.get(ch_key, {}).get(_ck, {}).get(sub_key, [])
        if not entries:
            continue
        kept = [e for e in entries
                if not (isinstance(e, dict) and e.get("is_pair")
                        and os.path.normpath(e.get("pair_ep1_path", "")) == norm_p1
                        and os.path.normpath(e.get("pair_ep2_path", "")) == norm_p2)]
        if len(kept) == len(entries):
            continue
        db.channels_db[ch_key][_ck][sub_key] = kept
        return True
    return False


def _probe_and_patch_durations(ch_key, container_key, sub_key, items_pool, _resume_batch_id=None):
    import time as _time
    if _channel_is_server_streamed(ch_key):
        return  # Server-supplied durations/gains; no local probing or pool pruning
    initialize_vlc_on_demand()
    pygame.time.wait(300)
    save_counter = 0
    pool_size = len(items_pool)
    batch_size = 5 if pool_size < 50 else 25
    # Single source of truth lives in media.py (COMMERCIAL_MAX_SECONDS),
    # since it also defines the ceiling of the top commercial duration
    # bundle build_block_timeline schedules against.
    COMMERCIAL_MAX_SECONDS = media.COMMERCIAL_MAX_SECONDS
    _is_commercial_block = (container_key == "schedules" and sub_key == "Commercials")
    _removed_long_commercials = 0
    _removed_silent_commercials = 0
    _removed_unplayable = 0
    # Track this pass so it can be resumed if the app goes down mid-way
    # through (crash, force-close, watchdog relaunch). _resume_batch_id is
    # set when we're continuing a pass from a previous run; otherwise this
    # is a fresh pass and gets its own id.
    batch_id = _resume_batch_id or f"{ch_key}:{container_key}:{sub_key}:{_time.time()}"
    _register_probe_batch(batch_id, ch_key, container_key, sub_key, items_pool)
    try:
        for i, item_path in enumerate(items_pool):
            norm_p = os.path.normpath(item_path)
            _cached = _get_cached_media_probe(norm_p)
            if _cached and _media_probe_fingerprint_stale(norm_p, _cached):
                # The file at this path has changed size/mtime since we
                # last measured it (re-encoded, replaced, trimmed, etc.) --
                # its cached duration/gain/dims are for a file that no
                # longer exists at this path in that form. Don't trust
                # them; wipe and treat this pass exactly like an unprobed
                # file so it gets measured fresh (fix #7).
                log.info(
                    "[DURATION PROVENANCE] %s changed on disk since it was last "
                    "measured -- discarding stale probe cache entry and "
                    "re-probing", os.path.basename(norm_p),
                )
                cache = db.config.get("media_probe_cache", {})
                cache.pop(norm_p, None)
                _cached = {}
            probed = _cached.get("duration")
            probed_gain = _cached.get("gain")
            if probed is None:
                try:
                    probed = _probe_duration_guarded(norm_p)
                except Exception:
                    probed = None
            if probed_gain is None:
                try:
                    if _is_drive_degraded(norm_p):
                        raise LoudnessProbeTimeoutError(norm_p)
                    probed_gain = _probe_loudness_guarded(
                        norm_p, raise_on_no_audio=True,
                        treat_fallback_as_unknown=True,
                        raise_on_unplayable=True)
                except NoAudioStreamError as _naerr:
                    _drop_media_from_pool(ch_key, sub_key, norm_p,
                                           getattr(_naerr, "reason", "no audio track"),
                                           container_key=container_key)
                    _removed_silent_commercials += 1
                    _store_cached_media_probe(norm_p, duration=probed)
                    _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                    continue
                except UnplayableMediaError as _uerr:
                    _strikes = _register_unplayable_strike(norm_p, _uerr.reason)
                    _store_cached_media_probe(norm_p, duration=probed)
                    if _strikes >= UNPLAYABLE_STRIKE_THRESHOLD:
                        _drop_media_from_pool(ch_key, sub_key, norm_p,
                                               f"confirmed unplayable ({_uerr.reason}, "
                                               f"{_strikes} strikes)",
                                               container_key=container_key)
                        _removed_unplayable += 1
                    _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                    continue
                except Exception:
                    probed_gain = None
            if _is_commercial_block and probed and probed > COMMERCIAL_MAX_SECONDS:
                if _drop_media_from_pool(ch_key, sub_key, norm_p,
                                          f"{int(probed)}s > {COMMERCIAL_MAX_SECONDS}s, too long to be a commercial",
                                          container_key=container_key):
                    _removed_long_commercials += 1
                _store_cached_media_probe(norm_p, duration=probed, gain=probed_gain)
                _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                continue
            if (not probed or probed <= 0) and not probed_gain:
                _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                continue
            _patch_probed_gain("channel", ch_key, sub_key, norm_p,
                                gain=probed_gain, duration=probed)
            save_counter += 1
            # Checkpoint remaining work alongside the same periodic save this
            # loop already does -- no extra I/O, just makes that save also
            # durable proof of exactly how far this pass got.
            _update_probe_batch_progress(batch_id, items_pool[i + 1:])
            if save_counter % batch_size == 0:
                try: db.save_settings_async()
                except Exception as e: log.warning("Periodic settings save failed during duration probe for %s/%s: %s", container_key, sub_key, e)
            if i < 2:
                _time.sleep(0.05)
            elif i < 15:
                _time.sleep(0.2)
            else:
                _time.sleep(0.8 if pool_size > 100 else 0.4)
    finally:
        # Whether we finished the pool, hit an unhandled exception, or the
        # loop broke out early, the pass is over -- clear the resumable
        # record so a clean/expected end doesn't look like an interrupted
        # one on the next startup. A hard kill (crash, force-close) skips
        # this entirely, which is exactly what leaves the record behind for
        # _resume_interrupted_probe_batches() to pick up next run.
        _clear_probe_batch(batch_id)
    try: db.save_settings_async(force=True)
    except Exception as e: log.warning("Final settings save failed after duration probe for %s/%s: %s", container_key, sub_key, e)
    _drop_summary = ""
    if _removed_long_commercials or _removed_silent_commercials or _removed_unplayable:
        _drop_summary = (f" (dropped {_removed_long_commercials} too-long, "
                          f"{_removed_silent_commercials} no-audio, "
                          f"{_removed_unplayable} unplayable)")
    print(f"[DURATION PROBE] {container_key}/{sub_key} for ch {ch_key} -> probed {save_counter}/{pool_size} file(s){_drop_summary}")


def _dedupe_incoming_files(existing_entries, incoming_paths):
    seen_names = {os.path.basename(e.get("path", "")) for e in existing_entries if isinstance(e, dict)}
    out = []
    for p in incoming_paths:
        name = os.path.basename(p)
        if name in seen_names:
            continue
        seen_names.add(name)
        out.append(p)
    return out


def _fe_delete_old_managed_asset(old_path, managed_folder, new_path):
    """A single-file asset (menu background, console/DVD splash, libretro core)
    was just replaced -- delete the file it's replacing so it doesn't sit
    around as an orphan forever.

    Safety: only ever deletes a file that lives directly inside the folder
    we manage copies in (managed_folder). If the stored old path points
    somewhere else -- e.g. an older build stored a raw source path instead
    of a copied-in one -- this is a no-op rather than risking deleting a
    file the user never asked us to touch. Also a no-op if there's nothing
    to clean up, or the "old" and "new" paths are the same file.
    """
    if not old_path or not managed_folder:
        return
    try:
        old_abs = os.path.abspath(old_path)
        new_abs = os.path.abspath(new_path) if new_path else ""
        if old_abs == new_abs:
            return
        if os.path.dirname(old_abs) != os.path.abspath(managed_folder):
            return
        if os.path.isfile(old_abs):
            os.remove(old_abs)
            print(f"[FILE EXPLORER] Removed previous asset: {os.path.basename(old_abs)}")
    except Exception as e:
        log.warning(f"[FILE EXPLORER] Could not remove previous asset {old_path}: {e}")


def _fe_close(commit):
    """Close the explorer, committing queued files to their destination if commit=True."""
    if commit:
        checked = app_state.get("file_explorer_checked", [])
        context = app_state.get("file_explorer_context", {})
        mode    = context.get("mode", "schedule")
        ch_key  = context.get("ch", "")
        block   = context.get("block", "")
        hkey    = context.get("hkey", "")
        if mode == "rom_folder_relocate":
            ck = context.get("console_key", "")
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if ck and picked and os.path.isdir(picked):
                if game_deck is not None:
                    game_deck.console_rom_dir[ck] = picked
                db.config.setdefault("console_rom_dir", {})[ck] = picked
                db.save_settings_async()
                print(f"[GAMES] {ck} ROM folder relocated to: {picked}")
                if game_deck is not None:
                    game_deck.refresh_from_config(db.config)
        elif mode in ("schedule", "commercial", "holiday"):
            # "checked" was pre-populated with what's already scheduled, so an
            # empty list here means "remove everything" and must go through.
            _locked_path = _fe_locked_playing_path(context)
            _final_checked = list(checked)
            if _locked_path and _locked_path not in _final_checked:
                # Never let a commit remove the file that's live right now.
                _final_checked.append(_locked_path)
                print(f"[FILE EXPLORER] Currently-playing file can't be removed "
                      f"while it's live -- keeping it scheduled: "
                      f"{os.path.basename(_locked_path)}")
            if mode == "schedule":
                # Freeze (ch, block) at commit time so a fast channel switch
                # before the queue drains can't misfile these onto whatever
                # channel is selected later. "files" is the full desired
                # final list; the drain reconciles rather than appends.
                explorer_queue.put({"ch": ch_key, "block": block, "files": _final_checked})
            elif mode == "commercial" and ch_key and block:
                ch_data  = db.channels_db.setdefault(ch_key, {})
                existing = ch_data.setdefault("schedules", {}).get(block, [])
                entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, _final_checked)
                ch_data["schedules"][block] = entries
                db.save_settings_async()
                print(f"[FILE EXPLORER] {block} -> {len(entries)} file(s) for ch {ch_key} "
                      f"(+{len(new_paths)} new, -{removed_n} removed"
                      + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
                if new_paths:
                    threading.Thread(
                        target=_probe_and_patch_durations,
                        args=(ch_key, "schedules", block, list(new_paths)),
                        daemon=True
                    ).start()
                if str(app_state.get("current_channel", "")).zfill(2) == str(ch_key).zfill(2):
                    # A full re-tune (change_channel) here would make the
                    # edited commercial list "instant", but that stops and
                    # restarts VLC, which looks and sounds exactly like a
                    # real channel change even though nothing the viewer is
                    # currently watching actually needs to change.
                    # Invalidating the cached schedule (same pattern the
                    # commercials_enabled toggle already uses, just above)
                    # is enough: whatever's playing right now keeps playing
                    # undisturbed, and the new list takes effect at the next
                    # scheduling decision -- the next commercial break --
                    # instead of needing an abrupt cut the moment this dialog
                    # closes.
                    _plog = ch_data.setdefault("playback_log", {})
                    _plog["sched_block_key"] = ""
                    _plog["sched_cached_tracks"] = []
                    _plog["sched_cached_durations"] = {}
            elif mode == "holiday" and ch_key and hkey:
                ch_data  = db.channels_db.setdefault(ch_key, {})
                existing = ch_data.setdefault("holiday_schedules", {}).get(hkey, [])
                entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, _final_checked)
                ch_data["holiday_schedules"][hkey] = entries
                # ASYNC WRITE: same reasoning as the "commercial" branch above.
                db.save_settings_async()
                print(f"[FILE EXPLORER] Holiday {hkey} -> {len(entries)} file(s) for ch {ch_key} "
                      f"(+{len(new_paths)} new, -{removed_n} removed"
                      + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
                if new_paths:
                    threading.Thread(
                        target=_probe_and_patch_durations,
                        args=(ch_key, "holiday_schedules", hkey, list(new_paths)),
                        daemon=True
                    ).start()
                # Same reasoning as the "commercial" branch above: invalidate
                # the cached schedule instead of forcing a full re-tune, so
                # whatever's currently playing keeps playing undisturbed and
                # the edited holiday list takes effect at the next scheduling
                # decision instead of an abrupt stop/restart right now.
                if str(app_state.get("current_channel", "")).zfill(2) == str(ch_key).zfill(2):
                    _plog = ch_data.setdefault("playback_log", {})
                    _plog["sched_block_key"] = ""
                    _plog["sched_cached_tracks"] = []
                    _plog["sched_cached_durations"] = {}
        elif mode == "scan_for_roms":
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if not picked:
                pass
            elif not _is_drive_responsive(picked):
                # Don't even attempt os.path.isdir()/the walk -- the picked
                # folder's own drive isn't responding right now (disconnected/
                # asleep external drive, stalled network share). Nothing to
                # show in the UI for this -- the file explorer already told
                # the person which folder they picked, same as add_roms --
                # just log it so it's traceable if someone asks why nothing
                # showed up.
                print("[GAMES] Scan For Roms: drive not responding — try again once it's connected")
                app_state["_games_menu_flash_msg"] = "SCAN FOR ROMS: DRIVE NOT RESPONDING"
                app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
            elif os.path.isdir(picked) and game_deck is not None and hasattr(game_deck, "bulk_scan_for_roms"):
                # game_deck.bulk_scan_for_roms() now peeks inside every
                # .zip/.7z it finds to confirm the content actually matches
                # the console (see _archive_matches_console in game_deck.py)
                # instead of trusting the folder-name match alone -- that's
                # what stops something like an arcade "CPS1" folder full of
                # zips from being swept into PSX just because both accept
                # .zip. Opening every archive's listing takes real time on a
                # big collection, so this runs in the
                # background and keeps the picker open (with the same
                # "FINISHING FOLDER SCAN..." busy overlay _fe_poll_expand
                # already uses when DONE is waiting on an in-flight
                # ADD/REMOVE folder walk) until it reports back. See
                # _fe_bulkscan_worker / _fe_poll_bulkscan.
                app_state["file_explorer_bulkscan_pending"]    = True
                app_state["file_explorer_bulkscan_started_ms"] = pygame.time.get_ticks()
                with app_state["file_explorer_bulkscan_lock"]:
                    app_state["file_explorer_bulkscan_result"]   = None
                    app_state["file_explorer_bulkscan_progress"] = (0, 0)
                threading.Thread(
                    target=_fe_bulkscan_worker,
                    args=(picked,),
                    daemon=True,
                ).start()
                return   # _fe_poll_bulkscan() finishes the close once the background scan reports back
        elif mode == "scan_for_cores":
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if not picked:
                pass
            elif not _is_drive_responsive(picked):
                # Same reasoning as scan_for_roms above -- don't attempt the
                # walk against a drive that isn't currently responding.
                print("[GAMES] Scan For Cores: drive not responding — try again once it's connected")
                app_state["_games_menu_flash_msg"] = "SCAN FOR CORES: DRIVE NOT RESPONDING"
                app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
            elif os.path.isdir(picked) and game_deck is not None and hasattr(game_deck, "bulk_scan_for_cores"):
                results, unresponsive_roots = game_deck.bulk_scan_for_cores(picked)
                if hasattr(game_deck, "reload_emulator_config"):
                    game_deck.reload_emulator_config()
                total_new = sum(n for n, _p in results.values())
                if results:
                    per_console = ", ".join(
                        f"{ck}: +{n}" + (f" ({p} already there)" if p else "")
                        for ck, (n, p) in sorted(results.items())
                    )
                    summary = (f"Scan For Cores: added {total_new} core(s) across "
                               f"{len(results)} console(s) ({per_console})")
                else:
                    summary = "Scan For Cores: no matching cores found"
                    app_state["_games_menu_flash_msg"] = "SCAN FOR CORES: NOTHING FOUND"
                    app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
                if unresponsive_roots:
                    summary += ("; skipped unreadable drive(s): "
                                + ", ".join(r.rstrip("\\") for r in unresponsive_roots))
                print(f"[GAMES] {summary}")
        elif mode == "add_roms":
            # "checked" is the full desired final list of manually-added
            # roms for this console (pre-populated with what's already
            # there), so an empty list here means "remove everything for
            # this console" -- same reconcile semantics as the schedule
            # buckets, not an append-only add.
            ck = context.get("console_key", "")
            if ck and game_deck is not None:
                existing = list(game_deck.console_roms_manual.get(ck, []))
                existing_norm = {os.path.normpath(p) for p in existing if p}
                checked_norm = []
                seen = set()
                for p in checked:
                    np_ = os.path.normpath(p)
                    if np_ not in seen:
                        seen.add(np_)
                        checked_norm.append(np_)
                brand_new = [np_ for np_ in checked_norm if np_ not in existing_norm]
                n_new, n_dupe = (0, 0)
                if brand_new and hasattr(game_deck, "add_manual_roms"):
                    n_new, n_dupe = game_deck.add_manual_roms(ck, brand_new)
                # add_manual_roms only ever appends -- now drop anything the
                # user unchecked so this is a true replace, not an accumulate.
                final_list = [
                    p for p in game_deck.console_roms_manual.get(ck, [])
                    if os.path.normpath(p) in checked_norm
                ]
                removed_n = len(existing_norm - set(checked_norm))
                game_deck.console_roms_manual[ck] = final_list
                db.config.setdefault("console_roms_manual", {})[ck] = list(final_list)
                db.save_settings_async()
                _dupe_note = f", {n_dupe} duplicate(s) skipped" if n_dupe else ""
                print(f"[GAMES] {ck}: {len(final_list)} manually-added rom(s) total "
                      f"(+{n_new} new, -{removed_n} removed{_dupe_note})")
        elif mode == "ch03_menu_music":
            # "checked" is the full desired final playlist (pre-populated with
            # what was already there), so an empty list here means "remove
            # everything" and must go through -- same reconcile semantics as
            # schedule/commercial/holiday, not an append.
            existing = db.config.get("ch03_menu_music", [])
            entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, checked)
            db.config["ch03_menu_music"] = entries
            db.save_settings_async()
            print(f"[GAMES] Menu music -> {len(entries)} track(s) total "
                  f"(+{len(new_paths)} new, -{removed_n} removed"
                  + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
            if (app_state.get("current_channel") == "03"
                    and game_deck is not None
                    and getattr(game_deck, "mode", "BROWSE") == "BROWSE"
                    and not getattr(game_deck, "dvd_playback_active", False)):
                if not entries:
                    _stop_ch03_menu_music()
                else:
                    _start_ch03_menu_music()
        elif checked:
            if mode == "libretro_core":                # Single-file pick — take only the first checked file
                ck      = context.get("console_key", "")
                folder  = context.get("emu_folder", "")
                chosen  = checked[0] if checked else ""
                if chosen and ck:
                    import json as _json, shutil as _shutil
                    dest = os.path.join(folder, os.path.basename(chosen))
                    try:
                        if os.path.abspath(chosen) != os.path.abspath(dest):
                            _shutil.copy2(chosen, dest)
                            print(f"[GAMES] Copied core into {folder}")
                    except Exception as _ce:
                        log.warning(f"[GAMES] Could not copy core: {_ce}")
                        dest = chosen
                    from game_deck import resolve_emulator_config_path
                    cfg_path = resolve_emulator_config_path()
                    try:
                        with open(cfg_path, "r", encoding="utf-8") as fp:
                            cfg = _json.load(fp)
                    except Exception:
                        cfg = {}
                    cfg[ck] = os.path.basename(dest)
                    with open(cfg_path, "w", encoding="utf-8") as fp:
                        _json.dump(cfg, fp, indent=2)
                    print(f"[GAMES] Libretro core for {ck} set to: {os.path.basename(dest)}")
                    # Keep the source core so multiple cores can coexist and
                    # switching selections remains possible.
                    if game_deck is not None and hasattr(game_deck, "reload_emulator_config"):
                        game_deck.reload_emulator_config()
            elif mode == "add_bios":                      # Multi-file pick — copy every checked file in, then decide which one is active
                ck       = context.get("console_key", "")
                bios_dir = context.get("bios_dir", "")
                if bios_dir and ck and checked:
                    import shutil as _shutil
                    os.makedirs(bios_dir, exist_ok=True)
                    copied, failed = 0, 0
                    for src in checked:
                        dest = os.path.join(bios_dir, os.path.basename(src))
                        try:
                            if os.path.abspath(src) != os.path.abspath(dest):
                                _shutil.copy2(src, dest)
                            copied += 1
                        except Exception as _be:
                            failed += 1
                            _log_warn_throttled("rtv_L6402", f"[GAMES] Could not copy BIOS file {src}: {_be}")
                    log.warning(f"[GAMES] Add Bios: copied {copied} file(s) into {bios_dir} for {ck}"
                          + (f" ({failed} failed)" if failed else ""))
                    # Whatever got checked this trip becomes the active BIOS --
                    # whether that's a brand-new file just copied in, or an
                    # existing file the user picked from the system folder
                    # itself to switch to. If more than one got checked at
                    # once (bulk-adding several region dumps in one go), the
                    # best-ranked one wins by the same USA > PAL > Japan
                    # priority as the auto-pick fallback (_bios_priority_key),
                    # so "add a batch, keep using the best one" just works.
                    _names = [os.path.basename(p) for p in checked]
                    _active_pick = min(_names, key=_bios_priority_key)
                    db.config.setdefault("active_bios", {})[ck] = _active_pick
                    db.save_settings_async()
                    print(f"[GAMES] Active BIOS for {ck} set to: {_active_pick}")
                    if game_deck is not None:
                        game_deck.refresh_from_config(db.config)
            elif mode == "console_splash":                  # Single-file pick — take only the first checked file
                folder = context.get("splash_folder", "")
                ck     = context.get("console_key", "DVD")
                chosen = checked[0] if checked else ""
                if chosen:
                    import shutil as _shutil
                    dest = chosen
                    if folder:
                        dest = os.path.join(folder, os.path.basename(chosen))
                        try:
                            if os.path.abspath(chosen) != os.path.abspath(dest):
                                _shutil.copy2(chosen, dest)
                                print(f"[GAMES] Copied splash screen into {folder}")
                        except Exception as _se:
                            log.warning(f"[GAMES] Could not copy splash screen: {_se}")
                            dest = chosen
                    if ck == "DVD":
                        _old_splash = db.config.get("dvd_splash_path", "")
                        db.config["dvd_splash_path"] = dest
                    else:
                        _old_splash = db.config.get("console_splash_path", {}).get(ck, "")
                        db.config.setdefault("console_splash_path", {})[ck] = dest
                    db.save_settings_async()
                    print(f"[GAMES] {ck} splash screen set to: {os.path.basename(dest)}")
                    if folder:
                        _fe_delete_old_managed_asset(_old_splash, folder, dest)
                    if game_deck is not None:
                        game_deck.refresh_from_config(db.config)
            elif mode == "menu_bg":                          # Single-file pick — take only the first checked file
                chosen = checked[0] if checked else ""
                if chosen:
                    import shutil as _shutil
                    dest = os.path.join(MENU_BG_BASE_DIR, os.path.basename(chosen))
                    _old_bg = db.config.get("menu_bg_path", "")
                    try:
                        if os.path.abspath(chosen) != os.path.abspath(dest):
                            _shutil.copy2(chosen, dest)
                            print(f"[GAMES] Copied menu background into {MENU_BG_BASE_DIR}")
                    except Exception as _me:
                        log.warning(f"[GAMES] Could not copy menu background: {_me}")
                        dest = chosen
                    db.config["menu_bg_path"] = dest
                    db.save_settings_async()
                    print(f"[GAMES] Menu background set to: {os.path.basename(dest)}")
                    _fe_delete_old_managed_asset(_old_bg, MENU_BG_BASE_DIR, dest)
                    if game_deck is not None:
                        game_deck.refresh_from_config(db.config)
            elif mode == "watermark_select":               # Single-file pick — take only the first checked file
                chosen = checked[0] if checked else ""
                if chosen:
                    import shutil as _shutil
                    os.makedirs(WATERMARK_BASE_DIR, exist_ok=True)
                    dest = os.path.join(WATERMARK_BASE_DIR, os.path.basename(chosen))
                    _old_wm = db.config.get("watermark_path", "")
                    try:
                        if os.path.abspath(chosen) != os.path.abspath(dest):
                            _shutil.copy2(chosen, dest)
                            print(f"[WATERMARK] Copied watermark image into {WATERMARK_BASE_DIR}")
                    except Exception as _we:
                        log.warning(f"[WATERMARK] Could not copy watermark image: {_we}")
                        dest = chosen
                    db.config["watermark_path"] = dest
                    db.save_settings_async()
                    print(f"[WATERMARK] Watermark image set to: {os.path.basename(dest)}")
                    # NOTE: unlike menu background / splash / core, watermark
                    # images are meant to be kept as a switchable library --
                    # do NOT delete _old_wm here. _fe_delete_old_managed_asset
                    # is for true single-slot assets only; calling it for
                    # watermarks would destroy the previous one every time
                    # the watermark is switched.
                    # Force the next draw to reload/rescale from the new
                    # source instead of reusing whatever was cached under
                    # the old path.
                    _watermark_cache["path"] = None
                    _watermark_cache["raw"] = None
                    _watermark_cache["surface"] = None

    _fe_finish_close()


def _fe_finish_close():
    """The tail end of _fe_close(): remember the last folder browsed and
    actually hide the picker. Split out so a mode that has to finish its
    commit work in the background (scan_for_roms -- see _fe_poll_bulkscan)
    can keep the picker open with its busy overlay until that work reports
    back, instead of closing immediately like every other mode does."""
    _ck  = _fe_context_key(app_state.get("file_explorer_context", {}))
    _cwd = app_state.get("file_explorer_cwd")
    if _ck and _cwd and db is not None:
        db.config.setdefault("fe_last_cwd", {})[_ck] = _cwd
        db.save_settings_async()

    app_state["file_explorer_active"]  = False
    app_state["file_explorer_checked"] = []
    app_state["file_explorer_done_requested"] = False
    app_state["file_explorer_items"]   = []
    pygame.mouse.set_visible(False)  # Always hide mouse on close
    if app_state.get("show_menu", False):
        app_state["last_input_time"] = pygame.time.get_ticks()


def _fe_bulkscan_worker(picked_folder):
    """Background thread body for the deferred scan_for_roms commit (see
    _fe_close). Runs game_deck.bulk_scan_for_roms() -- which now opens
    every candidate .zip/.7z to verify its contents, so this can take a
    while on a big collection -- off the main thread, and hands the result
    back for _fe_poll_bulkscan() to apply. Progress is written to
    app_state as it goes so _fe_draw_busy_overlay can show a real % / ETA
    instead of an indeterminate spinner while this runs."""
    def _report_progress(done, total):
        with app_state["file_explorer_bulkscan_lock"]:
            app_state["file_explorer_bulkscan_progress"] = (done, total)

    try:
        results, unresponsive_roots = game_deck.bulk_scan_for_roms(
            picked_folder, progress_cb=_report_progress
        )
    except Exception as e:
        log.warning("bulk_scan_for_roms failed for %r: %s", picked_folder, e)
        results, unresponsive_roots = {}, []
    with app_state["file_explorer_bulkscan_lock"]:
        app_state["file_explorer_bulkscan_result"] = (results, unresponsive_roots)


def _fe_poll_bulkscan():
    """Polled every frame while the file explorer is open (same as
    _fe_poll_scan/_fe_poll_expand). Once the background Scan For Roms walk
    (see _fe_bulkscan_worker) reports back, applies its results, then
    actually closes the picker via _fe_finish_close(). A timeout backstop
    mirrors the other file-explorer
    background ops so a walk stuck on a drive that goes bad mid-scan can't
    strand the picker open forever."""
    if not app_state.get("file_explorer_bulkscan_pending", False):
        return

    with app_state["file_explorer_bulkscan_lock"]:
        result = app_state["file_explorer_bulkscan_result"]
        if result is not None:
            app_state["file_explorer_bulkscan_result"] = None

    if result is None:
        started_ms = app_state.get("file_explorer_bulkscan_started_ms", 0)
        timeout_ms = app_state.get("file_explorer_bulkscan_timeout_ms", 120000)
        if started_ms and (pygame.time.get_ticks() - started_ms) > timeout_ms:
            log.warning("[GAMES] Scan For Roms: background scan timed out -- closing picker anyway")
            app_state["file_explorer_bulkscan_pending"] = False
            _fe_finish_close()
        return

    app_state["file_explorer_bulkscan_pending"] = False
    results, unresponsive_roots = result

    if results:
        db.config.setdefault("console_roms_manual", {})
        for ck in results:
            db.config["console_roms_manual"][ck] = list(
                game_deck.console_roms_manual.get(ck, [])
            )
        db.save_settings_async()
    # Logged only -- no post-scan popup/toast in the UI. The file explorer
    # already communicated the pick ("Folder selected — click DONE to
    # scan") the same way add_roms communicates its queue while you're
    # still in there; once you're back out, the results just show up in
    # each console's rom list like any other add.
    total_added = sum(n for n, _s in results.values())
    if results:
        per_console = ", ".join(
            f"{ck}: +{n}" + (f" ({s} dup)" if s else "")
            for ck, (n, s) in sorted(results.items())
        )
        summary = (f"Scan For Roms: added {total_added} rom(s) across "
                   f"{len(results)} console(s) ({per_console})")
    else:
        summary = "Scan For Roms: no matching console folders/roms found"
        app_state["_games_menu_flash_msg"] = "SCAN FOR ROMS: NOTHING FOUND"
        app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
    if unresponsive_roots:
        summary += ("; skipped unreadable drive(s): "
                    + ", ".join(r.rstrip("\\") for r in unresponsive_roots))
    print(f"[GAMES] {summary}")

    _fe_finish_close()


def _fe_get_btn_rects(fx, fy, fw, fh):
    footer_y = fy + fh - _FE_FOOTER_H
    btn_y    = footer_y + _FE_FOOTER_H - _FE_BTN_H - 12
    widths   = [_FE_BTN_W_SM, _FE_BTN_W, _FE_BTN_W, _FE_BTN_W_SM]
    keys     = ["cancel", "remove_sel", "add_sel", "done"]
    total_w  = sum(widths)
    gap      = (fw - total_w) // (len(widths) + 1)
    x        = fx + gap
    rects    = []
    for w, key in zip(widths, keys):
        rects.append((pygame.Rect(x, btn_y, w, _FE_BTN_H), key))
        x += w + gap
    return rects


def _fe_scrollbar_thumb_rect(sb_x, items_y, items_h, n_items, visible, scroll):
    if n_items > visible:
        th = max(20, items_h * visible // max(1, n_items))
        ty = items_y + (items_h - th) * scroll // max(1, n_items - visible)
    else:
        th = items_h
        ty = items_y
    return pygame.Rect(sb_x, ty, 8, th)


def _fe_scroll_from_thumb_y(thumb_y, sb_x, items_y, items_h, n_items, visible):
    max_sc = max(0, n_items - visible)
    if max_sc <= 0:
        return 0
    th = max(20, items_h * visible // max(1, n_items))
    track_travel = max(1, items_h - th)
    frac = (thumb_y - items_y) / float(track_travel)
    return max(0, min(max_sc, round(frac * max_sc)))


def _fe_handle_event(event):
    """Route a pygame event to the file explorer (mouse-driven, Windows-style)."""
    if event.type in (pygame.KEYDOWN, pygame.MOUSEBUTTONDOWN, pygame.MOUSEWHEEL):
        app_state["last_input_time"] = pygame.time.get_ticks()

    # While a bulk "Scan For Roms" commit is still running in the
    # background, the picker is locked open on purpose (see
    # _fe_poll_bulkscan) -- roms aren't listed until the scan finishes, so
    # nothing here is safe to touch or exit out of yet. Swallow input
    # entirely until it reports back.
    if app_state.get("file_explorer_bulkscan_pending", False):
        return

    # ESC cancels -- but if DONE was already clicked and is only waiting on
    # a still-running background folder walk/scan to land (see the "done"
    # button handler's own file_explorer_expand_pending/scan_pending guard
    # a few hundred lines down), the user has already committed to saving.
    # Cancelling out from under that here would silently discard a commit
    # the user explicitly asked for -- which is exactly what made pressing
    # ESC/Back right after DONE (while a big folder of commercials was
    # still being walked) look like DONE had just... done nothing. Once
    # file_explorer_done_requested is set, let the deferred commit finish
    # exactly as promised -- the poll loops (_fe_poll_expand/_fe_poll_scan)
    # will call _fe_close(True) for us the instant the walk lands, same as
    # if DONE is clicked again for real. ESC before DONE has ever been
    # clicked keeps its original cancel-immediately behavior.
    if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
        if app_state.get("file_explorer_done_requested", False):
            return
        _fe_close(False)
        return
    if event.type == pygame.KEYDOWN and event.key == pygame.K_BACKSPACE:
        _fe_go_up()
        return

    fe_rect = app_state.get("file_explorer_rect")
    if not fe_rect:
        return
    fx, fy, fw, fh = fe_rect

    content_y  = fy + _FE_HEADER_H
    content_h  = fh - _FE_HEADER_H - _FE_FOOTER_H
    right_x    = fx + _FE_LEFT_W + 1
    right_w    = fw - _FE_LEFT_W - 1 - _FE_ADDLOC_PANEL_W - 1
    rp_x       = right_x + right_w + 1                          # Add Location panel x
    rp_w       = _FE_ADDLOC_PANEL_W
    items_y    = content_y + _FE_COL_H
    items_h    = content_h - _FE_COL_H
    footer_y   = fy + fh - _FE_FOOTER_H
    tb_y       = fy + _FE_TITLE_H

    left_rect   = pygame.Rect(fx, content_y, _FE_LEFT_W, content_h)
    items_rect  = pygame.Rect(right_x, items_y, right_w - 12, items_h)
    footer_rect = pygame.Rect(fx, footer_y, fw, _FE_FOOTER_H)
    up_rect     = pygame.Rect(fx + 6, tb_y + (_FE_TOOLBAR_H - 30) // 2, 60, 30)
    addloc_rect = _fe_get_addloc_rect(rp_x, rp_w, content_y, content_h)
    rows_top    = _fe_get_saved_rows_top(content_y)
    rp_rows_rect = pygame.Rect(rp_x, rows_top, rp_w, (content_y + content_h) - rows_top)

    items  = app_state.get("file_explorer_items", [])
    scroll = app_state.get("file_explorer_scroll", 0)
    sel    = app_state.get("file_explorer_selection", set())

    def idx_at(my):
        if my < items_rect.y or my >= items_rect.bottom:
            return -1
        # my is virtual-canvas space (see _real_to_virtual_pos below) -- with
        # Bezel on it's a float from the inverse scale/offset, and floor
        # division of a float still yields a float, not an int. Cast so the
        # result is always a clean int index for list subscripting.
        return int(scroll + (my - items_rect.y) // _FE_ROW_H)

    if event.type == pygame.MOUSEBUTTONDOWN:
        # Hit-rects above (up_rect, addloc_rect, items_rect, etc.) are all
        # in virtual-canvas coordinates -- event.pos is real, post-Bezel-
        # composite screen coordinates, which only match 1:1 when Bezel is
        # off. With Bezel on the picture is shrunk/offset into the Bezel
        # art's cutout, so clicks must be converted back first or every
        # button's clickable spot silently stays where it used to be.
        mx, my = _real_to_virtual_pos(event.pos)
        btn = event.button
        app_state["last_input_time"] = pygame.time.get_ticks()

        if btn == 4:
            app_state["file_explorer_scroll"] = max(0, scroll - 3)
            return
        if btn == 5:
            n = len(items)
            visible_rows = max(1, (app_state.get("file_explorer_rect", (0,0,0,500))[3] - _FE_HEADER_H - _FE_FOOTER_H - _FE_COL_H) // _FE_ROW_H)
            app_state["file_explorer_scroll"] = max(0, min(max(0, n - visible_rows), scroll + 3))
            return
        if btn != 1:
            return

        if up_rect.collidepoint(mx, my):
            _fe_go_up()
            return

        # [+ Add Location] right-side panel button
        if addloc_rect.collidepoint(mx, my):
            _fe_add_saved_location()
            return

        if rp_rows_rect.collidepoint(mx, my):
            saved_locs = _fe_get_saved_locations()
            # Bezel scaling can make virtual mouse coordinates floats.  Cast
            # before using the row as a list index.
            idx = int((my - rows_top) // _FE_LEFT_ROW_H)
            if 0 <= idx < len(saved_locs):
                p = saved_locs[idx]
                # "-" remove zone on the right edge of the row
                if mx >= rp_x + rp_w - _FE_LEFT_REMOVE_W:
                    _fe_remove_saved_location(p)
                else:
                    _fe_navigate(p)
            return

        if left_rect.collidepoint(mx, my):
            rows1, rows2 = _fe_left_layout(content_h)
            pc_items     = _fe_get_this_pc_items()
            qa_items     = _fe_get_quick_access_items()
            sec1_items_y = content_y + _FE_LEFT_ROW_H
            sec1_items_h = rows1 * _FE_LEFT_ROW_H
            sec2_hdr_y   = sec1_items_y + sec1_items_h
            sec2_items_y = sec2_hdr_y + _FE_LEFT_ROW_H
            sec2_items_h = rows2 * _FE_LEFT_ROW_H

            if sec1_items_y <= my < sec1_items_y + sec1_items_h:
                max_sc = max(0, len(pc_items) - rows1)
                sc     = max(0, min(max_sc, app_state.get("file_explorer_left_scroll_pc", 0)))
                # Bezel scaling can make virtual mouse coordinates floats.
                idx    = sc + int((my - sec1_items_y) // _FE_LEFT_ROW_H)
                if 0 <= idx < len(pc_items):
                    app_state["file_explorer_left_sel"] = pc_items[idx]["path"]
                    _fe_navigate(pc_items[idx]["path"])
                return
            if sec2_items_y <= my < sec2_items_y + sec2_items_h:
                max_sc = max(0, len(qa_items) - rows2)
                sc     = max(0, min(max_sc, app_state.get("file_explorer_left_scroll_qa", 0)))
                # Bezel scaling can make virtual mouse coordinates floats.
                idx    = sc + int((my - sec2_items_y) // _FE_LEFT_ROW_H)
                if 0 <= idx < len(qa_items):
                    app_state["file_explorer_left_sel"] = qa_items[idx]["path"]
                    _fe_navigate(qa_items[idx]["path"])
                return

        if footer_rect.collidepoint(mx, my):
            for rect, key in _fe_get_btn_rects(fx, fy, fw, fh):
                if rect.collidepoint(mx, my):
                    if key == "cancel":
                        _fe_close(False)
                    elif key == "remove_sel":
                        _ctx = app_state.get("file_explorer_context", {})
                        if _ctx.get("mode") in ("rom_folder_relocate", "scan_for_roms", "scan_for_cores"):
                            _ctx.pop("picked_rom_folder", None)
                            _ctx.pop("picked_rom_count", None)
                            app_state["file_explorer_checked"] = []
                        elif _fe_in_managed_delete_dir(_ctx):
                            _fe_delete_selected_files()
                        else:
                            _fe_remove_selected_from_queue()
                    elif key == "add_sel":
                        _ctx = app_state.get("file_explorer_context", {})
                        if _ctx.get("mode") == "rom_folder_relocate":
                            _fe_add_selected_rom_folder()
                        elif _ctx.get("mode") == "scan_for_roms":
                            _fe_add_selected_scan_folder()
                        elif _ctx.get("mode") == "scan_for_cores":
                            _fe_add_selected_scan_cores_folder()
                        else:
                            _fe_add_selected_to_queue()
                    elif key == "done":
                        if (app_state.get("file_explorer_expand_pending", 0) <= 0
                                and not app_state.get("file_explorer_scan_pending", False)):
                            _fe_close(True)
                        else:
                            # Either a folder ADD/REMOVE SELECTED is still
                            # walking disk on a background thread, or the
                            # current folder's own listing (kicked off by
                            # _fe_navigate on entry) hasn't landed yet -- e.g.
                            # a splash-video folder scan competing for I/O
                            # with a DVD actively playing off the same drive.
                            # Closing now would commit a partial/stale
                            # "checked" list, so defer: remember Done was
                            # requested and let the poll loop below finish
                            # the close once whichever is pending lands.
                            app_state["file_explorer_done_requested"] = True
                    return

        _SB_PAD  = 4
        sb_x     = right_x + right_w - 10
        sb_track = pygame.Rect(sb_x - _SB_PAD, items_y, 8 + _SB_PAD * 2, items_h)
        if sb_track.collidepoint(mx, my):
            _n_items = len(items)
            _visible = max(1, items_h // _FE_ROW_H)
            _thumb   = _fe_scrollbar_thumb_rect(sb_x, items_y, items_h, _n_items, _visible, scroll)
            if _thumb.collidepoint(mx, my):
                _grab_offset = my - _thumb.y
            else:
                _grab_offset = _thumb.h // 2
                _new_ty = max(items_y, min(items_y + items_h - _thumb.h, my - _grab_offset))
                app_state["file_explorer_scroll"] = _fe_scroll_from_thumb_y(
                    _new_ty, sb_x, items_y, items_h, _n_items, _visible)
            app_state["file_explorer_sb_drag"] = _grab_offset
            return

        if items_rect.collidepoint(mx, my):
            idx  = idx_at(my)
            mods = pygame.key.get_mods()
            if 0 <= idx < len(items):
                if mods & pygame.KMOD_SHIFT:
                    anchor = app_state.get("file_explorer_sel_anchor", 0)
                    lo, hi = min(anchor, idx), max(anchor, idx)
                    app_state["file_explorer_selection"] = set(range(lo, hi + 1))
                elif mods & pygame.KMOD_CTRL:
                    new_sel = set(sel)
                    if idx in new_sel:
                        new_sel.discard(idx)
                    else:
                        new_sel.add(idx)
                    app_state["file_explorer_selection"] = new_sel
                    app_state["file_explorer_sel_anchor"] = idx
                else:
                    app_state["file_explorer_selection"]  = {idx}
                    app_state["file_explorer_sel_anchor"] = idx

                # Double-click detection
                now = pygame.time.get_ticks()
                lct = app_state.get("file_explorer_last_click_ms", 0)
                lci = app_state.get("file_explorer_last_click_idx", -1)
                if lci == idx and (now - lct) < 500:
                    item = items[idx]
                    if item["type"] == "dir":
                        _fe_navigate(item["path"])
                        return
                app_state["file_explorer_last_click_ms"]  = now
                app_state["file_explorer_last_click_idx"] = idx
            else:
                if not (mods & (pygame.KMOD_SHIFT | pygame.KMOD_CTRL)):
                    app_state["file_explorer_selection"] = set()

            # Begin drag
            app_state["file_explorer_drag_start"] = (mx, my)
            app_state["file_explorer_drag_cur"]   = (mx, my)

    elif event.type == pygame.MOUSEMOTION:
        _sb_grab = app_state.get("file_explorer_sb_drag")
        if event.buttons[0] and _sb_grab is not None:
            _mx, _my = _real_to_virtual_pos(event.pos)
            _n_items = len(items)
            _visible = max(1, items_h // _FE_ROW_H)
            _thumb_h = _fe_scrollbar_thumb_rect(
                right_x + right_w - 10, items_y, items_h, _n_items, _visible, scroll).h
            _new_ty = max(items_y, min(items_y + items_h - _thumb_h, _my - _sb_grab))
            app_state["file_explorer_scroll"] = _fe_scroll_from_thumb_y(
                _new_ty, right_x + right_w - 10, items_y, items_h, _n_items, _visible)
            return
        if event.buttons[0] and app_state.get("file_explorer_drag_start"):
            mx, my = _real_to_virtual_pos(event.pos)
            app_state["file_explorer_drag_cur"] = (mx, my)
            sx, sy = app_state["file_explorer_drag_start"]
            if abs(mx - sx) > 4 or abs(my - sy) > 4:
                _ZONE  = 50   # px PAST the edge over which auto-scroll ramps from slow to full speed
                _now_t = pygame.time.get_ticks()
                _last_t = app_state.get("_fe_drag_scroll_t", 0)
                _n     = len(items)
                _vis   = max(1, items_h // _FE_ROW_H)
                _max_sc = max(0, _n - _vis)
                _cur_sc = app_state.get("file_explorer_scroll", 0)
                _delta  = 0
                _speed  = 120

                # Auto-scroll only kicks in once the cursor has actually left
                # the item list (above items_rect.y / below items_rect.bottom)
                # -- never while it's still merely near an edge but inside the
                # visible rows. Triggering on inside-proximity would fire on
                # drags that start on (or briefly pass over) one of the
                # first/last couple of rows -- extremely common, since that's
                # naturally where you click to start an upward or downward
                # multi-select after already scrolling -- and would
                # auto-scroll toward that end on every following tick while
                # the cursor just sat there, sweeping the selection far past
                # what was actually dragged over.
                if my < items_rect.y:
                    _past = items_rect.y - my
                    _speed = max(60, 120 - int(60 * min(_past, _ZONE) / _ZONE))
                    _delta = -1
                elif my > items_rect.bottom:
                    _past = my - items_rect.bottom
                    _speed = max(60, 120 - int(60 * min(_past, _ZONE) / _ZONE))
                    _delta = 1

                if _delta and (_now_t - _last_t) >= _speed:
                    _cur_sc = max(0, min(_max_sc, _cur_sc + _delta))
                    app_state["file_explorer_scroll"] = _cur_sc
                    app_state["_fe_drag_scroll_t"]    = _now_t

                _anchor  = app_state.get("file_explorer_sel_anchor", 0)
                if my <= items_rect.y:
                    _cur_idx = _cur_sc               # above list → top visible item
                elif my >= items_rect.bottom:
                    _cur_idx = _cur_sc + _vis - 1    # below list → bottom visible item
                else:
                    # Same float-leak as idx_at() above: my can be a Bezel-
                    # scaled float here, so force a clean int index.
                    _cur_idx = _cur_sc + int((my - items_rect.y) // _FE_ROW_H)
                _cur_idx = max(0, min(_n - 1, _cur_idx))
                _lo, _hi = min(_anchor, _cur_idx), max(_anchor, _cur_idx)
                app_state["file_explorer_selection"] = set(range(_lo, _hi + 1))

    elif event.type == pygame.MOUSEBUTTONUP and event.button == 1:
        app_state["file_explorer_drag_start"] = None
        app_state["file_explorer_drag_cur"]   = None
        app_state["file_explorer_sb_drag"]    = None

    elif event.type == pygame.MOUSEWHEEL:
        _wmx, _wmy = _real_to_virtual_pos(pygame.mouse.get_pos())
        if left_rect.collidepoint(_wmx, _wmy):
            _rows1, _rows2 = _fe_left_layout(content_h)
            _n1 = len(_fe_get_this_pc_items())
            _n2 = len(_fe_get_quick_access_items())
            _sec1_items_y = content_y + _FE_LEFT_ROW_H
            _sec1_items_h = _rows1 * _FE_LEFT_ROW_H
            _sec2_items_y = _sec1_items_y + _sec1_items_h + _FE_LEFT_ROW_H
            _sec2_items_h = _rows2 * _FE_LEFT_ROW_H
            if _sec1_items_y <= _wmy < _sec1_items_y + _sec1_items_h:
                _max_sc = max(0, _n1 - _rows1)
                _sc     = app_state.get("file_explorer_left_scroll_pc", 0)
                app_state["file_explorer_left_scroll_pc"] = max(0, min(_max_sc, _sc - event.y * 3))
            elif _sec2_items_y <= _wmy < _sec2_items_y + _sec2_items_h:
                _max_sc = max(0, _n2 - _rows2)
                _sc     = app_state.get("file_explorer_left_scroll_qa", 0)
                app_state["file_explorer_left_scroll_qa"] = max(0, min(_max_sc, _sc - event.y * 3))
        else:
            n = len(items)
            visible_rows = max(1, (app_state.get("file_explorer_rect", (0,0,0,500))[3] - _FE_HEADER_H - _FE_FOOTER_H - _FE_COL_H) // _FE_ROW_H)
            max_scroll = max(0, n - visible_rows)
            app_state["file_explorer_scroll"] = max(0, min(max_scroll, scroll - event.y * 3))


def _fe_render(screen, active_theme, fe_rect):
    """Render the Windows-style file explorer overlay."""
    import colorsys as _fecs
    fx, fy, fw, fh = fe_rect
    app_state["file_explorer_rect"] = fe_rect

    ui_hue   = db.config.get("theme_ui_hue", 140) / 360.0 if db else 0.39
    bg_hue   = db.config.get("theme_bg_hue", 220) / 360.0 if db else 0.61
    _r,_g,_b = _fecs.hsv_to_rgb(ui_hue, 0.88, 1.0)
    UI_C     = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.55, 0.10)
    BG_C     = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.45, 0.16)
    PANEL_C  = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(ui_hue, 0.65, 0.50)
    SEL_C    = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.35, 0.14)
    ITEM_BG  = (int(_r*255), int(_g*255), int(_b*255))
    WHITE    = (255, 255, 255)
    GREY     = (150, 150, 150)
    ADDED_C  = UI_C   # "added/checked" file-name color follows the theme's UI accent, not a fixed green
    LOCKED_C = (255, 170, 60)  # Currently playing file.

    bg_alpha = min(255, int((db.config.get("menu_opacity", 50) / 100.0) * 255) + 90) if db else 235

    content_y = fy + _FE_HEADER_H
    content_h = fh - _FE_HEADER_H - _FE_FOOTER_H
    right_x   = fx + _FE_LEFT_W + 1
    right_w   = fw - _FE_LEFT_W - 1 - _FE_ADDLOC_PANEL_W - 1
    rp_x      = right_x + right_w + 1                          # Add Location panel x
    rp_w      = _FE_ADDLOC_PANEL_W
    items_y   = content_y + _FE_COL_H
    items_h   = content_h - _FE_COL_H
    footer_y  = fy + fh - _FE_FOOTER_H
    tb_y      = fy + _FE_TITLE_H
    visible   = max(1, items_h // _FE_ROW_H)

    items    = app_state.get("file_explorer_items", [])
    scroll   = app_state.get("file_explorer_scroll", 0)
    sel      = app_state.get("file_explorer_selection", set())
    checked  = app_state.get("file_explorer_checked", [])
    cwd      = app_state.get("file_explorer_cwd")
    title    = app_state.get("file_explorer_title", "FILE BROWSER")
    left_sel = app_state.get("file_explorer_left_sel", -1)
    drag_s   = app_state.get("file_explorer_drag_start")
    drag_c   = app_state.get("file_explorer_drag_cur")
    # Real, post-Bezel-composite mouse position converted back to the
    # virtual-canvas coordinates every hover/highlight rect below is
    # defined in -- with Bezel on, the raw position doesn't line up with
    # anything drawn here anymore (see _real_to_virtual_pos).
    mx, my   = _real_to_virtual_pos(pygame.mouse.get_pos(), screen)

    bg = pygame.Surface((fw, fh), pygame.SRCALPHA)
    bg.fill(BG_C + (bg_alpha,))
    screen.blit(bg, (fx, fy))

    tb_surf = pygame.Surface((fw, _FE_TITLE_H), pygame.SRCALPHA)
    tb_surf.fill(UI_C + (80,))
    screen.blit(tb_surf, (fx, fy))
    f_title = _cached_sys_font("Courier New", 20, bold=True)
    t_lbl   = f_title.render(title, True, WHITE)
    screen.blit(t_lbl, (fx + 12, fy + (_FE_TITLE_H - t_lbl.get_height()) // 2))

    pygame.draw.rect(screen, (10, 10, 10), (fx, tb_y, fw, _FE_TOOLBAR_H))
    up_rect = pygame.Rect(fx + 6, tb_y + (_FE_TOOLBAR_H - 30) // 2, 60, 30)
    is_up   = up_rect.collidepoint(mx, my)
    pygame.draw.rect(screen, UI_C if is_up else (40, 40, 40), up_rect)
    pygame.draw.rect(screen, UI_C, up_rect, 1)
    f_sm  = _cached_sys_font("Courier New", 16, bold=True)
    up_lbl = f_sm.render("UP ^", True, WHITE)
    screen.blit(up_lbl, (up_rect.x + (up_rect.w - up_lbl.get_width()) // 2,
                          up_rect.y + (up_rect.h - up_lbl.get_height()) // 2))
    pb_x    = up_rect.right + 6
    pb_h    = 30
    pb_rect = pygame.Rect(pb_x, tb_y + (_FE_TOOLBAR_H - pb_h) // 2, fw - (pb_x - fx) - 6, pb_h)
    pygame.draw.rect(screen, (18, 18, 18), pb_rect)
    pygame.draw.rect(screen, (60, 60, 60), pb_rect, 1)
    path_tx = cwd if cwd else "Computer"
    f_path  = _cached_sys_font("Courier New", 16, bold=True)
    p_lbl   = f_path.render(path_tx, True, UI_C)
    clip_s  = pygame.Surface((pb_rect.w - 8, pb_rect.h), pygame.SRCALPHA)
    clip_s.fill((0, 0, 0, 0))
    clip_s.blit(p_lbl, (0, (pb_rect.h - p_lbl.get_height()) // 2))
    screen.blit(clip_s, (pb_rect.x + 4, pb_rect.y))

    lp = pygame.Surface((_FE_LEFT_W, content_h), pygame.SRCALPHA)
    lp.fill(PANEL_C + (bg_alpha,))
    screen.blit(lp, (fx, content_y))
    pygame.draw.line(screen, (50, 50, 50), (fx + _FE_LEFT_W, content_y), (fx + _FE_LEFT_W, content_y + content_h), 1)

    f_lhdr = _cached_sys_font("Courier New", 14, bold=True)
    f_litem = _cached_sys_font("Courier New", 18, bold=True)
    f_btn_sym = _cached_sys_font("Courier New", 19, bold=True)

    def _fe_draw_left_section(hdr_label, hdr_y, items_y, items_h, items_list, scroll_key):
        # Header (fixed)
        pygame.draw.rect(screen, (8, 8, 8), (fx, hdr_y, _FE_LEFT_W, _FE_LEFT_ROW_H))
        hlbl = f_lhdr.render("  " + hdr_label.upper(), True, (100, 100, 100))
        screen.blit(hlbl, (fx + 2, hdr_y + (_FE_LEFT_ROW_H - hlbl.get_height()) // 2))

        rows   = items_h // _FE_LEFT_ROW_H
        n      = len(items_list)
        max_sc = max(0, n - rows)
        scroll = max(0, min(max_sc, app_state.get(scroll_key, 0)))
        app_state[scroll_key] = scroll

        for row_i in range(rows):
            idx = scroll + row_i
            if idx >= n:
                break
            li = items_list[idx]
            ly = items_y + row_i * _FE_LEFT_ROW_H
            is_lhov    = (fx <= mx < fx + _FE_LEFT_W and ly <= my < ly + _FE_LEFT_ROW_H)
            is_lactive = (li["path"] == left_sel)
            row_w = _FE_LEFT_W - 12   # leave room for this section's scrollbar
            if is_lactive:
                pygame.draw.rect(screen, SEL_C, (fx, ly, row_w, _FE_LEFT_ROW_H))
            elif is_lhov:
                hs = pygame.Surface((row_w, _FE_LEFT_ROW_H), pygame.SRCALPHA)
                hs.fill(UI_C + (45,))
                screen.blit(hs, (fx, ly))
            tc_l   = WHITE if (is_lactive or is_lhov) else (200, 200, 200)
            lbl    = _fe_cached_label(f_litem, "  " + "  " * li["indent"] + li["label"], tc_l)
            # Clip to row_w so long folder names never bleed into the right panel
            _lp_old_clip = screen.get_clip()
            screen.set_clip(pygame.Rect(fx, ly, row_w, _FE_LEFT_ROW_H))
            screen.blit(lbl, (fx + 2, ly + (_FE_LEFT_ROW_H - lbl.get_height()) // 2))
            screen.set_clip(_lp_old_clip)

        if items_h > 0:
            lsb_x = fx + _FE_LEFT_W - 10
            pygame.draw.rect(screen, (28, 28, 28), (lsb_x, items_y, 8, items_h))
            if n > rows and rows > 0:
                lth = max(20, items_h * rows // max(1, n))
                lty = items_y + (items_h - lth) * scroll // max(1, n - rows)
            else:
                lth = items_h
                lty = items_y
            pygame.draw.rect(screen, UI_C, (lsb_x, lty, 8, lth))

    rows1, rows2 = _fe_left_layout(content_h)
    pc_items = _fe_get_this_pc_items()
    qa_items = _fe_get_quick_access_items()
    sec1_hdr_y   = content_y
    sec1_items_y = content_y + _FE_LEFT_ROW_H
    sec1_items_h = rows1 * _FE_LEFT_ROW_H
    sec2_hdr_y   = sec1_items_y + sec1_items_h
    sec2_items_y = sec2_hdr_y + _FE_LEFT_ROW_H
    sec2_items_h = rows2 * _FE_LEFT_ROW_H

    _fe_draw_left_section("This PC", sec1_hdr_y, sec1_items_y, sec1_items_h,
                           pc_items, "file_explorer_left_scroll_pc")
    _fe_draw_left_section("Quick Access", sec2_hdr_y, sec2_items_y, sec2_items_h,
                           qa_items, "file_explorer_left_scroll_qa")

    pygame.draw.rect(screen, (15, 15, 15), (right_x, content_y, right_w, _FE_COL_H))
    pygame.draw.line(screen, (45, 45, 45), (right_x, content_y + _FE_COL_H - 1),
                     (right_x + right_w, content_y + _FE_COL_H - 1), 1)
    f_col = _cached_sys_font("Courier New", 16, bold=True)
    screen.blit(f_col.render("Name", True, GREY), (right_x + 8, content_y + (_FE_COL_H - f_col.size("Name")[1]) // 2))

    alp = pygame.Surface((rp_w, content_h), pygame.SRCALPHA)
    alp.fill(PANEL_C + (bg_alpha,))
    screen.blit(alp, (rp_x, content_y))
    pygame.draw.line(screen, (45, 45, 45), (rp_x, content_y), (rp_x, content_y + content_h), 1)

    pygame.draw.rect(screen, (8, 8, 8), (rp_x, content_y, rp_w, _FE_ADDLOC_HDR_H))
    f_rphdr = _cached_sys_font("Courier New", 14, bold=True)
    rphdr_lbl = f_rphdr.render("SAVED LOCATIONS", True, (100, 100, 100))
    screen.blit(rphdr_lbl, (rp_x + (rp_w - rphdr_lbl.get_width()) // 2,
                             content_y + (_FE_ADDLOC_HDR_H - rphdr_lbl.get_height()) // 2))

    saved_locs = _fe_get_saved_locations()
    rows_top   = _fe_get_saved_rows_top(content_y)
    panel_bottom = content_y + content_h
    for i, p in enumerate(saved_locs):
        ly = rows_top + i * _FE_LEFT_ROW_H
        if ly + _FE_LEFT_ROW_H > panel_bottom:
            break
        is_rhov = (rp_x <= mx < rp_x + rp_w and ly <= my < ly + _FE_LEFT_ROW_H)
        row_w   = rp_w - _FE_LEFT_REMOVE_W
        if is_rhov:
            hs = pygame.Surface((row_w, _FE_LEFT_ROW_H), pygame.SRCALPHA)
            hs.fill(UI_C + (45,))
            screen.blit(hs, (rp_x, ly))
        label = os.path.basename(p.rstrip("\\/")) or p
        lbl = _fe_cached_label(f_litem, "  " + label, (200, 200, 200) if not is_rhov else WHITE)
        _rp_old_clip = screen.get_clip()
        screen.set_clip(pygame.Rect(rp_x, ly, row_w, _FE_LEFT_ROW_H))
        screen.blit(lbl, (rp_x + 2, ly + (_FE_LEFT_ROW_H - lbl.get_height()) // 2))
        screen.set_clip(_rp_old_clip)

        rm_x    = rp_x + rp_w - _FE_LEFT_REMOVE_W
        rm_rect = pygame.Rect(rm_x, ly, _FE_LEFT_REMOVE_W, _FE_LEFT_ROW_H)
        is_rmhov = rm_rect.collidepoint(mx, my)
        if is_rmhov:
            hs = pygame.Surface((_FE_LEFT_REMOVE_W, _FE_LEFT_ROW_H), pygame.SRCALPHA)
            hs.fill((180, 40, 40, 90))
            screen.blit(hs, (rm_x, ly))
        minus_clr = (255, 120, 120) if is_rmhov else (130, 70, 70)
        mlbl = _fe_cached_label(f_btn_sym, "-", minus_clr)
        screen.blit(mlbl, (rm_x + (_FE_LEFT_REMOVE_W - mlbl.get_width()) // 2,
                           ly + (_FE_LEFT_ROW_H - mlbl.get_height()) // 2))

    addloc_rect = _fe_get_addloc_rect(rp_x, rp_w, content_y, content_h)
    is_addloc_hov = addloc_rect.collidepoint(mx, my)
    addloc_bc = (40, 80, 150) if is_addloc_hov else (25, 50, 95)
    pygame.draw.rect(screen, addloc_bc, addloc_rect)
    pygame.draw.rect(screen, UI_C, addloc_rect, 1)
    f_addloc = _cached_sys_font("Courier New", 15, bold=True)
    addloc_lbl = f_addloc.render("+ Add Location", True, WHITE)
    screen.blit(addloc_lbl, (addloc_rect.x + (addloc_rect.w - addloc_lbl.get_width()) // 2,
                              addloc_rect.y + (addloc_rect.h - addloc_lbl.get_height()) // 2))

    ib = pygame.Surface((right_w, items_h), pygame.SRCALPHA)
    ib.fill(ITEM_BG + (bg_alpha,))
    screen.blit(ib, (right_x, items_y))

    f_dir  = _cached_sys_font("Courier New", 22, bold=True)
    f_file = _cached_sys_font("Courier New", 22, bold=True)

    _rsw   = right_w - 12
    _sc_key = (_rsw, _FE_ROW_H, SEL_C, UI_C)
    if app_state.get("_fe_surf_cache_key") != _sc_key:
        app_state["_fe_surf_cache_key"] = _sc_key
        _a = pygame.Surface((_rsw, _FE_ROW_H), pygame.SRCALPHA)
        _a.fill((255, 255, 255, 8))
        app_state["_fe_surf_alt"] = _a
        _s = pygame.Surface((_rsw, _FE_ROW_H), pygame.SRCALPHA)
        _s.fill(SEL_C + (185,))
        app_state["_fe_surf_sel"] = _s
        _h = pygame.Surface((_rsw, _FE_ROW_H), pygame.SRCALPHA)
        _h.fill(UI_C + (35,))
        app_state["_fe_surf_hov"] = _h
    _alt_surf = app_state.get("_fe_surf_alt")
    _sel_surf = app_state.get("_fe_surf_sel")
    _hov_surf = app_state.get("_fe_surf_hov")

    _fe_ctx = app_state.get("file_explorer_context", {})
    _locked_path = _fe_locked_playing_path(_fe_ctx)

    # In the "Select Libretro Core" / "Add BIOS" browsers, figure out which
    # file in the console's managed folder is the live/active one right
    # now -- whether that's the user's saved pick or (if none saved yet)
    # whichever file the relevant auto-pick fallback would use -- so it
    # can be highlighted below.
    _active_managed_path = None
    if _fe_ctx.get("mode") == "libretro_core":
        _active_console = _fe_ctx.get("console_key", "")
        _active_folder  = _fe_ctx.get("emu_folder", "")
        if _active_console and _active_folder and cwd and os.path.normpath(cwd) == os.path.normpath(_active_folder):
            _active_name = _fe_resolve_active_core_name(_active_console, _active_folder)
            if _active_name:
                _active_managed_path = os.path.normpath(os.path.join(_active_folder, _active_name))
    elif _fe_ctx.get("mode") == "add_bios":
        _active_console = _fe_ctx.get("console_key", "")
        _active_folder  = _fe_ctx.get("bios_dir", "")
        if _active_console and _active_folder and cwd and os.path.normpath(cwd) == os.path.normpath(_active_folder):
            _active_name = _fe_resolve_active_bios_name(_active_console, _active_folder)
            if _active_name:
                _active_managed_path = os.path.normpath(os.path.join(_active_folder, _active_name))

    # Which visible folders contain a checked/added file somewhere inside
    # them (at any depth) -- lets the left edge of a folder row hint "there's
    # added content in here" without having to open every folder to check.
    _checked_dirs = set()
    if checked:
        for _cp in checked:
            _d = os.path.dirname(_cp)
            while _d and _d not in _checked_dirs:
                _checked_dirs.add(_d)
                _parent = os.path.dirname(_d)
                if _parent == _d:
                    break
                _d = _parent

    for i in range(visible):
        idx   = scroll + i
        if idx >= len(items):
            break
        item  = items[idx]
        row_y = items_y + i * _FE_ROW_H
        is_sel = idx in sel
        item_path = item.get("path", "")
        is_chk = item_path in checked
        t      = item["type"]
        is_dir = (t == "dir")
        is_locked = bool(_locked_path) and (not is_dir) and os.path.normpath(item_path) == _locked_path
        is_active_item = bool(_active_managed_path) and (not is_dir) and os.path.normpath(item_path) == _active_managed_path
        has_added_inside = is_dir and os.path.normpath(item_path) in _checked_dirs
        is_hov = (right_x <= mx < right_x + right_w - 12 and row_y <= my < row_y + _FE_ROW_H and not drag_s)

        if i % 2 == 1 and _alt_surf:
            screen.blit(_alt_surf, (right_x, row_y))
        if is_sel and _sel_surf:
            screen.blit(_sel_surf, (right_x, row_y))
        elif is_hov and _hov_surf:
            screen.blit(_hov_surf, (right_x, row_y))

        # No more "[*] " bracket prefix for "has added content inside" --
        # a folder row now shows that state by lighting up its own folder
        # icon instead (see _fe_draw_folder_icon below). "[+]"/"[A]" still
        # mark a directly-checked or actively-managed item either way.
        prefix = "[+] " if is_chk else ("[A] " if is_active_item else "")
        f_use  = f_dir if is_dir else f_file
        if is_sel:
            tc_row = (200, 225, 255)
        elif is_locked:
            tc_row = LOCKED_C
        elif is_chk or is_active_item:
            tc_row = ADDED_C
        else:
            tc_row = WHITE

        # Reserve a fixed icon column ahead of every row's text so names
        # stay aligned whether or not that row draws an icon -- only
        # directories get one (files leave the column blank), which is
        # what actually keeps folders from blending in with files.
        text_x = right_x + 4 + _FE_ICON_W + _FE_ICON_GAP
        if is_dir:
            icon_c = ADDED_C if (has_added_inside or is_chk) else GREY
            _fe_draw_folder_icon(screen, right_x + 4, row_y + (_FE_ROW_H - _FE_ICON_H) // 2, icon_c)

        name_lbl = _fe_cached_label(
            f_use, prefix + item["name"] + (" \u25cf NOW PLAYING" if is_locked else ""), tc_row)
        # screen.set_clip clips the blit without allocating a new surface
        _old_clip = screen.get_clip()
        screen.set_clip(pygame.Rect(right_x + 4, row_y, right_w - 12, _FE_ROW_H))
        screen.blit(name_lbl, (text_x, row_y + (_FE_ROW_H - name_lbl.get_height()) // 2))
        screen.set_clip(_old_clip)

    sb_x = right_x + right_w - 10
    pygame.draw.rect(screen, (28, 28, 28), (sb_x, items_y, 8, items_h))
    _sb_thumb = _fe_scrollbar_thumb_rect(sb_x, items_y, items_h, len(items), visible, scroll)
    th, ty = _sb_thumb.h, _sb_thumb.y
    pygame.draw.rect(screen, UI_C, (sb_x, ty, 8, th))

    # Drag selection rect
    if drag_s and drag_c:
        sx, sy = drag_s
        ex, ey = drag_c
        if abs(ex - sx) > 3 or abs(ey - sy) > 3:
            rx, ry = min(sx, ex), min(sy, ey)
            rw, rh = abs(ex - sx), abs(ey - sy)
            dr = pygame.Surface((max(1, rw), max(1, rh)), pygame.SRCALPHA)
            dr.fill(UI_C + (40,))
            screen.blit(dr, (rx, ry))
            pygame.draw.rect(screen, UI_C, (rx, ry, rw, rh), 1)

    pygame.draw.line(screen, UI_C, (fx, footer_y), (fx + fw, footer_y), 1)
    pygame.draw.rect(screen, (10, 10, 10), (fx, footer_y, fw, _FE_FOOTER_H))
    n_chk = len(checked)
    f_cnt = _cached_sys_font("Courier New", 17, bold=True)
    c_clr = ADDED_C if n_chk > 0 else GREY
    _fe_ctx_mode = _fe_ctx.get("mode", "")
    if _fe_ctx_mode == "rom_folder_relocate":
        if n_chk > 0:
            cnt_txt = f"{n_chk} ROM(s) found — folder selected"
        else:
            cnt_txt = "Select a folder, then click ADD SELECTED"
    elif _fe_ctx_mode == "scan_for_roms":
        if n_chk > 0:
            _matched = _fe_ctx.get("picked_rom_count", 0)
            if _matched > 0:
                cnt_txt = f"{_matched} console folder(s) matched — click DONE to scan"
            else:
                cnt_txt = "Folder selected — click DONE to scan"
        else:
            cnt_txt = "Select a folder, then click ADD SELECTED"
    elif _fe_ctx_mode == "scan_for_cores":
        if n_chk > 0:
            _matched = _fe_ctx.get("picked_rom_count", 0)
            if _matched > 0:
                cnt_txt = f"{_matched} core .dll(s) matched — click DONE to scan"
            else:
                cnt_txt = "Folder selected — click DONE to scan"
        else:
            cnt_txt = "Select a folder, then click ADD SELECTED"
    else:
        _fe_scheduling_mode = _fe_ctx_mode in ("schedule", "commercial", "holiday", "add_roms", "ch03_menu_music")
        _cnt_word = "scheduled" if _fe_scheduling_mode else "queued"
        _item_word = "rom(s)" if _fe_ctx_mode == "add_roms" else "file(s)"
        cnt_txt = f"{n_chk} {_item_word} {_cnt_word}   |   {len(sel)} currently selected"
    cnt_lbl = f_cnt.render(cnt_txt, True, c_clr)
    screen.blit(cnt_lbl, (fx + (fw - cnt_lbl.get_width()) // 2, footer_y + 18))

    f_btn   = _cached_sys_font("Courier New", 19, bold=True)
    labels  = {"cancel": "CANCEL", "remove_sel": "REMOVE SELECTED", "add_sel": "ADD SELECTED", "done": "DONE"}
    for rect, key in _fe_get_btn_rects(fx, fy, fw, fh):
        is_hov = rect.collidepoint(mx, my)
        if key == "cancel":
            bc = (210, 50, 50) if is_hov else (80, 20, 20)
        elif key == "remove_sel":
            bc = (200, 100, 30) if is_hov else (100, 50, 10)
        elif key == "done":
            bc = UI_C if is_hov else (20, 70, 20)
        else:
            bc = (40, 80, 150) if is_hov else (25, 50, 95)
        pygame.draw.rect(screen, bc, rect)
        pygame.draw.rect(screen, UI_C, rect, 1)
        lum = bc[0]*299 + bc[1]*587 + bc[2]*114
        bl  = f_btn.render(labels[key], True, (0, 0, 0) if lum > 128000 else WHITE)
        screen.blit(bl, (rect.x + (rect.w - bl.get_width()) // 2, rect.y + (rect.h - bl.get_height()) // 2))

    pending    = app_state.get("file_explorer_expand_pending", 0)
    started_ms = app_state.get("file_explorer_expand_started_ms", 0)
    scan_pending    = app_state.get("file_explorer_scan_pending", False)
    scan_started_ms = app_state.get("file_explorer_scan_started_ms", 0)
    _done_waiting = app_state.get("file_explorer_done_requested", False)
    if pending > 0 and started_ms and (
            _done_waiting or (pygame.time.get_ticks() - started_ms) >= 1000):
        # No 1s debounce once DONE has actually been clicked and is waiting
        # on this -- the user needs to see it's working, not guess whether
        # their click registered.
        _fe_draw_busy_overlay(screen, fx, fy, fw, fh, UI_C, PANEL_C, BG_C,
                               "FINISHING FOLDER SCAN..." if _done_waiting else "PROCESSING FILES...")
    elif scan_pending and scan_started_ms and (
            _done_waiting or (pygame.time.get_ticks() - scan_started_ms) >= 150):
        # Same no-debounce-once-DONE-is-waiting treatment as above, for a
        # plain folder-listing scan (e.g. DONE pressed right after navigating
        # into a splash-video folder, before the read has come back).
        _fe_draw_busy_overlay(screen, fx, fy, fw, fh, UI_C, PANEL_C, BG_C,
                               "FINISHING FOLDER SCAN..." if _done_waiting else "READING FOLDER...")

    if app_state.get("file_explorer_bulkscan_pending", False):
        # DONE was already clicked to get here -- show immediately, same as
        # the _done_waiting case above, instead of the normal 1s debounce.
        # Unlike the two overlays above, this one has a real denominator
        # (see bulk_scan_for_roms' progress_cb) so it shows an actual % and
        # a rough ETA instead of an indeterminate bounce -- a big rom
        # collection can take a while and people were left guessing how
        # much longer it had left.
        _bs_done, _bs_total = app_state.get("file_explorer_bulkscan_progress", (0, 0))
        _bs_started_ms = app_state.get("file_explorer_bulkscan_started_ms", 0)
        _bs_label = "FOLDER SCAN..."
        _bs_frac  = None
        if _bs_total > 0:
            _bs_frac = min(1.0, _bs_done / _bs_total)
            _bs_label = f"FOLDER SCAN... {int(_bs_frac * 100)}%"
        _fe_draw_busy_overlay(screen, fx, fy, fw, fh, UI_C, PANEL_C, BG_C,
                               _bs_label, progress_fraction=_bs_frac)

    pygame.draw.rect(screen, UI_C, (fx, fy, fw, fh), 2)


def _fe_draw_busy_overlay(screen, fx, fy, fw, fh, ui_c, panel_c, bg_c, label="PROCESSING FILES...",
                           progress_fraction=None):
    """`progress_fraction` (0.0-1.0) draws a real fill bar instead of the
    default indeterminate bounce -- used only by the bulk "Scan For Roms"
    caller, which has an actual denominator to show. Every other caller
    passes nothing and keeps the original bounce, unchanged."""
    box_w, box_h = 340, 92
    bx = fx + (fw - box_w) // 2
    by = fy + (fh - box_h) // 2

    # Dim the whole explorer a bit so the box reads as sitting on top of it.
    dim = pygame.Surface((fw, fh), pygame.SRCALPHA)
    dim.fill((0, 0, 0, 90))
    screen.blit(dim, (fx, fy))

    pygame.draw.rect(screen, panel_c, (bx, by, box_w, box_h))
    pygame.draw.rect(screen, ui_c, (bx, by, box_w, box_h), 2)

    f_lbl = _cached_sys_font("Courier New", 18, bold=True)
    lbl   = f_lbl.render(label, True, ui_c)
    screen.blit(lbl, (bx + (box_w - lbl.get_width()) // 2, by + 16))

    track_w, track_h = box_w - 40, 14
    tx = bx + 20
    ty = by + box_h - 18 - track_h
    pygame.draw.rect(screen, bg_c, (tx, ty, track_w, track_h))
    pygame.draw.rect(screen, ui_c, (tx, ty, track_w, track_h), 1)

    if progress_fraction is not None:
        # Determinate: a real fill from 0 to the given fraction.
        fill_w = int(track_w * max(0.0, min(1.0, progress_fraction)))
        if fill_w > 0:
            pygame.draw.rect(screen, ui_c, (tx, ty, fill_w, track_h))
    else:
        # Indeterminate bar: a chunk that bounces back and forth across the track.
        chunk_w   = max(30, track_w // 3)
        period_ms = 1100
        t     = (pygame.time.get_ticks() % period_ms) / period_ms
        phase = t * 2
        if phase > 1:
            phase = 2 - phase   # ping-pong 0 -> 1 -> 0 instead of snapping back
        chunk_x = tx + int((track_w - chunk_w) * phase)
        pygame.draw.rect(screen, ui_c, (chunk_x, ty, chunk_w, track_h))



